-- ===== Acadian Redfish / Ocean Perch (acadian-redfish) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('acadian-redfish', 'Acadian Redfish / Ocean Perch', 'Sebastes fasciatus / Sebastes mentella', 'saltwater', '{"NB","NS","PEI"}'::text[], 'A deepwater rockfish (70-500m, mostly 150-300m) found off the Bay of Fundy, Scotian Shelf, and Gulf of St. Lawrence. A major commercial fishery reopened in 2024 after a 30-year moratorium, but this is essentially not a shore or inshore recreational species in NB/NS/PEI, and no province-specific recreational bag limit for redfish turns up in current DFO notices.', '/species/acadian-redfish.jpg', 'Steven G. Johnson', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Acadian_redfish.jpg', true, now())
