insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'acadian-redfish'), 6, 'If you catch one', 'Use a descending device for release — barotrauma from depth is severe and near-certain fatal without one');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'acadian-redfish'), 7, 'Regulatory confidence', 'LOW — this is the fastest-changing, least-documented species in this guide; call DFO to confirm current rules');
