insert into species_sources (species_id, label, url) values ((select id from species where slug = 'acadian-redfish'), 'Fisheries (Oxford/Wiley), Conserving Rockfishes: Barotrauma and Descending Devices in the Northeast Pacific', 'https://academic.oup.com/fisheries/article/47/9/406/7816660');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'acadian-redfish'), 0, 'Deepwater/Beaked Redfish', 'related-species', 'Sebastes mentella', 'Externally near-identical to Acadian redfish and not practically distinguishable boat-side. The reliable check is anal fin soft-ray count (typically 8 in S. mentella vs typically 7 in S. fasciatus) and dorsal fin soft-ray count (usually 14-15 vs 14 in fasciatus) — both require careful fin counting, not a glance. Depth is a rough guide: S. mentella tends to sit deeper (roughly 300-500m+, sometimes to 1,000m+) than S. fasciatus.', 'More transatlantic in distribution and generally deeper on the continental slope than S. fasciatus, though ranges overlap broadly through the Gulf of St. Lawrence and Scotian Shelf.', 'Both species are managed and sold together as "redfish"/"ocean perch" with no separate recreational rule — the distinction is scientific/commercial bookkeeping, not something that changes what an angler does with a fish in hand.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'acadian-redfish'), 1, 'Golden Redfish', 'related-species', 'Sebastes norvegicus', 'The third "redfish" species present in the Northwest Atlantic, distinguished from the two beaked-redfish species (fasciatus/mentella) by a much-reduced symphyseal tubercle (the small bony knob at the tip of the lower jaw, prominent on the other two species) and typically 15 dorsal fin soft rays. Like fasciatus vs. mentella, this is a fin-count and jaw-detail distinction, not something visible at a glance.', 'Continental shelf and slope waters generally in the 100-300m range, overlapping with both other redfish species in this region.', 'Sold and regulated identically to Acadian and deepwater redfish under the same "redfish"/"ocean perch" umbrella — no separate recreational bag limit or rule exists for it.', '/species/acadian-redfish--variant-1.jpg', 'User:Tanzania', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Sebastes_norvegicus.jpeg');

-- ===== American Eel (american-eel) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('american-eel', 'American Eel', 'Anguilla rostrata', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Snake-like, bottom-oriented estuary fish caught on stationary bait rather than lures, found in nearly every tidal river system in NB/NS/PEI; a species in long-term decline that''s worth fishing conservatively despite no formal at-risk listing.', '/species/american-eel.jpg', 'USFWS Mountain Prairie', 'Public domain', 'https://commons.wikimedia.org/wiki/File:American_Eel_(Anguilla_rostrata)_-_white_background.jpg', true, now())
