insert into species_sources (species_id, label, url) values ((select id from species where slug = 'american-eel'), 'DFO — Recreational Groundfish Fishery, Southern Gulf of St. Lawrence', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'american-eel'), 0, 'Glass Eel', 'life-stage', NULL, 'The first stage after the leaf-shaped ocean larva (leptocephalus) transforms on the continental shelf — fully transparent, with no pigment yet, typically found right at the head of the estuary as they arrive from the sea.', 'River mouths and lower estuaries across NB and NS in spring, as they arrive from the Sargasso Sea.', 'Not legal to target recreationally. Glass eels feed the licensed commercial elver fishery (see Elver entry below) — recreational anglers have no legal path to harvest this stage.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'american-eel'), 1, 'Elver', 'life-stage', NULL, 'A glass eel that has started picking up pigment (a "smoky" tint) as it pushes further upriver toward fresh water — defined under federal regulation as any American eel under 10 cm in length.', 'Estuaries and lower rivers across NB and NS during the spring run, closer to head-of-tide than glass eels.', 'The elver fishery is a tightly licensed, limited-entry commercial fishery in the Maritimes, now valued at tens of millions of dollars a year and among the most valuable fish by weight sold in Canada. It is NOT open to recreational anglers under any circumstance — the Maritime Provinces Fishery Regulations explicitly prohibit recreational elver fishing. Do not attempt to catch, net, or possess elvers without a commercial licence.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'american-eel'), 2, 'Yellow Eel', 'life-stage', NULL, 'The long-lived growth stage anglers actually catch on hook and line — greenish-yellow to olive-brown, typically 8-20+ inches, and can remain in this stage for 3 to 30+ years before maturing further.', 'Every tidal estuary and connected river system across NB, NS, and PEI covered elsewhere in this guide — this is the stage targeted by the bottom-bait technique described above.', 'This is the legal recreational stage, subject to the bag/size limits in the regulations table above (e.g., 35 cm minimum size, daily bag limits by region).', '/species/american-eel--variant-2.jpg', 'USFWS Mountain Prairie', 'Public domain', 'https://commons.wikimedia.org/wiki/File:American_Eel_(Anguilla_rostrata)_-_white_background.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'american-eel'), 3, 'Silver Eel', 'life-stage', NULL, 'The final, mature migratory stage: eyes enlarge, the body shifts from yellow-green to a dark gray back with a silvery-white belly and flanks, and reproductive organs develop ahead of the one-way trip back to the Sargasso Sea to spawn and die.', 'Encountered in the same rivers as yellow eels, typically in fall as maturing fish stage for their downstream migration to the sea.', 'Still the same legally-fishable species and stage as yellow eel under current regulations, but consider releasing silver-phase fish specifically — they represent the population''s active spawning migration back to the Sargasso Sea, and given the species'' long-term decline, letting mature fish complete that migration matters more than for a younger yellow eel.', NULL, NULL, NULL, NULL);

-- ===== American Shad (american-shad) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('american-shad', 'American Shad', 'Alosa sapidissima', 'saltwater', '{"NB","NS"}'::text[], 'A hard-fighting anadromous herring relative that runs up Maritime rivers by the tens of thousands each spring — the Saint John River near Mactaquac in New Brunswick and several Nova Scotia rivers, especially the Annapolis, are the region''s best-known runs. Often called "the poor man''s salmon" for the sport it offers on light tackle.', NULL, NULL, NULL, NULL, true, now())
