insert into species_sources (species_id, label, url) values ((select id from species where slug = 'american-shad'), 'DFO Maritimes Region, Tidal and freshwater (Diadromous) recreational fisheries', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'american-shad'), 0, 'Alewife (Gaspereau)', 'lookalike', 'Alosa pseudoharengus', 'Size is the fastest check: American shad run much larger, with adult females reaching up to 30 inches, while alewife top out around 7-9 oz — smaller than any legal-size shad. The jaw is the definitive check on a fish in hand: a shad''s lower jaw rises in a gradual slope and tucks into a notch under the upper jaw, while an alewife''s (and blueback herring''s) lower jaw juts upward sharply in a bent, shovel-like angle.', 'Alewife run the same rivers at the same time as American shad throughout NB and NS — the Saint John River and Annapolis system carry both runs concurrently in spring.', 'Regulatory and conservation status differ: American shad is a COSEWIC prioritized candidate species under active review, while alewife (gaspereau) supports an active commercial fishery in Nova Scotia. Confirm which species you have before assuming either species'' rules apply.', '/species/american-shad--variant-0.jpg', 'Unknown author', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Alosa_pseudoharengus.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'american-shad'), 1, 'Blueback Herring (Gaspereau)', 'lookalike', 'Alosa aestivalis', 'Same size difference as alewife applies here: blueback herring reach only about a pound, far smaller than a legal adult American shad. The jaw check is identical too — a shad''s lower jaw slopes gradually into a notch under the upper jaw, while a blueback herring''s lower jaw angles up sharply in the same shovel shape as an alewife''s.', 'Runs the same rivers and same spring window as American shad and alewife across NB and NS, including the Saint John River and Annapolis system.', 'Same practical concern as alewife: don''t assume shad-specific conservation flags or bag rules apply to a smaller river-herring catch, or vice versa — check the jaw and size before deciding what you''ve caught.', '/species/american-shad--variant-1.jpg', 'Smithsonian Environmental Research Center', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Alosa_aestivalis_(S0110)_(15910316357).jpg');

-- ===== Atlantic Cod (atlantic-cod) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('atlantic-cod', 'Atlantic Cod', 'Gadus morhua', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Iconic bottom-dwelling groundfish targeted on a short, tightly controlled recreational season, with different windows and limits depending on whether you fish the Gulf side (NB, PEI, and the Northumberland Strait shore of NS) or the Atlantic/Bay of Fundy side of Nova Scotia.', '/species/atlantic-cod.jpg', 'Wilhelm Thomas Fiege', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Atlantic_Cod,_Atlantischer_Kabeljau_(Gadus_morhua).jpg', true, now())
