insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-cod'), 0, 'Haddock', 'lookalike', 'Melanogrammus aeglefinus', 'Haddock has a straight, dark (almost black) lateral line, versus cod''s pale, curved lateral line — this is the fastest field check. Haddock also carries a distinct dark oval blotch ("the Devil''s thumbprint") above and behind the pectoral fin that cod never has, and lacks cod''s chin barbel entirely (cod''s barbel is obvious and always present). Haddock''s body is a cleaner silvery-grey without cod''s mottled brown-to-greenish blotching, and its tail is slightly forked with a dark rear edge versus cod''s more rounded/square tail.', 'Deeper offshore banks and ledges, generally in the same grounds as cod but more associated with clean sand/gravel bottom; caught alongside cod on the Scotian Shelf and Bay of Fundy side of NS.', 'Haddock is zero-retention under the 2026 DFO Gulf Region notice — must be released immediately in NB, PEI, and the NS Northumberland Strait/Gulf shore, exactly like pollock, even during the open cod window. On the DFO Maritimes Region side (NS Atlantic coast, Bay of Fundy), haddock retention is permitted within the same aggregate groundfish bag limit as cod and pollock (10/day Halifax Harbour and west, 5/day Hartlen Point and east). Confusing a haddock for a cod on the Gulf side and keeping it is a real, avoidable violation — check the lateral line and thumbprint before it goes in the cooler.', '/species/atlantic-cod--variant-0.jpg', 'Vsevolod Rudyi', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Melanogrammus_aeglefinus_318932194.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-cod'), 1, 'Pollock', 'lookalike', 'Pollachius virens', 'Pollock has a forked tail (cod''s is rounded/square), a protruding lower jaw that projects past the upper jaw (cod''s upper jaw projects further), and a chin barbel that''s tiny or absent versus cod''s obvious barbel. Pollock''s back runs olive-green to smoky black rather than cod''s brown-to-greenish mottling, and its lateral line is straighter and less distinctly pale than cod''s curved one.', 'Same wharves, breakwaters, and offshore structure as cod region-wide; pollock also feed well up in the water column and even at the surface, unlike bottom-hugging cod.', 'Retention rules genuinely differ between the two species in the Gulf Region: pollock is zero-retention there in 2026 while cod has a short open window and a 5-fish sub-limit within the 15-fish groundfish aggregate. Mistaking a pollock for a legal cod (or vice versa) on the Gulf side has real consequences — check jaw, tail, and barbel before deciding what goes in the cooler.', '/species/atlantic-cod--variant-1.jpg', 'Gervais et Boulart', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Pollachius_virens_Gervais.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-cod'), 2, 'Atlantic Tomcod', 'lookalike', 'Microgadus tomcod', 'Tomcod are a dwarf cod-family relative, not a juvenile Atlantic cod — the giveaway is size: tomcod max out around 15 cm (6 in), while even small recreationally-caught cod run 40+ cm. Both have three dorsal fins, two anal fins, and a chin barbel, so a small tomcod can superficially resemble a baby cod at a glance, but no genuinely juvenile Atlantic cod of that tiny size shows up on typical estuary or wharf gear in this region.', 'Estuaries and river mouths (e.g. the Shubenacadie, NS) rather than the open coastal and offshore structure cod relate to.', 'No regulatory concern — both are legal to target where seasons allow — but worth knowing tomcod is its own species, not a undersized cod, if one turns up on flounder gear in an estuary.', '/species/atlantic-cod--variant-2.jpg', 'New York Fish and Game Commission', 'Public domain', 'https://commons.wikimedia.org/wiki/File:FMIB_41877_Tomcod_(Microgadus_tomcod_Walbaum).jpeg');

-- ===== Atlantic Herring (atlantic-herring) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('atlantic-herring', 'Atlantic Herring', 'Clupea harengus', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Small, silvery schooling baitfish jigged from lit wharves after dark, prized as fresh bait for mackerel, cod, striped bass, and tuna, and important enough commercially that DFO tracks its stock health closely.', '/species/atlantic-herring.jpg', 'savoieju', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Clupea_harengus_Atlantic.jpg', true, now())
