insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-herring'), 0, 'Know the Fish', 'Atlantic herring (*Clupea harengus*) are slender, deeply forked-tail schooling fish, silver-sided with a dark blue-green back, usually 8–12 inches where anglers jig them from shore. They lack the lateral-line scales and wavy back markings mackerel have, and their single soft dorsal fin sits mid-body rather than near the tail.

Herring move in dense, tightly packed schools and feed on plankton, copepods, and small crustaceans, which is why they''re taken on tiny flash rather than anything resembling a whole baitfish. In this region there are two distinct spawning components: **fall spawners** (the large majority, spawning roughly August–October) and much smaller **spring spawning** groups tied to specific grounds like Grand Manan, Advocate Bay and Parrsboro in the upper Bay of Fundy, and Spectacle Buoy in southwest Nova Scotia. Fall spawners mature and first spawn around age 3–4, then settle into an annual cycle of spawning, overwintering, and summer feeding.', '[{"label":"DFO — Rebuilding Plan, Atlantic Herring Spring Spawner Component, NAFO Division 4T","url":"https://www.dfo-mpo.gc.ca/fisheries-peches/ifmp-gmp/herring-hareng/2025/herring-4t-hareng-eng.html"},{"label":"DFO — Atlantic Herring in the Maritimes Region, Integrated Fisheries Management Plan","url":"https://www.dfo-mpo.gc.ca/fisheries-peches/ifmp-gmp/herring-hareng/2020/index-eng.html"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-herring'), 1, 'When to Go', '### Season
Herring show up inshore around wharves from summer into fall, overlapping heavily with the mackerel run — many anglers catch both species on the same sabiki drop without targeting one over the other.

### Time of Day
Unlike mackerel, which fish best at dawn/dusk on visible surface activity, herring are consistently described by local anglers as a **night fish around lit docks**: herring school up under the glow of a wharf or pier light after dark, and the standard local method is casting a small sabiki away from the light and jigging it back through the lit water. Fishing picks up through the evening and into full dark.

### Tide
No strong tide preference is documented specifically for herring the way it is for mackerel; moving water and an active light-driven bait ball under the wharf matter more than tide stage.', '[{"label":"novascotiafishing.com forum, Bedford Basin/Halifax Harbor","url":"https://www.novascotiafishing.com/threads/bedford-basin-halifax-harbor.1904/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-herring'), 2, 'Where to Find Them', 'Herring relate to any wharf, pier, or breakwater with a night light spilling onto the water — the light draws plankton, which draws herring, which is the whole game.

- **Halifax Harbour / Bedford Basin, NS** — long-running local reports of herring, mackerel, and bluefish under the harbour''s lit wharves and piers.
- **Herring Cove, NS** (just outside Halifax) — small, sheltered former fishing cove with a government wharf, historically fished for herring and still a listed local spot.
- **Grand Manan Island, NB** — the historic centre of the Bay of Fundy herring weir fishery; wharves around the harbour and Seal Cove are worked at night for jigging bait (locals report squid jigging at midnight off the fisherman''s wharf in the same style used for herring).
- **Pointe-du-Chêne Wharf and the Cocagne breakwater, NB** — same Northumberland Strait spots known for mackerel also produce herring on sabiki gear.
- **Souris Wharf, PEI** — active commercial harbour on PEI''s east coast with public wharf access and reported pier fishing for pelagic baitfish alongside mackerel and tuna.

Ask locally before dark — the best-known spot changes year to year with where the bait is holding, and lit, publicly accessible wharves are the throughline across all three provinces.', '[{"label":"novascotiafishing.com forum, Bedford Basin/Halifax Harbor","url":"https://www.novascotiafishing.com/threads/bedford-basin-halifax-harbor.1904/"},{"label":"Fishbrain, Herring Cove fishing reports","url":"https://fishbrain.com/fishing-waters/7PMN5YNt/herring-cove"},{"label":"Grand Manan Tourism, Fishing, Hunting & Wharves","url":"http://www.grandmanannb.com/fishing.html"},{"label":"kwalmag.com, 25 Best Fishing Spots in Prince Edward Island","url":"https://kwalmag.com/2025/11/11/25-best-fishing-spots-in-prince-edward-island-canada-shore-pier-offshore/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-herring'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Light spinning rod, 6–7 ft, 10–15 lb mono or light braid — herring are smaller and softer-mouthed than mackerel. |
| Reel | Small-to-medium spinning reel, smooth drag for multi-fish hookups. |
| Terminal tackle | Sabiki/herring rig, smaller hooks (size 10–14) than a mackerel rig since herring have smaller mouths; add a small weight or teaser spoon below the rig for casting weight. |
| Light | Headlamp or a wharf/dock light — fishing after dark is the norm, not the exception, for this species. |
| Extras | Aerated bait bucket or cooler if keeping herring alive for bait, small landing net, pliers. |', '[{"label":"BC Fishing Journal, Sabiki Rigs for Fishing Herring and Bait Fish","url":"https://www.bcfishingjournal.com/featured/sabiki-rigs-for-fishing-herring-and-bait-fish/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-herring'), 4, 'Technique: Jigging Under the Lights', '1. Find a public wharf, pier, or dock with a working night light over the water — this is the single biggest factor in finding herring, more than any specific GPS spot.
2. Rig a sabiki/herring rig sized for small mouths (hooks 10–14) with a small weight or spoon on the bottom snap.
3. Cast just outside the lit circle on the water, into the shadow line where bait often holds tighter, and let the rig sink toward the bottom of the light''s reach.
4. Jig with short, sharp wrist flicks while slowly retrieving/taking up slack — this is a tighter, snappier jigging motion than the slow soft lifts used for mackerel.
5. Herring often sit deeper in the water column under the light than mackerel do, so if nothing hits near the surface let the rig sink further before starting your retrieve.
6. When you feel weight, keep reeling steadily up — multiple fish can be hooked on one drop.
7. Fishing typically improves as it gets fully dark and stays productive through the evening.', '[{"label":"novascotiafishing.com forum, Bedford Basin/Halifax Harbor","url":"https://www.novascotiafishing.com/threads/bedford-basin-halifax-harbor.1904/"},{"label":"New Brunswick Fishing Forum, Herring Season","url":"https://www.newbrunswickfishing.com/forums/index.php/topic/9905-herring-season/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-herring'), 5, 'Keeping Herring Alive and Fresh as Bait', 'Herring is one of the best natural baits in the region for mackerel, cod, striped bass, and bluefin tuna — but it''s also fragile and dies or spoils faster than hardier baitfish.

**To keep it alive:**
- Use a larger bait bucket or cooler, not a small 5-gallon pail — herring need real water volume and don''t tolerate crowding.
- Run a battery aerator/bubbler continuously, or in 15-minute on/off intervals to avoid burning it out.
- Keep the water cool — a sealed ice pack or frozen water bottle in the bucket helps in summer; never dump loose ice directly in, as it dilutes salinity and shocks the fish.
- Swap a portion of the water every 15–20 minutes with fresh seawater.
- Net bait out rather than grabbing by hand to avoid stripping their protective slime coat.

**If keeping it dead/fresh instead:** bleed and ice immediately the same way you would mackerel — herring''s oily flesh spoils fast, and fresh cut bait outfishes anything that''s sat too long.', '[{"label":"Salt Strong, 6 Tips To Keep Your Bait Alive Longer","url":"https://www.saltstrong.com/articles/keep-bait-alive-longer/"},{"label":"LSO News, How to keep bait alive longer when saltwater fishing","url":"https://www.lsonews.com/keep-bait-alive/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-herring'), 6, 'Conservation & Stock Status', 'Herring status varies sharply by spawning component in this region, and it''s worth knowing which one you''re near:

- **Fall spawners (Southern Gulf of St. Lawrence)** — the dominant group. DFO''s 2026 assessment found this spawning stock biomass in the **Healthy Zone**, and the commercial fall fishery TAC was increased to 15,500 tonnes for 2026–2027, up from 8,500 tonnes in 2025.
- **Spring spawners (Southern Gulf of St. Lawrence, NAFO 4T)** — a much smaller, geographically specific group. The outlook here is bleak: DFO''s most recent projections show the stock trending toward near-zero within about a decade, driven by high natural mortality (predation), shrinking average size, and very low recruitment tied partly to warming water (spring spawners need cold water to recruit well). A formal rebuilding plan is in place for this component.

The commercial fishery (weir, gillnet, purse seine) is the primary harvest method for herring in Atlantic Canada — this is not primarily a hook-and-line fishery. Recreational/hook-and-line herring fishing is a minor, largely unregulated-by-bag-limit activity layered on top. Given the spring spawner situation specifically, avoid targeting known spring spawning aggregations (e.g., near Grand Manan, Advocate Bay/Parrsboro, Spectacle Buoy) and keep only what you''ll use promptly as bait.', '[{"label":"Canada.ca — Fisheries and Oceans Canada increases Total Allowable Catch for Atlantic mackerel and Southern Gulf of St. Lawrence fall herring fishery (2026)","url":"https://www.canada.ca/en/fisheries-oceans/news/2026/07/fisheries-and-oceans-canada-increases-total-allowable-catch-for-atlantic-mackerel-and-southern-gulf-st-lawrence-fall-herring-fishery.html"},{"label":"Atlantic Fisherman, Outlook Bleak for Southern Gulf Spring Herring Stock","url":"https://atlanticfisherman.com/outlook-bleak-for-southern-gulf-spring-herring-stock/"},{"label":"DFO — Rebuilding Plan, Atlantic Herring Spring Spawner Component, NAFO Division 4T","url":"https://www.dfo-mpo.gc.ca/fisheries-peches/ifmp-gmp/herring-hareng/2025/herring-4t-hareng-eng.html"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'atlantic-herring'), 'NB', 'Tidal/saltwater', 'No closed recreational hook-and-line season found in DFO notices', 'No specific recreational bag limit for herring found in DFO Gulf Region or Maritimes Region notices — herring is managed primarily as a commercial weir/gillnet/seine fishery, and no hook-and-line possession limit is published the way there is for mackerel or striped bass. Fish conservatively, especially avoid keeping quantities near known spring-spawning grounds.', 'None specified', 'No provincial angling licence needed in tidal/salt water. General New Brunswick tidal-water gear rule: sport fish species limited to 1 line with max 3 hooks (3 points each); this general handline rule is the closest documented gear constraint, though herring isn''t classified as a listed sport fish.', 'https://www2.gnb.ca/content/gnb/en/departments/erd/fish-and-wildlife/content/go-fishing/content/rec_fisheries_faq.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'atlantic-herring'), 'NS', 'Tidal/saltwater', 'No closed recreational hook-and-line season found in DFO notices', 'No specific recreational bag limit for herring found in DFO Maritimes Region pelagic species notices (which detail mackerel, shark, and bluefin tuna but do not address herring) — fish conservatively, particularly given the poor status of the spring spawning component.', 'None specified', 'No provincial angling licence needed in tidal/salt water. Commercial herring fishery (weir/gillnet/seine) is the primary harvest method; recreational hook-and-line is a minor, lightly-regulated activity.', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/pelag-eng.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'atlantic-herring'), 'PEI', 'Tidal/saltwater', 'No closed recreational hook-and-line season found in DFO notices', 'No specific recreational bag limit for herring found in DFO Gulf Region notices — fish conservatively.', 'None specified', 'No provincial angling licence needed in tidal/salt water. DFO Gulf Region''s published recreational notices for the southern Gulf of St. Lawrence cover groundfish species specifically and do not address herring.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
