insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-mackerel'), 0, 'Know the Fish', 'Atlantic mackerel (*Scomber scombrus*) are fast-swimming, slender, deeply forked-tail fish that travel in large, tightly packed schools. Identify them by the dark, wavy bands across their back and the small finlets running along the top and bottom near the tail. Most fish caught from shore in this region run 12–18 inches and under 3 lbs.

They feed heavily on copepods, small baitfish, shrimp, and squid, which is why anything small, shiny, and moving fast draws strikes. Two mackerel populations move through Atlantic Canada: a southern contingent, and a northern contingent that migrates up to spawn in the Gulf of St. Lawrence in June–July before dispersing along the coast. This is why mackerel arrive close to shore in the Northumberland Strait mainly from August into the fall — they''re the post-spawn, feeding-heavy fish moving through. Mackerel are also sensitive to water temperature, which is part of why their inshore timing varies year to year.', '[{"label":"NH Fish & Game, Atlantic Mackerel","url":"https://www.wildlife.state.nh.us/marine/mackerel.html"},{"label":"Mass.gov, Creature Feature: Atlantic Mackerel","url":"https://www.mass.gov/info-details/creature-feature-atlantic-mackerel"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-mackerel'), 1, 'When to Go', '### Season
August through fall is the reliable inshore window for this region, as fish that spawned in the Gulf of St. Lawrence in June–July spread out and feed along the coast. Some years fish show earlier; local wharf regulars are the best real-time source.

### Time of Day
First light and evening are consistently the best windows — watch for surface activity and diving birds at these times specifically.

### Tide
Opinions vary even among experienced local anglers, but the most consistent pattern reported is fishing from about three hours before high tide through an hour or so after, with the bite often picking back up once the tide turns and starts moving out. The common thread across all reports: moving water outfishes dead slack water.', '[{"label":"novascotiafishing.com forum, Mackerel Fishing / Good Mackerel Fishing Wharfs","url":"https://www.novascotiafishing.com/"},{"label":"fishingreminder.com, Halifax fishing spot guide","url":"https://fishingreminder.com/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-mackerel'), 2, 'Find the School', 'Mackerel are a search-and-find fishery — once you locate a school you''ll likely catch fish quickly; in the wrong spot at the wrong time you can blank for hours even on a good day. Read the water for:

- Diving gulls or terns working an area repeatedly — birds see the bait balls mackerel are pushing to the surface from above.
- Jumping baitfish or ''boils'' — surface disturbance where mackerel are attacking bait from below.
- Any wharf, breakwater, or pier with moving tidal current — mackerel relate to current edges the same way baitfish do.

**Locally:** Pointe-du-Chêne Wharf and the Cocagne breakwater on the New Brunswick side; the Georgetown wharf area and Panmure Island causeway on the PEI side are all known, easy-access mackerel spots.', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-mackerel'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Light-to-medium spinning rod, 6–7 ft (20 lb braid / 12 lb mono leader) — mackerel aren''t large and lighter line casts small terminal tackle better. |
| Reel | Any spinning reel holding 100+ yards of light line with a smooth drag for when several fish hit at once. |
| Terminal tackle | Sabiki/feather rig or small casting spoons/metal jigs — carry both. |
| Extras | Bucket/cooler with ice, needle-nose pliers, a rag or wet gloves — mackerel are slimy and often hooked in multiples. |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-mackerel'), 4, 'Method One: Sabiki / Feather Rig', 'The standard high-volume method — a rig of 5–10 small hooks dressed with flash or feathers, imitating a small school of baitfish.

**Setting it up**
1. Tie main line to the top swivel with an improved clinch or Palomar knot (Palomar handles repeated multi-fish strain better).
2. Clip a 1–3 oz weight or heavier casting spoon to the snap at the bottom — gets the rig down and adds casting weight.
3. For mackerel specifically, a rig on size 8–12 hooks is the right scale — most store-bought ''mackerel''/''herring'' sabikis are already sized right.

**Fishing it**
1. Cast out, or drop straight down beside a wharf/breakwater, and let it sink to where fish are showing.
2. Jig with short, soft 6–12 inch lifts every few seconds — don''t rip it; subtle flash and movement triggers strikes.
3. From a pier, you can also let it settle and hold still a few seconds between lifts.
4. When you feel weight, reel up steadily — don''t stop early, multiple fish can still be hitting other hooks (''a full house'').
5. Keep the rig tangle-free between drops: check hooks/knots after landing multiples.', '[{"label":"knots.fish, How to Set Up a Sabiki Rig","url":"https://knots.fish/"},{"label":"saltstrong.com, How To Make A Sabiki Rig","url":"https://www.saltstrong.com/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-mackerel'), 5, 'Method Two: Small Casting Spoon or Metal Jig', 'Faster-moving and more active than a sabiki — better when fish are visibly schooling on top and you want to cover water quickly, or want one fish at a time (e.g., live bait for striped bass).

1. Cast a small, shiny casting spoon (1/2–1 oz) or metal jig into or past the school.
2. Retrieve fast and steady — speed and flash trigger strikes. Don''t slow down on a short hit.
3. If fish aren''t visible on the surface, let the lure sink a few feet first, then retrieve — vary sink time to find their depth.

A medium spinning outfit with 15 lb line and a 1–1.5 oz mackerel jig is a commonly recommended standard setup.', '[{"label":"NH Fish & Game, Atlantic Mackerel","url":"https://www.wildlife.state.nh.us/marine/mackerel.html"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-mackerel'), 6, 'Handling & Care After the Catch', 'Mackerel have soft, oily flesh that spoils fast — faster than most inshore species.

- **Bleed immediately** — cut through the gill arches (or the ''V'' where gills meet the lower jaw) right after unhooking.
- **Ice right away** — a dedicated cooler/bucket with ice, fish on top of (not buried under) the bulk of the ice.
- **Gut and clean promptly** — as soon as practical after bleeding.
- **For eating**: a few slits per side, olive oil, salt and pepper, grilled or broiled is the standard simple prep for a fish this oily and flavorful.', '[{"label":"fishermensvoice.com, Mackerel Fishing — A Maine Tradition","url":"https://www.fishermensvoice.com/"},{"label":"saltstrong.com, How To Bleed Fish","url":"https://www.saltstrong.com/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-mackerel'), 7, 'Bonus: Using Mackerel as Striped Bass Bait', 'Mackerel is one of the most effective striped bass baits on this coast, live or dead:

- **Live-lined** — hook through the lips (or ahead of the dorsal fin) on a circle hook, let it swim naturally in current/drift. Highest-effort, highest-reward; needs a livewell or aerated bucket.
- **Fresh cut/chunk bait** — cut into chunks/strips, fish on a bottom rig with a circle or J-hook and enough weight to hold in current. Simpler, still a proven producer.
- **Dead but fresh** — a whole dead mackerel drifted along bottom often takes the biggest fish of the day when live bait only produces small ones.

Freshness matters more than almost anything else here.', '[{"label":"guidesly.com, Best Bait for Striped Bass","url":"https://www.guidesly.com/"},{"label":"thefisherman.com, Live Bait: The Mack Daddy","url":"https://www.thefisherman.com/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-mackerel'), 8, 'Conservation & Consumption Notes', 'Atlantic mackerel stocks in Canada have declined enough that DFO imposed a total moratorium on the **commercial** mackerel fishery in March 2022, remaining in place in subsequent seasons. That moratorium applies to commercial harvest, not hook-and-line recreational fishing — no recreational mackerel bag limit specific to this region turned up in current DFO Gulf Region notices at time of writing. Given the state of the stock, fish conservatively: keep what you''ll actually eat or use as bait promptly, and release the rest.', '[{"label":"CBC News, Atlantic mackerel moratorium jeopardizes rod-and-reel bluefin tuna fishery","url":"https://www.cbc.ca/1.6475674"},{"label":"DFO — Recreational Groundfish Fishery, Southern Gulf of St. Lawrence","url":"https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'atlantic-mackerel'), 'NB', 'Tidal/saltwater', 'No closed season for hook-and-line recreational take', 'No specific bag limit found in DFO notices — fish conservatively given stock decline', 'None specified', 'No provincial licence needed in tidal/salt water. Commercial fishery under moratorium since March 2022; does not apply to recreational hook-and-line.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
