insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'atlantic-mackerel'), 6, 'As Bait', 'Live-line, fresh-cut chunks, or a whole dead mackerel on bottom — freshness is everything');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'atlantic-mackerel'), 'NH Fish & Game, Atlantic Mackerel', 'https://www.wildlife.state.nh.us/marine/mackerel.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'atlantic-mackerel'), 'Mass.gov, Creature Feature: Atlantic Mackerel', 'https://www.mass.gov/info-details/creature-feature-atlantic-mackerel');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'atlantic-mackerel'), 'DFO — Recreational Groundfish Fishery, Southern Gulf of St. Lawrence', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'atlantic-mackerel'), 'CBC News, Atlantic mackerel moratorium jeopardizes rod-and-reel bluefin tuna fishery', 'https://www.cbc.ca/1.6475674');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-mackerel'), 0, 'Northern Contingent Mackerel', 'stock', NULL, 'Not visually distinguishable from the southern contingent — this is a population/management distinction, not a physical one. The northern contingent is the group that spawns in the Gulf of St. Lawrence in June-July before dispersing along the coast.', 'The Gulf of St. Lawrence, including the Northumberland Strait shorelines covered in this guide — this is the contingent responsible for the fish showing up inshore in this region from August into fall.', 'Explains the region''s fishing calendar: mackerel arrive close to shore here mainly after the northern contingent finishes spawning offshore in the Gulf, which is why the inshore window opens in August rather than earlier in summer.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-mackerel'), 1, 'Southern Contingent Mackerel', 'stock', NULL, 'Also not visually distinguishable in hand — a separate spawning population managed and assessed independently of the northern (Gulf of St. Lawrence) contingent.', 'Primarily south of this region along the US Atlantic coast and southern Scotian Shelf; mixes with the northern contingent to varying degrees in DFO stock assessments.', 'Relevant mainly for understanding why Canadian and US stock assessments and quota discussions sometimes reference different population trends for what looks like "the same" mackerel from a wharf in NB or PEI.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-mackerel'), 2, 'Chub Mackerel', 'related-species', 'Scomber colias', 'Chub mackerel show dusky mottled blotches or spots below the midline, where Atlantic mackerel are clean silvery-white below the midline with no spotting. The two dorsal fins also sit closer together on a chub mackerel than on an Atlantic mackerel, and the first dorsal fin has 9-10 spines on a chub versus 11-13 on an Atlantic mackerel.', 'Occasionally reported in warmer years as water temperatures shift, though Atlantic mackerel remains the dominant species encountered inshore in this region.', 'No specific regulatory distinction found for this region, but correctly identifying an unusual mackerel catch is worth doing for accurate reporting of any range-shift sightings as this warmer-water species becomes more common with changing sea temperatures.', NULL, NULL, NULL, NULL);

-- ===== Atlantic Salmon (atlantic-salmon) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('atlantic-salmon', 'Atlantic Salmon', 'Salmo salar', 'anadromous', '{"NB","NS","PEI"}'::text[], 'Iconic anadromous gamefish of the Miramichi (NB) and Margaree (NS) systems, fished almost entirely catch-and-release with barbless flies under some of the strictest recreational rules in Canada.', '/species/atlantic-salmon.jpg', 'Uwe Kils', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Salmonlarvakils.jpg', true, now())
