insert into species_sources (species_id, label, url) values ((select id from species where slug = 'atlantic-salmon'), 'Canada Fishing Licence — New Brunswick Fishing Licence Guide 2026', 'https://canadafishinglicence.com/provinces/new-brunswick/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'atlantic-salmon'), 'Canada Fishing Licence — PEI Fishing Licence Guide 2026', 'https://canadafishinglicence.com/provinces/pei/');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-salmon'), 0, 'Grilse', 'form', NULL, 'A returning adult under 63 cm fork length that has spent only one winter at sea — smaller and more streamlined than a multi-sea-winter fish, typically in the 2-6 lb range. Look and behave like small versions of a full adult salmon: silver on return, darkening as they hold in the river.', 'All open salmon rivers in NB, NS, and PEI — grilse make up the bulk of most rivers'' summer run, including the Miramichi, Restigouche, and Margaree.', 'DFO''s grilse/large-salmon split (above or below 63 cm) is the actual regulatory size break used in stock assessments and historically in retention rules; even though the whole recreational fishery is catch-and-release right now, this is still the line anglers and biologists use to describe run composition and report catches.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-salmon'), 1, 'Multi-Sea-Winter (MSW) Salmon', 'form', NULL, 'A returning adult 63 cm fork length or larger that has spent two or more winters at sea. Noticeably deeper-bodied and heavier than a grilse of the same river, sometimes 10+ lbs on big systems like the Restigouche.', 'Same rivers as grilse, though MSW fish make up a larger share of the run on some systems (the Restigouche is known for larger multi-sea-winter fish) than others.', 'Same catch-and-release rule applies regardless of size class — there is no size-based retention distinction in the current recreational fishery.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-salmon'), 2, 'Parr', 'life-stage', NULL, 'Juvenile stream-dwelling stage, one to eight years old depending on the river. Slim and streamlined with a sharp snout, small mouth, a deeply forked tail, well-defined vertical parr marks (bars) down the flanks, few spots on the gill cover (often just one large spot), and an adipose fin that is never orange or red. A single row of teeth on the roof of the mouth (vomerine teeth) separates it from brown trout parr, which have two zig-zag rows.', 'Every salmon-bearing stream and river in NB, NS, and PEI, well upstream of tidal water.', 'Must always be released immediately — parr are juvenile Atlantic salmon, not a legal catch of any kind, and are commonly mistaken for brook trout (see the brook-trout lookalike entry on this page).', '/species/atlantic-salmon--variant-2.jpg', 'Peter Steenstra at the Green Lake National Fish Hatchery', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Atlantic_salmon_parr.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-salmon'), 3, 'Smolt', 'life-stage', NULL, 'The migratory stage a parr transforms into before heading to sea, usually 13-18 cm and two to five years old. Parr marks fade and the fish turns bright silver with a nearly black back and white belly, ready to imprint on saltwater life.', 'Same rivers as parr, moving downstream toward tidal water and the ocean during the smolt run, roughly May-June.', 'Also a fish that must be released immediately if encountered — smolts are the same protected wild salmon population, just mid-migration.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-salmon'), 4, 'Brook Trout', 'lookalike', 'Salvelinus fontinalis', 'The critical confusion in Maritime trout streams. Brook trout have red spots surrounded by a pale blue halo along their flanks and worm-like marbled (vermiculated) markings on the back — Atlantic salmon parr never have red spots and instead show plain vertical parr bars with only a few dark spots above the lateral line. Brook trout also have a squarer, less deeply forked tail than the sharply forked tail of a salmon parr, and white leading edges on their lower fins that parr lack.', 'The same small streams and rivers across NB, NS, and PEI where salmon parr are found — nearly all cold, clean Maritime trout water.', 'Getting this backwards has real consequences: a salmon parr caught in a trout stream must be released immediately regardless of season or limit, since retention of any Atlantic salmon is currently prohibited across the region.', '/species/atlantic-salmon--variant-4.jpg', 'Photo by and (C)2007 Derek Ramsey (Ram-Man)', 'CC BY-SA 2.5', 'https://commons.wikimedia.org/wiki/File:Brook_Trout_Salvelinus_fontinalis_2900px.jpg');

-- ===== Atlantic Tomcod (atlantic-tomcod) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('atlantic-tomcod', 'Atlantic Tomcod', 'Microgadus tomcod', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Small, cold-loving estuary cod relative that turns into a genuine winter ice-fishing target in a few NB/NS estuaries — a real regional tradition worth knowing, alongside its usual role as a bonus catch on flounder gear the rest of the year.', '/species/atlantic-tomcod.jpg', 'New York Fish and Game Commission', 'Public domain', 'https://commons.wikimedia.org/wiki/File:FMIB_41877_Tomcod_(Microgadus_tomcod_Walbaum).jpeg', true, now())
