insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-tomcod'), 0, 'Know the Fish', 'Atlantic tomcod (*Microgadus tomcod*) are small, bottom-oriented members of the cod family, maxing out around 15 cm/6 in — a true dwarf relative of Atlantic cod, not a juvenile of that species (they''re a distinct species entirely). Look for the classic small-cod body shape: three dorsal fins, two anal fins, and a small barbel under the chin, but scaled down to a fraction of Atlantic cod''s size. In the Mi''kmaq language they''re known as *punamu*; the common nickname "frostfish" across their range comes directly from their habit of running upriver to spawn in the dead of winter, in January, when almost nothing else is active.

Tomcod are an estuarine species tolerant of a wide range of salinity and temperature, and unlike most fish in this guide they''re at their most active and most targeted during the coldest part of the year.', '[{"label":"Friends of Merrymeeting Bay, Tomcod (Microgadus tomcod)","url":"https://cybrary.friendsofmerrymeetingbay.org/fgom/Microgadus_tomcod.htm"},{"label":"Hakai Magazine, Tomcod Brings Everyone to the Table","url":"https://hakaimagazine.com/features/tomcod-brings-everyone-to-the-table/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-tomcod'), 1, 'The Winter Ice-Fishing Tradition', 'Tomcod support a genuine, longstanding **winter estuary fishery** in Nova Scotia that''s distinct from anything else in this guide — most saltwater species here are summer/fall targets, but tomcod peak in January.

- The **Shubenacadie River** estuary is the best-documented tomcod water in the region: fishers work the snow-covered banks and ice in winter, historically using **wire traps** set in the icy water to catch fish as they run upriver to spawn.
- This lines up with the species'' "frostfish" nickname and its January spawning run — tomcod are one of the only fish actively targeted through the ice in tidal/estuary settings in this region, as opposed to freshwater lake ice fishing for trout and other species.
- The tradition has deep Indigenous roots (the Mi''kmaq name *punamu* reflects long-standing harvest of this species) and continues today; the Apoqnmatulti''k research project, which pairs Western science with Indigenous and local knowledge holders, currently monitors tomcod movements and habitat in Nova Scotia, underlining how significant the species still is culturally and ecologically.
- Elsewhere in the wider Gulf of St. Lawrence region, tomcod are also taken through the ice in good numbers, reinforcing that this is a real, geographically broad winter tradition, not a one-river curiosity.', '[{"label":"Hakai Magazine, Tomcod Brings Everyone to the Table","url":"https://hakaimagazine.com/features/tomcod-brings-everyone-to-the-table/"},{"label":"Friends of Merrymeeting Bay, Tomcod (Microgadus tomcod)","url":"https://cybrary.friendsofmerrymeetingbay.org/fgom/Microgadus_tomcod.htm"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-tomcod'), 2, 'When to Go', 'Two distinct windows: **January**, during the spawning run, is peak season for the dedicated winter/ice fishery described above, especially in known estuaries like the Shubenacadie. Outside that window, tomcod are present in deeper estuary channels through the open-water season and are commonly caught **incidentally** while targeting winter flounder with the same bottom rigs — worth knowing so you don''t mistake a bonus tomcod for something else on your flounder line.', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-tomcod'), 3, 'Where to Find Them', '- **NS:** The **Shubenacadie River** estuary is the signature winter tomcod water in this region. Beyond that, tomcod are broadly present along Nova Scotia''s estuaries wherever winter flounder are also found.
- **NB:** Deeper estuary channels of the **Cocagne and Shediac River** systems hold tomcod, typically encountered as bycatch on flounder gear rather than targeted directly.
- **PEI:** The Boughton Bay/Three Rivers estuary similarly holds tomcod alongside winter flounder, again mostly as an incidental catch on the same gear.

In any of these systems, deeper estuary channels and the same soft-bottom areas that hold winter flounder are the right water.', '[{"label":"Fishbrain, Cocagne Cove listing","url":"https://fishbrain.com"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-tomcod'), 4, 'Gear', '| Item | Recommendation |
|---|---|
| Open-water rod | Same light spinning setup used for winter flounder — 6-6''6" ML rod, light line. |
| Rig | Hi-lo bottom rig baited with small strips of bait, fished on or near bottom. |
| Ice fishing (traditional) | Historically, wire traps set through the ice at the river mouth during the January run — a distinct method from typical hook-and-line ice fishing gear used for freshwater species. |
| Bait | Small strips of clam, worm, or other bottom bait. |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-tomcod'), 5, 'Technique', '**Open-water/incidental (spring-fall):**
1. Fish the same hi-lo bottom rig used for winter flounder in deeper estuary channels.
2. Slow retrieve with frequent pauses on bottom — tomcod bite is subtle, similar to flounder.
3. Treat any tomcod caught this way as a bonus, not a dedicated target.

**Winter run (January, e.g. Shubenacadie):**
1. Target the estuary/river mouth during the spawning push in January.
2. Traditional method uses wire traps set in the ice; modern anglers can also still-fish with small baited hooks near bottom through a hole if ice conditions allow safe access.
3. Always confirm ice safety and access locally before attempting any ice fishing — conditions vary year to year and estuary ice is less predictable than a closed freshwater lake.', '[{"label":"Hakai Magazine, Tomcod Brings Everyone to the Table","url":"https://hakaimagazine.com/features/tomcod-brings-everyone-to-the-table/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-tomcod'), 6, 'Handling & Table Notes', 'Tomcod are a traditional food fish in this region, particularly tied to the winter run — hence the Hakai Magazine framing of tomcod as a fish that "brings everyone to the table." Small size means they''re typically cooked whole or lightly cleaned rather than filleted. Handle gently if releasing; being a small, delicate-mouthed fish, they don''t tolerate rough handling well.', '[{"label":"Hakai Magazine, Tomcod Brings Everyone to the Table","url":"https://hakaimagazine.com/features/tomcod-brings-everyone-to-the-table/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'atlantic-tomcod'), 7, 'Conservation Notes', 'No specific at-risk status turned up for Atlantic tomcod in this region. DFO''s Maritimes Region recreational fisheries materials list tomcod distinct from Atlantic cod (i.e., tomcod aren''t subject to Atlantic cod''s stricter conservation rules), and no dedicated bag limit turned up in current notices — fish conservatively regardless, particularly given the cultural and ecological significance of the winter spawning run described above.', '[{"label":"DFO Maritimes Region Recreational Fisheries","url":"https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/index-eng.html"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'atlantic-tomcod'), 'NB', 'Tidal/saltwater and estuary', 'No closed season for hook-and-line recreational take in tidal water', 'No specific bag limit found in DFO Gulf Region notices — fish conservatively', 'None specified', 'No provincial licence needed in tidal/salt water. Listed by DFO as distinct from Atlantic cod, not subject to cod-specific closures.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'atlantic-tomcod'), 'NS', 'Tidal/saltwater and estuary', 'No closed season for hook-and-line recreational take in tidal water; winter spawning run (e.g. Shubenacadie estuary) peaks in January', 'No specific bag limit found in DFO notices reviewed — fish conservatively', 'None specified', 'No provincial licence needed in tidal/salt water. Traditional winter/ice fishery on rivers like the Shubenacadie — confirm current local ice-safety conditions and any posted access rules before fishing through the ice.', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/index-eng.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'atlantic-tomcod'), 'PEI', 'Tidal/saltwater', 'No closed season for hook-and-line recreational take in tidal water', 'No specific bag limit found in current DFO Gulf Region notices for PEI — fish conservatively', 'None specified', 'No provincial licence needed in tidal/salt water.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'atlantic-tomcod'), 0, 'Season', 'January spawning run (peak); year-round as bycatch on flounder gear');
