insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-tomcod'), 0, 'Rainbow Smelt', 'lookalike', 'Osmerus mordax', 'Smelt has a single dorsal fin plus a small adipose fin (the little fleshy fin between dorsal and tail) and a deeply forked tail, while tomcod has three dorsal fins, two anal fins, a rounded tail, and no adipose fin at all. Smelt has a pointed snout with visible canine-like teeth and no chin barbel; tomcod has a short chin barbel and a blunter, more cod-like head. Fresh smelt also carry a distinctive cucumber-like smell that tomcod lack, and smelt flanks show an iridescent purple-pink stripe over silver rather than tomcod''s more mottled olive-brown back.', 'Same estuaries and river mouths as tomcod, often run at the same time of year — both are cold-tolerant estuarine species caught through the ice or from shore in the same NB/NS systems.', 'No regulatory difference found between the two, but they''re genuinely easy to mix up in a winter bucket of small silvery fish — the dorsal-fin count and barbel are the fastest checks.', '/species/atlantic-tomcod--variant-0.jpg', 'Bex Goreham', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Osmerus_mordax_380012943.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'atlantic-tomcod'), 1, 'Juvenile Atlantic Cod', 'lookalike', 'Gadus morhua', 'Tomcod are a distinct dwarf species, not a young Atlantic cod — the reliable check is size and barbel length: tomcod max out around 15 cm (6 in) with a chin barbel shorter than the diameter of the eye, while even small cod encountered on typical gear are considerably larger with a proportionally longer, more obvious barbel. Both share the three-dorsal-fin, two-anal-fin cod-family body plan, which is why the confusion happens at all.', 'Tomcod stay in estuaries and river mouths; small cod are more likely around coastal wharves and deeper structure rather than upriver.', 'No retention concern either way in this region, but useful to know a tiny cod-shaped fish caught in an estuary is almost certainly a tomcod, not an undersized cod.', NULL, NULL, NULL, NULL);

-- ===== Atlantic Bluefin Tuna (bluefin-tuna) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('bluefin-tuna', 'Atlantic Bluefin Tuna', 'Thunnus thynnus', 'saltwater', '{"NB","NS","PEI"}'::text[], 'The giant of the Gulf of St. Lawrence — a federally quota-managed, charter-dominated fishery centred on North Lake, PEI (self-styled "Tuna Capital of the World"), plus Nova Scotia and New Brunswick grounds; realistically accessed by booking a licensed charter, not a DIY shore or small-boat target.', '/species/bluefin-tuna.jpg', 'Rafa Gallut', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:At%C3%BAn_rojo,_thunnus_thynnus,_pescado_a_jigging_en_Cabo_de_Palos,_Murcia..JPG', true, now())
