insert into species_sources (species_id, label, url) values ((select id from species where slug = 'bluefin-tuna'), 'ScienceDirect, Atlantic bluefin tuna diet variability in the southern Gulf of St. Lawrence, Canada', 'https://www.sciencedirect.com/science/article/pii/S0141113623000776');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'bluefin-tuna'), 'North Lake Charters, Tuna Fishing', 'https://www.northlakecharters.ca/tuna-fishing/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'bluefin-tuna'), 'DFO Gulf Region, 2026 Prince Edward Island Bluefin Tuna notice', 'https://www.glf.dfo-mpo.gc.ca/en/node/20604');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'bluefin-tuna'), 'PEI Fishermen''s Association, Bluefin Tuna Registration', 'https://peifa.org/members/registration-tuna');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'bluefin-tuna'), 'CBC, Catch-and-release tuna charter industry nearly shut down by pandemic', 'https://www.cbc.ca/lite/story/1.5685329');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'bluefin-tuna'), 'CBC, Atlantic bluefin tuna quotas see first increase in 24 years', 'https://amp.cbc.ca/news/canada/prince-edward-island/atlantic-bluefin-tuna-quotas-see-first-increase-in-24-years-1.2839856');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'bluefin-tuna'), 'DFO, Canadian Atlantic Bluefin Tuna Integrated Fisheries Management Plan', 'https://www.dfo-mpo.gc.ca/fisheries-peches/ifmp-gmp/bluefin-tuna-thon-rouge/bluefin-tuna-thonrouge2017-eng.html');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'bluefin-tuna'), 0, 'School Bluefin', 'form', NULL, 'A size class, not a different-looking fish: roughly 27 to under 47 inches curved fork length, translating to about 10-60 lb. Same species and appearance as a giant, just younger and smaller.', 'Occurs in the same Gulf of St. Lawrence waters as larger size classes, though the licensed charter fishery out of North Lake, PEI is built around targeting giants specifically.', 'Size class matters directly for quota management — ICCAT and DFO subdivide Canadian bluefin quota by size class (school, large school/small medium, giant), so which class a fish falls into affects licence conditions and reporting.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'bluefin-tuna'), 1, 'Giant Bluefin', 'form', NULL, 'The size class this fishery is built around: roughly 73 inches curved fork length and up, from about 200 lb into four figures. This is the size class North Lake''s charter fleet targets and the one most associated with the region''s reputation.', 'Concentrated around North Lake and East Point, PEI, and other southern Gulf of St. Lawrence grounds through the July-October season.', 'The catch-and-release charter product described elsewhere in this guide is built specifically around giants — barbless circle hooks and ~180 lb-class line exist to let a fish this size be fought and released safely.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'bluefin-tuna'), 2, 'Yellowfin Tuna', 'lookalike', 'Thunnus albacares', 'Pectoral fin length is the most reliable check: a bluefin''s pectoral fin falls short of reaching the start of the second dorsal fin, while a yellowfin''s pectoral fin extends just past it. Yellowfin also show a bright yellow lateral stripe and a mostly-yellow second dorsal fin and finlets, versus a bluefin''s grey-and-yellow mixed second dorsal.', 'Yellowfin are a warmer-water species less commonly encountered in the Gulf of St. Lawrence than bluefin, but can turn up during offshore trips in the wider Maritimes region.', 'Different species entirely with separate quota and licensing frameworks from Atlantic bluefin — a charter targeting bluefin under a bluefin licence cannot simply retain an incidental yellowfin under those same tags.', '/species/bluefin-tuna--variant-2.jpg', 'Marc Taquet', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Banc_de_thons_albacores_(Thunnus_albacares)_(Ifremer_00568-68027_-_25201).jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'bluefin-tuna'), 3, 'Bigeye Tuna', 'lookalike', 'Thunnus obesus', 'Bigeye and yellowfin are hard to tell apart from bluefin by pectoral length alone since both can reach or pass the second dorsal fin start — the belly pattern is the tiebreaker: yellowfin show alternating light lines and dots on the belly that bigeye lack. Bluefin are distinguished from both by the shorter pectoral fin that falls short of the second dorsal.', 'An occasional deepwater visitor to Atlantic Canadian offshore grounds, less commonly encountered than bluefin in the southern Gulf specifically.', 'A separately managed species from Atlantic bluefin — confirm species before assuming bluefin tags or quota rules apply to an incidental catch.', '/species/bluefin-tuna--variant-3.jpg', 'Allen Shimada, NOAA NMFS OST', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Thunnus_obesus_(bigeye_tuna).jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'bluefin-tuna'), 4, 'Albacore', 'lookalike', 'Thunnus alalunga', 'The easiest of the tuna lookalikes to rule out: albacore have by far the longest pectoral fins of any tuna, extending well past the start of the second dorsal fin — noticeably longer and more sickle-shaped than a bluefin''s short pectoral.', 'Present in Atlantic Canadian offshore waters generally, though less central to the southern Gulf of St. Lawrence bluefin grounds specifically.', 'Managed as a distinct species from Atlantic bluefin tuna with its own quota framework — the long pectoral fin makes this an easy one to rule out at a glance.', '/species/bluefin-tuna--variant-4.jpg', 'Hugues Evano (IFREMER, Délégation océan Indien (DOI), Département Ressources Biologiques et Environnement (RBE), F-97420 Le Port, France)', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Thon_germon_(Thunnus_alalunga)_(Ifremer_00764-87615).jpg');

-- ===== Brook Trout (brook-trout) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('brook-trout', 'Brook Trout', 'Salvelinus fontinalis', 'freshwater', '{"NB","NS","PEI"}'::text[], 'The native "speckled trout" of Maritime streams, lakes, and rivers — small-stream fishing at its most classic, with sea-run populations adding a bonus estuary fishery each spring.', '/species/brook-trout.jpg', 'Photo by and (C)2007 Derek Ramsey (Ram-Man)', 'CC BY-SA 2.5', 'https://commons.wikimedia.org/wiki/File:Brook_Trout_Salvelinus_fontinalis_2900px.jpg', true, now())
