insert into species_sources (species_id, label, url) values ((select id from species where slug = 'brook-trout'), 'newbrunswickfishing.com forum threads', 'https://www.newbrunswickfishing.com/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'brook-trout'), 'Nova Scotia Recreational Fishing', 'https://novascotia.ca/fish/programs-and-services/recreational-fishing/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'brook-trout'), 'PEI Fishing, Hunting & Trapping Licences', 'https://www.princeedwardisland.ca/en/topic/fishing-hunting-trapping-licences');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'brook-trout'), 0, 'Sea-Run Brook Trout ("Salter")', 'form', NULL, 'Bright chrome-silver flanks with washed-out spotting compared to the vivid marbling of a resident stream fish; the red spots with pale halos are still visible up close. Reverts to typical brook trout colouring within days of re-entering fresh water.', 'Tidal and estuary reaches of coastal rivers across all three provinces — the Cocagne and Shediac (NB), Boughton and Morell (PEI), and most NS coastal systems.', 'Best targeted May through early July as fish gorge on estuary baitfish and shrimp. Falls under the same provincial licence and limits as resident brook trout — there is no separate sea-run category.', '/species/brook-trout--variant-0.jpg', 'Photo by and (C)2007 Derek Ramsey (Ram-Man)', 'CC BY-SA 2.5', 'https://commons.wikimedia.org/wiki/File:Brook_Trout_Salvelinus_fontinalis_2900px.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'brook-trout'), 1, 'Resident Stream Brook Trout', 'form', NULL, 'Stays in fresh water its whole life. Shows the classic vivid marbled (vermiculated) dark-green back, red spots ringed in pale blue along the flanks, and white-edged lower fins year-round rather than the washed-out chrome look of a fish fresh from the estuary.', 'Small, cold, clean streams and lakes throughout NB, NS, and PEI — the most widely distributed form of the species regionally.', 'Same licence and limits as sea-run fish caught in the same water.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'brook-trout'), 2, 'Atlantic Salmon Parr', 'lookalike', 'Salmo salar', 'Salmon parr lack the red spots that brook trout show along their sides, instead displaying plain vertical parr bars with only a few dark spots above the lateral line. Parr also have a more streamlined body, a sharper snout, a deeply forked tail (brook trout have a squarer, only slightly forked tail), and an adipose fin that is never orange or red, unlike a brook trout''s often reddish-tinged adipose fin.', 'The same small streams and rivers across NB, NS, and PEI where brook trout are caught — nearly every cold, clean trout stream in the region also holds young salmon.', 'Must be released immediately regardless of season, size, or limit — retention of any Atlantic salmon is currently prohibited across the region, and salmon parr are one of the most commonly misidentified fish in Maritime small-stream angling.', '/species/brook-trout--variant-2.jpg', 'Peter Steenstra at the Green Lake National Fish Hatchery', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Atlantic_salmon_parr.jpg');

-- ===== Brown Trout (brown-trout) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('brown-trout', 'Brown Trout', 'Salmo trutta', 'freshwater', '{"NB","NS"}'::text[], 'Introduced, wary, dusk-active trout found in select NB and NS rivers and lakes — a smaller, more localized fishery than rainbow or brook trout, best worked at night or low light with streamers, spinners, or large dry flies.', '/species/brown-trout.jpg', 'Eric Engbretson for U.S. Fish and Wildlife Service', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Salmo_trutta.jpg', true, now())
on conflict (slug) do update set
  common_name = excluded.common_name,
  scientific_name = excluded.scientific_name,
