insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'brown-trout'), 2, 'NS Bag Limit', '5 combined trout species/day; Sept fly/lure only');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'brown-trout'), 3, 'Best Time', 'Dusk into full dark — browns are the most nocturnal of the region''s trout');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'brown-trout'), 4, 'Best Gear', 'Large dry flies/streamers at low light, or inline spinners on light spinning gear');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'brown-trout'), 5, 'Known Waters', 'Saint John River system (NB); Mersey River, MacPhersons Lake, Garden of Eden Lake (NS)');
