insert into species_sources (species_id, label, url) values ((select id from species where slug = 'brown-trout'), 'Angler''s Atlas — St. John River', 'https://www.anglersatlas.com/place/724844/st-john-river');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'brown-trout'), 0, 'Sea Trout (Sea-Run Brown Trout)', 'form', NULL, 'The same species as resident brown trout, just anadromous. Fresh from the estuary it''s distinctly silvery, with a dark grey back and bright silver flanks fading to a white or cream belly, and noticeably larger than resident fish from the same river. After time back in fresh water it darkens and starts to look like an oversized resident brown, at which point only a scale reading (showing fast marine growth rings) can confirm sea-run origin.', 'Not established as a distinct fishery in the NB/NS sources checked for this guide — brown trout populations here are documented mainly as resident river and stocked-lake fish. Anglers on tidal reaches of brown trout rivers should still be aware sea-run individuals are biologically possible.', 'Falls under the same brown trout licence and limits as resident fish — there is no separate sea trout category in NB or NS regulations.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'brown-trout'), 1, 'Atlantic Salmon', 'lookalike', 'Salmo salar', 'DFO''s own field marks: Atlantic salmon have an upper jaw that does NOT extend past the eye, an adipose fin that is never orange, and only a few spots concentrated on the upper body. Brown trout, by contrast, have an upper jaw extending past the eye, an adipose fin that may be fringed with orange or red, and spots scattered heavily over the entire body, including large dark spots ringed with a lighter halo mixed with red spots. Mouth check: salmon have a single row of teeth on the roof of the mouth (vomerine teeth); brown trout have two rows in a zig-zag pattern.', 'Rivers in NB and NS where both species can occur, including sections of the Saint John River system.', 'This confusion has a real legal consequence: Atlantic salmon retention is currently prohibited across NB, NS, and PEI, so any fish identified as a salmon rather than a brown trout must be released immediately regardless of size or season.', '/species/brown-trout--variant-1.jpg', 'Uwe Kils', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Salmonlarvakils.jpg');

-- ===== Chain Pickerel (chain-pickerel) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('chain-pickerel', 'Chain Pickerel', 'Esox niger', 'freshwater', '{"NB","NS"}'::text[], 'Aggressive, toothy ambush predator found in slow rivers, lakes and bays across southern New Brunswick and southwestern/central Nova Scotia. Introduced to both provinces and now classified as invasive — as of 2026, anglers in specific NB Recreational Fishery Areas and across all of Nova Scotia are legally required to kill and keep any chain pickerel they catch, not release it.', '/species/chain-pickerel.jpg', 'Noel Burkhead/Howard Jelks', 'CC BY-SA 2.5', 'https://commons.wikimedia.org/wiki/File:Esox_niger.jpg', true, now())
