insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'chain-pickerel'), 0, 'Know the Fish', 'Chain pickerel (*Esox niger*) are slender, torpedo-shaped members of the pike family, identified by a chain-like dark green mesh pattern over a lighter green-gold body and a distinct dark vertical (sometimes diagonal) bar running down from the eye. They have a duck-bill-shaped snout packed with sharp teeth. Most fish caught in this region run 12–20 inches; anything over 24 inches is a very good fish for the Maritimes.

They''re classic "lie and wait" ambush predators — they hold tight to weed edges, lily pads, and submerged wood, then explosively strike baitfish, frogs, and even small ducklings that pass by. Chain pickerel are not native to the Maritimes: they were illegally introduced to southwestern Nova Scotia in the 1940s and later turned up in southern New Brunswick, and have since spread through additional watersheds via both natural movement and further illegal bucket-dumping. Wherever they establish, they''re documented to hammer native brook trout populations hard, sometimes within just a few years.', '[{"label":"Nova Scotia Invasive Species Council, Chain Pickerel","url":"https://nsinvasives.ca/chain-pickerel/"},{"label":"USGS Nonindigenous Aquatic Species, Chain Pickerel factsheet","url":"https://nas.er.usgs.gov/queries/factsheet.aspx?SpeciesID=681"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'chain-pickerel'), 1, 'Where to Find Them', '**New Brunswick:** established in the lower Saint John River system and its warm, weedy bays — Belleisle Bay, Washademoak Lake, Grand Lake, and connected waters like the Kennebecasis and Hammond rivers are all reported pickerel water by local anglers. Miramichi Lake is another spot where they show up May through September.

**Nova Scotia:** concentrated in southwestern NS (Yarmouth/Shelburne/Queens counties) where they were first released, having since spread into additional watersheds province-wide.

Look for slow current, lily pads, cattails, and drop-offs along weed edges — these fish rarely stray far from cover.', '[{"label":"New Brunswick Fishing Forum, Favourite Pickerel Spots","url":"https://www.newbrunswickfishing.com/threads/favourite-pickerel-spots.9497/"},{"label":"Nova Scotia Invasive Species Council, Chain Pickerel","url":"https://nsinvasives.ca/chain-pickerel/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'chain-pickerel'), 2, 'When to Go', '### Season
Chain pickerel spawn very early in spring, right after ice-out, often before most other species get moving. This is prime time — pre-spawn and post-spawn fish feed heavily and are at peak weight, and they''ll push into shallow coves and channels they wouldn''t normally use once water temperatures climb into the mid-to-high 40s°F.

### Through the Season
Once vegetation fills in for summer, pickerel tuck into weed edges and pads and hold there into fall. They also bite well through the ice — pickerel are a common winter target in Maritime lakes.', '[{"label":"The Current Angler, Early Season Tactics for Chain Pickerel","url":"https://thecurrentangler.com/2022/03/28/early-season-tactics-for-chain-pickerel/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'chain-pickerel'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | 6.5–7 ft medium-light spinning rod — same outfit you''d use for bass or trout. |
| Line | 8–12 lb monofilament or braid with a fluorocarbon leader. |
| Leader | Add a short wire or heavy fluorocarbon leader — pickerel have a mouthful of sharp teeth that will slice straight through light line. |
| Lures | Spinnerbaits, spoons, small jerkbaits, and topwater baits in white, red/white, or yellow, plus natural baitfish patterns. |
| Extras | Long-nose pliers or a jaw spreader for hook removal — do not put fingers near the teeth. |', '[{"label":"FishingBooker, How to Go Chain Pickerel Fishing","url":"https://fishingbooker.com/blog/chain-pickerel-fishing/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'chain-pickerel'), 4, 'Technique', '1. Target weed edges, lily pad clusters, and submerged wood rather than open water — pickerel almost never chase far from cover.
2. Work lures with a slow, erratic retrieve punctuated by pauses — an injured, struggling baitfish pattern draws the most strikes.
3. In early spring, fan-cast shallow coves and channel edges where warming water pulls baitfish (and pickerel) in first.
4. In summer, cast parallel to weed lines and pad edges rather than straight into them, working the lure along the entire edge.
5. Set the hook firmly and quickly — pickerel have hard, bony mouths, and a soft hookset often results in a missed fish.', '[{"label":"MeatEater Fishing, Lake Snake Love: How to Catch Chain Pickerel","url":"https://www.themeateater.com/fish/freshwater/lake-snake-love-how-to-catch-chain-pickerel"},{"label":"Bass Pro Shops 1Source, Three Ways to Catch Chain Pickerel","url":"https://1source.basspro.com/news-tips/fishing-information/6532/three-ways-catch-chain-pickerel"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'chain-pickerel'), 5, 'Handling & Release — Read This Before You Let One Go', 'This is the single most important thing to know about chain pickerel in this region: **in many NB and all NS waters, you are now legally required to keep every chain pickerel you catch, not release it.**

Effective April 1, 2026, New Brunswick added a mandatory condition of licence requiring anglers to retain (not release) chain pickerel caught in these Recreational Fishery Areas (RFAs): **Restigouche, Chaleur, Miramichi, Southeast, and Inner Bay of Fundy.** Releasing one back can draw a fine of $100–$500 under the Fish and Wildlife Act. Fish must be humanely euthanized immediately (a swift, firm blow to the head is the standard method) and can be kept for consumption or delivered frozen to a local Department of Natural Resources office; catches should also be reported to DNR with date, location, and photos where possible.

Nova Scotia''s approach goes further: anyone fishing under a sportfishing licence agrees, as a condition of that licence, to retain any chain pickerel caught anywhere in the province — there is no release option once you''ve hooked one.

**Before you fish anywhere for chain pickerel in NB, confirm which RFA you''re in** using GNB''s Fishing Regulations Web/Mobile Map, since the mandatory-retention rule is defined by specific RFAs, not a blanket province-wide rule the way it is in NS.', '[{"label":"Government of New Brunswick, New recreational fishing rules to take effect","url":"https://www.gnb.ca/en/news/n-b.2026.03.new-recreational-fishing-rules-take-effect.html"},{"label":"Government of New Brunswick, Mandatory retention of invasive species","url":"https://www.gnb.ca/en/topic/environment-resources/biodiversity-conservation/invasive-species/invasive-fish.html"},{"label":"Government of New Brunswick, Fish NB Angling Regulations (regulations summary)","url":"https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'chain-pickerel'), 6, 'Conservation & Consumption Notes', 'Chain pickerel are not a conservation concern themselves — quite the opposite. Fisheries managers in both provinces treat them as a damaging invasive species that outcompetes native fish (including brook trout and Atlantic salmon fry) for food and habitat, which is the whole reason behind the retention requirement. Do not use chain pickerel as live or dead bait, and never transport live pickerel between waterbodies — that''s exactly how the species has continued to spread. Clean boats, waders, and bait buckets between trips to different lakes.

As table fare, pickerel are bony (Y-bones like their pike relatives) but the flesh is white, mild, and good eating once you learn to fillet around the bones.', '[{"label":"Nova Scotia Invasive Species Council, Chain Pickerel","url":"https://nsinvasives.ca/chain-pickerel/"},{"label":"Mi''kmaq-Maliseet Nations News, Chain Pickerel, An Aquatic Invasive Species","url":"https://www.mmnn.ca/2022/03/chain-pickerel-an-aquatic-invasive-species/"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'chain-pickerel'), 'NB', 'Freshwater', 'See current GNB Fish Regulations Summary for open season dates by water — a valid NB angling licence is required', 'No release permitted in Restigouche, Chaleur, Miramichi, Southeast, and Inner Bay of Fundy RFAs — mandatory retention condition of licence applies; confirm exact daily quota in the current regulations summary for the water you''re fishing', 'None specified for retention purposes — the rule requires keeping the fish regardless of size', 'Effective April 1, 2026: chain pickerel must be retained, not released, if caught in the RFAs listed above, as part of NB''s new invasive-species mandatory retention condition of licence. Fines of $100–$500 apply for releasing one. Fish must be humanely euthanized and may be eaten or delivered frozen to a local DNR office; report catches to DNR (email/phone in current regs summary). Confirm your RFA using the GNB Fishing Regulations Web/Mobile Map before fishing.', 'https://www.gnb.ca/en/topic/environment-resources/biodiversity-conservation/invasive-species/invasive-fish.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'chain-pickerel'), 'NS', 'Freshwater', 'No specific closed season found for chain pickerel in current NS Anglers'' Handbook summary — verify in current handbook', 'Mandatory retention — no release permitted anywhere in the province under sportfishing licence conditions', 'None specified — retention required regardless of size', 'Nova Scotia requires anglers, as a condition of their sportfishing licence, to retain (kill) any chain pickerel caught anywhere in the province rather than releasing it. It is also illegal to use or possess chain pickerel as bait in NS.', 'https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf', '2026');
