insert into species_sources (species_id, label, url) values ((select id from species where slug = 'chain-pickerel'), 'Government of New Brunswick, New recreational fishing rules to take effect', 'https://www.gnb.ca/en/news/n-b.2026.03.new-recreational-fishing-rules-take-effect.html');
