insert into species_sources (species_id, label, url) values ((select id from species where slug = 'chain-pickerel'), 'New Brunswick Fishing Forum, Favourite Pickerel Spots', 'https://www.newbrunswickfishing.com/threads/favourite-pickerel-spots.9497/');
