insert into species_sources (species_id, label, url) values ((select id from species where slug = 'chain-pickerel'), 'MeatEater Fishing, Lake Snake Love: How to Catch Chain Pickerel', 'https://www.themeateater.com/fish/freshwater/lake-snake-love-how-to-catch-chain-pickerel');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'chain-pickerel'), 0, 'Northern Pike', 'lookalike', 'Esox lucius', 'Chain pickerel show a dark, chain-like mesh pattern over a lighter green-gold body, with both the cheek and the entire gill cover (operculum) fully covered in scales. Northern pike are larger-growing, with light, bean-shaped cream or yellow spots scattered across a darker olive-green to brown body — the opposite light-on-dark pattern from a pickerel''s dark-on-light mesh — and only the cheek is fully scaled; the lower half of the gill cover is bare of scales.', 'Reported as an increasingly encountered fish in the Saint John River drainage (NB) as pike move in from neighbouring Maine waters; not yet a long-established Maritime population the way chain pickerel is.', 'Getting this wrong matters in the wrong direction here too: chain pickerel is a mandatory-keep invasive in several NB RFAs and province-wide in NS, while northern pike is not currently subject to the same mandatory-retention rule in this region — confirm the species carefully before deciding whether a fish must be kept.', '/species/chain-pickerel--variant-0.jpg', 'George Chernilevsky', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Esox_lucius_2021_G1.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'chain-pickerel'), 1, 'Muskellunge', 'lookalike', 'Esox masquinongy', 'Chain pickerel have both cheek and gill cover fully scaled and typically fewer than 120 lateral line scales in the low range for the genus. Muskellunge are the largest esocid, with only the upper portion of the cheek and gill cover scaled (the rest bare), dark spots or vertical bars on a lighter body (opposite of a pickerel''s dark mesh-on-light-body look), and six or more sensory pores per side on the underside of the lower jaw versus a pickerel''s fewer pores.', 'Saint John River, New Brunswick, particularly near the Meduxnekeag River — an introduced, unwanted population that established itself in the mid-2000s.', 'Muskellunge is not currently a mandatory-retention species in NB the way chain pickerel is in several RFAs — do not assume the same keep-it-rule applies just because both are toothy esocids caught in the same water.', '/species/chain-pickerel--variant-1.jpg', 'Knepp, Timothy - U.S. Fish and Wildlife Service', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Muskellunge_USFWS.jpg');

-- ===== Cunner (Bergall) (cunner) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('cunner', 'Cunner (Bergall)', 'Tautogolabrus adspersus', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Small, hardy, always-hungry wrasse found around nearly every wharf, breakwater, and rocky structure in NB/NS/PEI — the easiest, most reliable species in this guide and a great confidence-builder or between-bites distraction.', '/species/cunner.jpg', 'State of New York Forest, Fish, and Game Commission', 'Public domain', 'https://commons.wikimedia.org/wiki/File:FMIB_43254_Bergall;_Cunner_(Tautogolabrus_adspersus).jpeg', true, now())
