delete from species_variants where species_id = (select id from species where slug = 'cunner');
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'cunner'), 0, 'Know the Fish', 'Cunner (*Tautogolabrus adspersus*), locally called bergall, conner, or chogset, are small members of the wrasse family (Labridae) — the same family as tautog/blackfish further south. They range from the Gulf of St. Lawrence and Newfoundland down to Chesapeake Bay, making the NB/NS/PEI coast core habitat, not the edge of their range. Juveniles show a black circular spot on the rear dorsal fin; larger adults develop gold flecks along the sides. Colour is variable and mottled, blending in well against rocks and pilings.

Cunner are non-migratory, structure-oriented fish, typically found from the shallows down to over 100 m, but around wharves and breakwaters they''re usually right up near the pilings and rocks within easy casting range. One unusual trait: cunner survive winter by going into a dormant, torpid state, wedging into rock crevices and barely moving once water temperatures drop below roughly 5°C — which is why they disappear from the fishery in the cold months and reappear reliably every spring.', '[{"label":"Wikipedia / Marine Life ID, Cunner (Tautogolabrus adspersus)","url":"https://www.marinelifeid.com/identification/cunner-tautogolabrus-adspersus/"},{"label":"Canadian Journal of Zoology, Winter habits of the cunner, Tautogolabrus adspersus, in Newfoundland","url":"https://cdnsciencepub.com/doi/abs/10.1139/z71-218"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'cunner'), 1, 'When to Go', 'Cunner fish well through the open-water season, roughly spring through fall, once water has warmed past their winter torpor threshold. There''s no tight seasonal window like a spawning run — this is a consistent, any-warm-day fishery, which is part of why it''s a good option to fall back on when a target species (mackerel, striped bass) isn''t cooperating. Any time of day works; they''re not particularly tide- or light-dependent compared to species like mackerel or striped bass.', '[{"label":"Canadian Journal of Zoology, Winter habits of the cunner, Tautogolabrus adspersus, in Newfoundland","url":"https://cdnsciencepub.com/doi/abs/10.1139/z71-218"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'cunner'), 2, 'Where to Find Them', 'Cunner relate to hard structure almost exclusively: wharf pilings, breakwaters, rock jetties, bridge abutments, and shipwrecks.

- **NB:** Shediac Harbour is specifically noted as good cunner water; the Cocagne Cape Marina breakwater and any Northumberland Strait wharf with pilings will hold fish.
- **NS:** **Halifax Harbour** and the Northwest Arm are well-documented cunner water right off the downtown waterfront docks; expect them anywhere along the Atlantic coast, Bay of Fundy, and Cape Breton with wharf or rock structure — this is one of the most evenly distributed species in the province.
- **PEI:** Georgetown''s waterfront and other Three Rivers-area wharves are a good bet, as is any structure around Boughton Bay/Panmure Island.

Because cunner relate so tightly to structure everywhere, virtually any public wharf or breakwater in all three provinces is worth a look.', '[{"label":"Fishbrain, Halifax Harbour listing","url":"https://fishbrain.com/fishing-waters/NdeaVe7U/halifax-harbour"},{"label":"novascotiafishing.com, Halifax Harbour/Northwest Arm thread","url":"https://www.novascotiafishing.com/threads/halifax-harbour-northwest-arm.2905/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'cunner'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Light spinning rod, any you have on hand — no specialized gear needed. |
| Hooks | Small bait hooks (size 6-10) — cunner have small mouths and are notorious bait-stealers on oversized hooks. |
| Bait | Clam strips or worms are the standard, most-recommended baits. |
| Rig | Simple small bait rig or a plain hook with a split shot — no finesse required. |', '[{"label":"NorEast Fishing Forum, Tips on Bergall (cunner) fishing","url":"https://www.noreast.com/threads/tips-on-bergall-cunner-fishing.63959/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'cunner'), 4, 'Technique', '1. Find any wharf, breakwater, or rocky jetty with visible pilings, rockpiles, or bridge abutments.
2. Drop a small baited hook straight down beside the structure — no need to cast far or work a retrieve.
3. Cunner will take almost any small bait or lure presented near their cover, so this is a genuinely no-technique fishery — perfect for kids or beginners.
4. Expect fast, aggressive bites and a fair number of stolen baits; re-bait often rather than waiting out slow bites, since cunner are opportunistic and quick.
5. If bigger-fish tactics (striped bass, mackerel) are slow, dropping a small rig for cunner nearby is a reliable way to keep rods bent while you wait.', '[{"label":"NorEast Fishing Forum, Tips on Bergall (cunner) fishing","url":"https://www.noreast.com/threads/tips-on-bergall-cunner-fishing.63959/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'cunner'), 5, 'Handling & Table Notes', 'Cunner are hardy and easy to handle — a light grip and standard hook removal is all that''s needed. They''re an underrated eating fish: firm, mild white flesh, though small size means more cleaning effort per meal than a larger species. Most anglers targeting bigger species treat cunner as an incidental catch-and-release bonus rather than table fare, but there''s nothing wrong with keeping a few for a fish fry if you''re catching them anyway.', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'cunner'), 6, 'Conservation Notes', 'No at-risk status or specific conservation concern turned up for cunner in this research — they''re an abundant, resilient, non-migratory species. No dedicated recreational bag limit turned up in current DFO Gulf Region or Maritimes Region notices; fish them as a light, sustainable, any-size fishery.', '[]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'cunner'), 'NB', 'Tidal/saltwater', 'No closed season for hook-and-line recreational take in tidal water', 'No specific bag limit found in DFO Gulf Region notices — fish conservatively', 'None specified', 'No provincial licence needed in tidal/salt water.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'cunner'), 'NS', 'Tidal/saltwater', 'No closed season for hook-and-line recreational take in tidal water', 'No specific bag limit found in DFO notices reviewed — fish conservatively', 'None specified', 'No provincial licence needed in tidal/salt water. NS has coastline in both DFO Maritimes Region and DFO Gulf Region — no cunner-specific limit found in either.', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/index-eng.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'cunner'), 'PEI', 'Tidal/saltwater', 'No closed season for hook-and-line recreational take in tidal water', 'No specific bag limit found in current DFO Gulf Region notices for PEI — fish conservatively', 'None specified', 'No provincial licence needed in tidal/salt water.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'cunner'), 0, 'Season', 'Spring through fall — dormant/torpid in cold winter water');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'cunner'), 1, 'Best Time', 'Any time — not especially tide- or light-dependent');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'cunner'), 2, 'Where', 'Any wharf, breakwater, or rocky structure with pilings');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'cunner'), 3, 'Bait', 'Clam strips or worms on a small hook');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'cunner'), 4, 'Difficulty', 'Very easy — great for kids/beginners or between bigger-fish bites');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'cunner'), 5, 'Table Fare', 'Firm, mild white flesh; small size makes cleaning effort higher per meal');
