insert into species_sources (species_id, label, url) values ((select id from species where slug = 'cunner'), 'DFO Maritimes Region Recreational Fisheries', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/index-eng.html');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'cunner'), 0, 'Tautog (Blackfish)', 'lookalike', 'Tautoga onitis', 'Tautog is a much bigger, heavier-bodied fish, averaging 1-3 lb and reaching up to 3 ft/25 lb versus cunner''s small size throughout life. Tautog has a high-arched, steep, rounded head profile with a blunt snout and thick rubbery lips, while cunner has a more pointed head profile and thinner lips. Tautog''s dark, mottled blackish-brown coloring also runs heavier and less speckled than cunner''s variable mottled pattern with gold flecking.', 'Same structure cunner relates to — wharf pilings, breakwaters, rock jetties — with tautog present at the northern edge of its range in Nova Scotia, overlapping cunner water.', 'No regulatory concern in this region, but worth knowing a noticeably larger, blunt-headed wrasse on the same light gear is likely a tautog, not an oversized cunner.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'cunner'), 1, 'Juvenile Pollock', 'lookalike', 'Pollachius virens', 'Juvenile ("harbor") pollock share the same wharf-piling and breakwater structure as cunner and are a similar size in their first year or two, but pollock has a forked tail (cunner''s is rounded/fan-shaped), a single soft dorsal fin running the length of the back with no spiny section (cunner''s dorsal fin has a distinct spiny front section), and a cod-family body shape versus cunner''s deeper-bodied wrasse shape.', 'Both hold tight to the same inshore wharf and breakwater structure region-wide, especially in summer and fall.', 'No regulatory concern, but useful when a mixed bag of small structure-oriented fish comes up and includes something that doesn''t quite look like a cunner.', NULL, NULL, NULL, NULL);

-- ===== Gaspereau (Alewife) (gaspereau) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('gaspereau', 'Gaspereau (Alewife)', 'Alosa pseudoharengus', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Small, silvery, hard-fighting river-herring that surge into NB/NS/PEI estuaries and rivers each spring to spawn, supporting both a family-friendly hook-and-line/dip-net fishery and, in Nova Scotia, a long-running commercial river fishery.', '/species/gaspereau.jpg', 'Unknown author', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Alosa_pseudoharengus.jpg', true, now())
on conflict (slug) do update set
  common_name = excluded.common_name,
  scientific_name = excluded.scientific_name,
  category = excluded.category,
  provinces = excluded.provinces,
  summary = excluded.summary,
  image_path = excluded.image_path,
  image_credit = excluded.image_credit,
  image_license = excluded.image_license,
  image_source_url = excluded.image_source_url,
  is_published = true,
  updated_at = now();
delete from guide_sections where species_id = (select id from species where slug = 'gaspereau');
delete from regulations where species_id = (select id from species where slug = 'gaspereau');
delete from quick_reference where species_id = (select id from species where slug = 'gaspereau');
delete from species_sources where species_id = (select id from species where slug = 'gaspereau');
delete from species_variants where species_id = (select id from species where slug = 'gaspereau');
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'gaspereau'), 0, 'Know the Fish', 'Gaspereau (*Alosa pseudoharengus*), known in most of the U.S. as alewife, are small, deep-bodied, silvery members of the herring family, typically 25-30 cm as adults. They''re often lumped together with the closely related blueback herring (*Alosa aestivalis*) under the same catch-all name "gaspereau" or "river herring" — the two run at the same time in the same rivers and are managed together. You can tell them apart: alewife have larger eyes, a paler/silvery body, and a pale belly, while blueback herring have smaller eyes, a darker bluish back, and a darker belly.

Gaspereau are **anadromous**: adults live at sea and run up rivers each spring to spawn in lakes and slow river sections, then head back to salt water (some die after spawning, but not all — unlike Pacific salmon, gaspereau can spawn more than once in a lifetime). They''re prone to jumping and are surprisingly strong fighters on light tackle for their size, but have small mouths that require correspondingly small hooks and flies.', '[{"label":"Maine Sea Grant, Maine Seafood Guide — Alewife","url":"https://seagrant.umaine.edu/maine-seafood-guide/alewife/"},{"label":"DFO, Gaspereau Assessment for the Gulf Region to 2019","url":"https://publications.gc.ca/collections/collection_2024/mpo-dfo/fs70-5/Fs70-5-2024-041-eng.pdf"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'gaspereau'), 1, 'When to Go', 'The spring spawning run is the main event: gaspereau typically push upriver a few weeks after the rainbow smelt run, commonly **May** across most of NB/NS/PEI, though exact timing shifts year to year with water temperature. During the run, fish concentrate heavily at river mouths, fishways, and current seams, making for fast, easy action. Outside the main run, stragglers and school activity can still be found near estuary mouths into summer, but the spring window is by far the most productive and most consistent.', '[{"label":"Halifax Bloggers, Gaspereau in the Gaspereau | Noticed in Nova Scotia","url":"https://halifaxbloggers.ca/noticedinnovascotia/2017/05/gaspereau-in-the-gaspereau/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'gaspereau'), 2, 'Where to Find Them', 'Gaspereau run essentially every major river system with ocean access across all three provinces.

- **NS:** The **Gaspereau River** (Kings County, feeding the Annapolis system) is the namesake water and has a long commercial fishing tradition — some operations there represent the sixth generation of the same families fishing it. The wider **Annapolis River** system, the Shubenacadie, and rivers around the Bay of Fundy and Northumberland Strait all see runs.
- **NB:** The **Miramichi River** system (Southwest and Northwest Miramichi) has DFO-monitored gaspereau/blueback populations; the Cocagne and Shediac River mouths on the Northumberland Strait side are accessible, angler-tested spots for the run and for summer stragglers.
- **PEI:** The Boughton River and the Three Rivers system (Brudenell, Cardigan, Montague) near Georgetown are known producers, along with river mouths island-wide.

Within any of these, focus on the lower estuary and river-mouth current seams during the spring push, and any fishway or natural pinch point where fish stack up waiting to move upstream.', '[{"label":"Halifax Bloggers, Gaspereau in the Gaspereau | Noticed in Nova Scotia","url":"https://halifaxbloggers.ca/noticedinnovascotia/2017/05/gaspereau-in-the-gaspereau/"},{"label":"DFO, Gaspereau Assessment for the Gulf Region to 2019","url":"https://publications.gc.ca/collections/collection_2024/mpo-dfo/fs70-5/Fs70-5-2024-041-eng.pdf"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'gaspereau'), 3, 'Nova Scotia''s Commercial Gaspereau Fishery', 'Unlike most species in this guide, gaspereau supports a real, longstanding **commercial** fishery in Nova Scotia alongside the recreational one, and it''s worth understanding as local context even if you''re only fishing recreationally.

- Commercial harvest targets adult gaspereau during the May-June upstream spawning migration, using **gillnets** in tidal water and a traditional **weir-and-dip-net** setup (locally called a "square net") in non-tidal inland water.
- The **Gaspereau River** (Annapolis system) is the best-known commercial river, with some family operations having fished it for six generations.
- Regulations require square nets to be pulled from the water during weekly close times, and prohibit fishing certain sections of rivers like the Gaspereau outright.
- Stock status across the region is a concern: the majority of alewife populations assessed have been reported as **in decline**, which is part of why weekly closures and, in some cases, outright recreational quota reductions (e.g., Yarmouth County''s recreational quota was reduced to zero through the end of 2025 by variation order) are in place. Confirm current status before fishing a specific river.', '[{"label":"DFO, Assessment of Gaspereau River Alewife","url":"https://waves-vagues.dfo-mpo.gc.ca/Library/329174.pdf"},{"label":"DFO, 2021 Gaspereau Integrated Fishery Management Plan, Maritimes Region","url":"https://www.dfo-mpo.gc.ca/fisheries-peches/ifmp-gmp/gaspereau-gaspareau/index-eng.html"},{"label":"DFO Maritimes Region, Tidal and freshwater (Diadromous) recreational regulations","url":"https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'gaspereau'), 4, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Light spinning rod or fly rod — gaspereau are small and light tackle makes them fun; also matches their small-mouth requirement for small hooks/flies. |
| Line | 6-10 lb line is plenty. |
| Terminal tackle | Small white/light streamer flies (size 8-12) or an equivalently small light jighead. |
| Dip net | Legal alternative gear in tidal water in both NB and NS during the run (see regulations) — a common family/traditional method alongside hook-and-line. |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'gaspereau'), 5, 'Technique', '1. Locate the run at a river mouth, fishway, or current seam during the spring spawning migration (commonly May).
2. Cast a small white streamer fly or small light jighead across or slightly downstream of the current.
3. **Swing and retrieve at a swift, consistent pace** — similar to swinging a streamer for trout. Gaspereau are aggressive, active feeders during the run and respond well to a steady retrieve rather than a slow finesse presentation.
4. Expect strong fights and jumping for the fish''s size — light tackle makes this genuinely fun, not just easy.
5. If dip netting where legal, work the current edges and eddies where fish stack up against the flow rather than the main current itself.', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'gaspereau'), 6, 'Handling & Table Notes', 'Gaspereau are not well regarded as table fare by most local anglers — they''re bony and have a strong, oily smell, and the common local practice is catch-and-release for hook-and-line anglers, while commercial harvest goes mostly to bait, fishmeal, and smoked/salted product rather than fresh fillets. If keeping fish, ice them promptly given how oily and quick-to-spoil the flesh is (similar to mackerel). Handle released fish quickly and gently — they''re a key forage base for striped bass, so a healthy run benefits the whole estuary food chain.', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'gaspereau'), 7, 'Conservation Notes', 'Gaspereau/alewife populations are broadly reported as declining across much of the region, which is why weekly closures, harvest restrictions on specific rivers, and occasional zero-quota variation orders (as seen in Yarmouth County, NS) exist. Fish this species conservatively, respect posted river-specific closures, and expect rules to vary meaningfully by individual river — check the current DFO notice for the specific water you''re fishing before you go.', '[{"label":"DFO, Assessment of Gaspereau River Alewife","url":"https://waves-vagues.dfo-mpo.gc.ca/Library/329174.pdf"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'gaspereau'), 'NB', 'Tidal and inland (river-run)', 'Tidal: no closed season for angling. Inland: open when a sport fish season is open. Dip nets: Jan 1–Jun 30 with weekly closure Fri 12:00pm–Sun 8:00am.', 'Daily bag and possession limit of 20 (angling and dip netting)', 'None specified', 'No licence for dip netting (except Saint John River inland waters). Provincial angling licence required for inland angling. Jigging for gaspereau is prohibited in inland waters.', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'gaspereau'), 'NS', 'Tidal and inland (river-run)', 'Tidal: no closed season for angling. Inland: coincides with sport fish season openings. Dip nets vary by county, generally Mar 15–Jul with extensive weekly closures; some rivers (e.g. Gaspereau) restrict net size and closed sections.', 'Daily bag and possession limit of 20 (angling and dip netting); some areas reduced further by variation order (e.g. Yarmouth County recreational quota cut to zero through Dec 31 2025) — confirm current status', 'None specified', 'No licence for dip netting. Provincial angling licence required for inland angling. Commercial gillnet/square-net fishery operates in parallel on rivers like the Gaspereau (Annapolis system) — see the dedicated section above.', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'gaspereau'), 'PEI', 'Tidal/saltwater', 'No closed season for hook-and-line recreational take in tidal water', 'No specific bag limit found in current DFO Gulf Region notices for PEI — fish conservatively', 'None specified', 'No provincial licence needed in tidal/salt water.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'gaspereau'), 0, 'Season', 'Main spawning run typically May; stragglers into summer');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'gaspereau'), 1, 'Best Time', 'During the upstream spring migration at river mouths/fishways');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'gaspereau'), 2, 'Gear', 'Light rod, small white streamer fly or small jighead');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'gaspereau'), 3, 'Retrieve', 'Swing and retrieve at a swift, steady pace');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'gaspereau'), 4, 'Table Fare', 'Bony, oily, strong smell — most anglers release; ice promptly if keeping');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'gaspereau'), 5, 'NS Note', 'Also a real commercial gillnet/weir fishery, especially on the Gaspereau River (Annapolis system)');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'gaspereau'), 'Maine Sea Grant, Maine Seafood Guide — Alewife', 'https://seagrant.umaine.edu/maine-seafood-guide/alewife/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'gaspereau'), 'DFO, Gaspereau Assessment for the Gulf Region to 2019', 'https://publications.gc.ca/collections/collection_2024/mpo-dfo/fs70-5/Fs70-5-2024-041-eng.pdf');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'gaspereau'), 'Halifax Bloggers, Gaspereau in the Gaspereau | Noticed in Nova Scotia', 'https://halifaxbloggers.ca/noticedinnovascotia/2017/05/gaspereau-in-the-gaspereau/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'gaspereau'), 'DFO, Assessment of Gaspereau River Alewife', 'https://waves-vagues.dfo-mpo.gc.ca/Library/329174.pdf');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'gaspereau'), 'DFO, 2021 Gaspereau Integrated Fishery Management Plan, Maritimes Region', 'https://www.dfo-mpo.gc.ca/fisheries-peches/ifmp-gmp/gaspereau-gaspareau/index-eng.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'gaspereau'), 'DFO Maritimes Region, Tidal and freshwater (Diadromous) recreational regulations', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'gaspereau'), 'DFO — Recreational Groundfish Fishery, Southern Gulf of St. Lawrence', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'gaspereau'), 0, 'Blueback Herring', 'related-species', 'Alosa aestivalis', 'The two "gaspereau" species run together and look nearly identical at a glance, but two checks separate them reliably. Eye size relative to the snout: an alewife''s eye is wider than the distance from the tip of its snout to the front of the eye (a noticeably large eye), while a blueback herring''s eye is smaller — its width equals that snout-to-eye distance rather than exceeding it. The more reliable check if you can open the belly: peritoneum (the membrane lining the body cavity) colour — alewife have a pale, silvery-white peritoneum, blueback herring have a dark, almost black one. Even with both checks, morphological ID between the two species is reported to be wrong up to 16% of the time, so treat this as a good-faith field call, not a certainty.', 'Blueback herring run the same rivers at the same time as alewife across NB, NS, and PEI, and the two are generally not distinguished by anglers or managed separately — both are simply "gaspereau" or "river herring" in local use and regulation.', 'DFO manages alewife and blueback herring together under the same gaspereau regulations, so misidentifying one for the other has no bag-limit consequence in this fishery — the value here is understanding what you''re actually catching, since the two species can have different population trends river to river.', '/species/gaspereau--variant-0.jpg', 'Smithsonian Environmental Research Center', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Alosa_aestivalis_(S0110)_(15910316357).jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'gaspereau'), 1, 'American Shad', 'lookalike', 'Alosa sapidissima', 'American shad are much larger than gaspereau — adult shad females reach up to 30 inches, dwarfing an adult alewife or blueback herring, which rarely exceed a foot. The jaw is the definitive check: a shad''s lower jaw rises in a gradual slope and tucks into a notch under the upper jaw, while gaspereau (both alewife and blueback herring) have a lower jaw that angles up sharply in a bent, shovel-like shape.', 'American shad run the same rivers as gaspereau at the same time of year, including the Saint John River and the Annapolis River system, so mixed schools of both are common during the spring push.', 'American shad is a COSEWIC prioritized candidate species under active status review, a materially different conservation picture than gaspereau''s mixed-but-generally-fishable status — worth knowing which species is filling your bucket before you assume gaspereau rules apply to a larger fish in the same net or school.', NULL, NULL, NULL, NULL);

-- ===== Landlocked Salmon (Ouananiche) (landlocked-salmon) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('landlocked-salmon', 'Landlocked Salmon (Ouananiche)', 'Salmo salar', 'freshwater', '{"NB","NS"}'::text[], 'A lake-locked form of Atlantic salmon known regionally as ouananiche, prized for acrobatic jumps and hard runs — a niche fishery limited to specific designated lakes in NB (e.g. Tetagouche, Loch Lomond, Grand, Oromocto) and NS (Grand Lake, Halifax County area), fished from spring open water into fall.', '/species/landlocked-salmon.jpg', 'Uwe Kils', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Salmonlarvakils.jpg', true, now())
