delete from species_variants where species_id = (select id from species where slug = 'landlocked-salmon');
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'landlocked-salmon'), 0, 'Know the Fish', 'Landlocked salmon are genetically the same species as sea-run Atlantic salmon (*Salmo salar*) — there are no physical differences between the two forms. What differs is life history: instead of migrating to sea, landlocked populations complete their entire life cycle in freshwater, typically using a lake to feed and grow before returning to a connected river or stream to spawn. In Quebec and parts of Atlantic Canada, this form is traditionally known as **ouananiche**.

Landlocked salmon are fall spawners, and adults prefer clear, cold lakes with summer surface temperatures topping out around 21-24°C (70-75°F); as lakes warm through summer, fish move from the relatively warm surface layer down into cooler deep water. They can grow to 50-85 cm where a lake''s forage base includes smelt or similar baitfish, while populations relying mainly on insects tend to stay smaller (10-30 cm).

Once hooked, landlocked salmon are known for acrobatic jumps and strong, fast runs — the trait behind the old nickname ''leaping landlocked.''', '[{"label":"Maine Dept. of Inland Fisheries & Wildlife — Landlocked Salmon Species Information","url":"https://www.maine.gov/ifw/fish-wildlife/fisheries/species-information/landlocked-salmon.html"},{"label":"Canadian Journal of Fisheries and Aquatic Sciences — Life-History Variability and Conservation Status of Landlocked Atlantic Salmon","url":"https://cdnsciencepub.com/doi/10.1139/cjfas-2018-0413"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'landlocked-salmon'), 1, 'Where to Find Them', '- **Middle Tetagouche Lake and Upper Tetagouche Lake (Chaleur RFA, NB)** — named designated waters for landlocked salmon angling under NB''s fish regulations.
- **Loch Lomond, Grand Lake, and Oromocto Lake (Lower Saint John RFA, NB)** — a cluster of designated landlocked salmon lakes near Saint John.
- **Grand Lake (Halifax County, NS)** — carries a landlocked salmon fishery under Nova Scotia''s angling regulations, with extended-season / reduced-limit rules applying October through March.
- Note: Nova Scotia''s much larger **Lake Ainslie** (headwaters of the Margaree River, Cape Breton) is known primarily for brook trout, white perch, and gaspereau — it is not established as an ouananiche fishery in the sources checked for this guide, despite sometimes being mentioned alongside landlocked salmon waters. Confirm any specific lake against the current NB Fish Regulations Summary or NS Anglers'' Handbook before planning a trip, since landlocked salmon are only legal to angle for in specifically designated waters.', '[{"label":"Fish Nova Scotia — Lake Ainslie","url":"https://www.fishnovascotia.ca/places/lake-ainslie"},{"label":"New Brunswick Fish Regulations Summary 2026-27","url":"https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'landlocked-salmon'), 2, 'When to Go', '### New Brunswick
General landlocked salmon season runs roughly **May 1 – September 30** in designated lakes, with most RFAs otherwise prohibiting landlocked salmon angling entirely outside the named waters.

### Nova Scotia
Most designated landlocked salmon lakes are open **April 1 – September 30**, with some waters (e.g. Goose Harbour Lake) open year-round. Grand Lake and similar extended-season waters typically drop to a reduced catch limit from October through March.

In spring, fish sit near the surface where water has warmed fastest; through summer they push down into cooler, deeper water as the surface heats up, so early and late season generally means shallower, more accessible fish.', '[{"label":"New Brunswick Fish Regulations Summary 2026-27","url":"https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf"},{"label":"Nova Scotia Anglers'' Handbook and 2026 Summary of Regulations","url":"https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'landlocked-salmon'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Fly rod | 6-7 wt, floating line for surface/near-surface fish in spring; sink-tip or full-sink line to reach deeper fish as the season warms. |
| Spinning rod | Medium spinning rod capable of casting small-to-medium spoons and handling a fast-running, jumping fish. |
| Flies/lures | Streamers imitating smelt or other baitfish, small spoons and inline spinners trolled or cast along drop-offs. |
| Extras | Landing net (a jumping fish at boat-side is often lost without one), drag set appropriately loose for sudden runs. |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'landlocked-salmon'), 4, 'Technique', '**Spring surface fishing:** work streamers or small spoons along shorelines and points where fish are holding in the warmer surface layer — early morning and evening are prime, similar to trout behaviour.

**Summer depth fishing:** as lakes stratify, target the thermocline or deeper structure with a sink-tip line or by trolling a spoon/streamer at depth — fish follow cooler water down and won''t be found shallow in the heat of the day.

**Fighting the fish:** keep your rod tip up and be ready for immediate, often repeated jumps right after the hookset — a controlled drag and quick reactions land more fish than trying to muscle a leaping landlocked salmon back to the boat.

**Surface feeding:** landlocked salmon will rise to take insects off the surface much like a trout, so a well-placed dry fly or small popper during a hatch can also produce, especially on calm evenings.', '[{"label":"Orvis News — Fish Facts: Landlocked Salmon (Salmo salar sebago)","url":"https://news.orvis.com/fly-fishing/fish-facts-landlocked-salmon-salmo-salar-sebago"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'landlocked-salmon'), 5, 'Handling & Release', '- Land fish promptly — extended fights in warmer summer surface water raise release mortality risk, similar to sea-run salmon.
- Use a net to control a jumping fish boat-side rather than trying to hand-land it, which often results in a lost hook or a dropped fish that''s already exhausted.
- Wet hands before handling, support horizontally, and minimize air exposure for any fish you plan to release, including those over the maximum retention size.
- Nova Scotia enforces an upper release size on landlocked salmon (commonly a maximum around 63 cm, all larger fish released) in addition to a legal minimum — check the current Anglers'' Handbook for the exact figures on your lake.', '[{"label":"Nova Scotia Anglers'' Handbook and 2026 Summary of Regulations","url":"https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'landlocked-salmon'), 6, 'Conservation & Consumption Notes', 'Landlocked salmon populations are limited to specific lake systems and are managed more conservatively than typical stocked trout — this shows up as low daily bag limits (1-2 fish), minimum size limits, and in Nova Scotia''s case a maximum release size designed to protect the largest, most fecund breeding fish. Fish only the specifically designated waters listed in the current provincial regulations; landlocked salmon angling is prohibited by default everywhere else. No region-specific mercury or consumption advisory for landlocked salmon turned up in current provincial sources for this guide.', '[{"label":"New Brunswick Fish Regulations Summary 2026-27","url":"https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'landlocked-salmon'), 'NB', 'Designated freshwater lakes only', '~May 1–Sep 30 in designated waters (varies by RFA)', 'Typically 1-2 fish/day depending on the specific lake', 'Fork length minimum 35 cm, maximum 63 cm', 'Legal only in specifically designated waters — e.g. Middle/Upper Tetagouche Lakes (Chaleur RFA); Loch Lomond, Grand, and Oromocto Lakes (Lower Saint John RFA). Prohibited elsewhere by default. Regular NB angling licence required.', 'https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'landlocked-salmon'), 'NS', 'Designated freshwater lakes only', 'Apr 1–Sep 30 in most designated lakes; some waters (e.g. Goose Harbour Lake) open year-round', '2 fish/day', 'Minimum 35 cm (13.8 in); all fish over 63 cm (24.8 in) must be released', 'Grand Lake, Halifax County is a designated landlocked salmon water. Tagging requirements have been eliminated for fish between 48-63 cm per the current handbook. General Fishing Licence required.', 'https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'landlocked-salmon'), 0, 'Season', 'Spring through fall in designated lakes only (varies NB/NS)');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'landlocked-salmon'), 1, 'NB Bag Limit', '1-2 fish/day, 35-63 cm, designated waters only');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'landlocked-salmon'), 2, 'NS Bag Limit', '2 fish/day, min 35 cm, must release over 63 cm');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'landlocked-salmon'), 3, 'Best Time', 'Spring (shallow/surface) and fall; fish go deep as lakes warm in summer');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'landlocked-salmon'), 4, 'Best Gear', '6-7 wt fly rod with streamers, or medium spinning rod with small spoons');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'landlocked-salmon'), 5, 'Key Waters', 'Tetagouche Lakes, Loch Lomond, Grand & Oromocto Lakes (NB); Grand Lake, Halifax County (NS)');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'landlocked-salmon'), 'New Brunswick Fish Regulations Summary 2026-27', 'https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'landlocked-salmon'), 'Nova Scotia Anglers'' Handbook and 2026 Summary of Regulations', 'https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'landlocked-salmon'), 'Maine Dept. of Inland Fisheries & Wildlife — Landlocked Salmon Species Information', 'https://www.maine.gov/ifw/fish-wildlife/fisheries/species-information/landlocked-salmon.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'landlocked-salmon'), 'Canadian Journal of Fisheries and Aquatic Sciences — Life-History Variability and Conservation Status of Landlocked Atlantic Salmon', 'https://cdnsciencepub.com/doi/10.1139/cjfas-2018-0413');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'landlocked-salmon'), 'Orvis News — Fish Facts: Landlocked Salmon (Salmo salar sebago)', 'https://news.orvis.com/fly-fishing/fish-facts-landlocked-salmon-salmo-salar-sebago');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'landlocked-salmon'), 'Fish Nova Scotia — Lake Ainslie', 'https://www.fishnovascotia.ca/places/lake-ainslie');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'landlocked-salmon'), 0, 'Sea-Run Atlantic Salmon', 'form', NULL, 'Genetically identical to landlocked salmon — same species, no physical differences between the two forms. What differs is life history: sea-run fish migrate to the ocean to feed and grow before returning to their natal river, while landlocked fish complete their entire life cycle using a lake instead of the ocean.', 'Sea-run fish are found in open river systems like the Miramichi (NB) and Margaree (NS); landlocked fish are confined to the specific designated lakes covered by this entry.', 'Completely different regulations apply. Sea-run Atlantic salmon retention is prohibited region-wide (catch-and-release only), while landlocked salmon in designated lakes may be retained within posted bag and size limits. Fishing a designated landlocked lake does not give you any exemption to keep a sea-run fish, and vice versa.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'landlocked-salmon'), 1, 'Brown Trout', 'lookalike', 'Salmo trutta', 'Landlocked salmon have a slightly forked tail with a thin caudal peduncle, a maxillary (upper jaw) that does not extend much past the eye, and a darker adipose fin with little to no spotting. Brown trout have a nearly square tail with a thicker peduncle, a maxillary that often extends slightly past the eye, more numerous reddish spots overall, and a larger adipose fin that''s often orange-tinged with visible spots. Post-spawn male landlocked salmon can turn dark and golden in late fall, making them look especially like a brown trout at first glance.', 'Any designated landlocked salmon lake that also holds brown trout — check the current NB/NS regulations for which specific lakes carry both species.', 'Worth checking carefully where bag limits or size rules differ between the two species in the same lake.', '/species/landlocked-salmon--variant-1.jpg', 'Eric Engbretson for U.S. Fish and Wildlife Service', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Salmo_trutta.jpg');

-- ===== Largemouth Bass (largemouth-bass) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('largemouth-bass', 'Largemouth Bass', 'Micropterus salmoides', 'freshwater', '{"NB"}'::text[], 'Introduced, invasive bass species now established in several lakes and river arms of the Saint John River system and the St. Croix River in New Brunswick. As of 2026, NB requires anglers to keep — not release — any largemouth bass caught in the affected Recreational Fishery Areas. DFO does not currently report an established population in Nova Scotia or PEI.', '/species/largemouth-bass.jpg', 'USFWS Mountain Prairie', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Largemouth_Bass_(Micropterus_salmoides)_June_2023.jpg', true, now())
on conflict (slug) do update set
  common_name = excluded.common_name,
  scientific_name = excluded.scientific_name,
  category = excluded.category,
  provinces = excluded.provinces,
  summary = excluded.summary,
  image_path = excluded.image_path,
  image_credit = excluded.image_credit,
  image_license = excluded.image_license,
  image_source_url = excluded.image_source_url,
  is_published = true,
  updated_at = now();
delete from guide_sections where species_id = (select id from species where slug = 'largemouth-bass');
delete from regulations where species_id = (select id from species where slug = 'largemouth-bass');
delete from quick_reference where species_id = (select id from species where slug = 'largemouth-bass');
delete from species_sources where species_id = (select id from species where slug = 'largemouth-bass');
