insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'largemouth-bass'), 0, 'Know the Fish', 'Largemouth bass (*Micropterus salmoides*) are a deep-bodied, olive-green freshwater gamefish with a dark, blotchy horizontal band along the flank and a jaw hinge that extends back past the eye — the classic feature separating them from smallmouth bass. They''re an ambush/structure-oriented predator, relating heavily to weed beds, docks, fallen timber, and other cover, and feed on baitfish, crayfish, frogs, and large insects.

Largemouth bass are not native to New Brunswick or anywhere in Atlantic Canada. DFO''s species profile places their introduced NB range specifically in the **St. Croix River** and the **Saint John River system**, including the Meduxnekeag River and the Mactaquac Arm/headpond, with further reports from Grand Lake, Washademoak Lake, Oromocto Lake, and an illegal introduction into Spednic Lake. DFO''s profile states the species is **not currently reported in Nova Scotia, Prince Edward Island, or Newfoundland and Labrador** — so despite occasional angler chatter, there''s no confirmed established NS or PEI population at this time.', '[{"label":"DFO, Largemouth Bass species profile","url":"https://www.dfo-mpo.gc.ca/species-especes/profiles-profils/largemouthbass-achigangrandebouche-eng.html"},{"label":"New Brunswick Invasive Species Council, Invasive Gamefish","url":"https://www.nbinvasives.ca/invasive-gamefish"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'largemouth-bass'), 1, 'Where to Find Them', 'All confirmed NB largemouth bass water sits in the lower/central Saint John River drainage and the St. Croix River on the Maine border:

- **Grand Lake, Washademoak Lake, and Oromocto Lake** — all warm, weedy, connected to the Saint John River system.
- **Mactaquac Arm / Mactaquac headpond**, and the **Meduxnekeag River**, both tied directly to the Saint John River.
- **Spednic Lake** on the St. Croix system, from an illegal introduction.

Look for the same cover largemouth relate to everywhere: lily pads, flooded timber, docks, and soft-bottom weedy bays — largemouth prefer noticeably slower, warmer, weedier water than the smallmouth bass NB anglers are more used to targeting.', '[{"label":"DFO, Largemouth Bass species profile","url":"https://www.dfo-mpo.gc.ca/species-especes/profiles-profils/largemouthbass-achigangrandebouche-eng.html"},{"label":"Fish''n Canada, The First-Ever \"Official\" Atlantic Canada Largemouth Bass","url":"https://fishncanada.com/the-first-ever-official-atlantic-canada-largemouth-bass/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'largemouth-bass'), 2, 'When to Go', 'Largemouth bass in this region follow the same general pattern as elsewhere in their range: they spawn in shallow water in late spring once temperatures climb into the mid-60s°F, then hold tight to cover through summer, feeding most actively in low light around dawn and dusk. Fall sees another feeding push as fish bulk up before winter. Given the short, cool Maritime season, expect the whole cycle to run later and compress compared to bass fisheries further south.', '[{"label":"DFO, Biological Synopsis of Largemouth Bass (Micropterus salmoides)","url":"https://publications.gc.ca/collections/collection_2010/mpo-dfo/Fs97-4-2884-eng.pdf"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'largemouth-bass'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | 6.5–7 ft medium to medium-heavy spinning or baitcasting rod. |
| Line | 10–17 lb monofilament or fluorocarbon; braid with a fluoro leader around heavy cover. |
| Lures | Soft plastic worms/creature baits rigged weedless, spinnerbaits, topwater frogs and poppers, crankbaits along deeper drop-offs. |
| Extras | Needle-nose pliers, a scale/measuring board if you plan to report or photograph a mandatory-retention catch. |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'largemouth-bass'), 4, 'Technique', '1. Fish the edges of visible cover — lily pad points, dock pilings, laydown logs — rather than open water; largemouth ambush from cover rather than roam.
2. Work a weedless soft-plastic (Texas-rigged worm or creature bait) slowly through pads and timber, letting it fall on slack line into every pocket.
3. Throw topwater (poppers, walking baits, frogs) at first and last light when bass are shallow and feeding aggressively.
4. In the heat of summer, switch to deeper cover or drop-offs adjacent to the shallow spawning/feeding areas, working crankbaits or Carolina-rigged plastics.
5. Set the hook with a firm sweep rather than a trout-style lift — largemouth have a hard, bony mouth plate.', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'largemouth-bass'), 5, 'Handling & Release — Read This Before You Let One Go', 'This is the key regulatory fact for this species in New Brunswick: **effective April 1, 2026, largemouth bass must be retained (killed), not released, if caught in the Restigouche, Chaleur, Miramichi, Southeast, Inner Bay of Fundy, or Upper Saint John Recreational Fishery Areas.** This is one of five species (with black crappie, chain pickerel, muskellunge, and smallmouth bass) covered by NB''s new invasive-species mandatory-retention condition of licence. Releasing a largemouth bass caught in one of those RFAs can draw a fine of $100–$500 under the Fish and Wildlife Act.

Fish must be humanely euthanized immediately (a swift blow to the head) and can be kept for food or delivered frozen to a local Department of Natural Resources office; report the catch (date, location, photo) to DNR. Given that essentially all known NB largemouth water sits within the Saint John River system, most anglers targeting this species should assume the retention rule applies — confirm your exact RFA with GNB''s Fishing Regulations Web/Mobile Map before you go.', '[{"label":"Government of New Brunswick, New recreational fishing rules to take effect","url":"https://www.gnb.ca/en/news/n-b.2026.03.new-recreational-fishing-rules-take-effect.html"},{"label":"Government of New Brunswick, Mandatory retention of invasive species","url":"https://www.gnb.ca/en/topic/environment-resources/biodiversity-conservation/invasive-species/invasive-fish.html"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'largemouth-bass'), 6, 'Conservation & Consumption Notes', 'Largemouth bass compete directly with native species and, alongside chain pickerel and smallmouth bass, are flagged by NB''s Invasive Species Council as a threat to native fish communities through predation and competition for food and habitat. There is no conservation reason to protect or release this species in NB waters — quite the opposite, which is the basis for the 2026 mandatory-retention rule. Never move live largemouth bass (or bait bucket water) between lakes; that''s the most likely way any remaining unaffected NB lakes could get seeded next.', '[{"label":"New Brunswick Invasive Species Council, Invasive Gamefish","url":"https://www.nbinvasives.ca/invasive-gamefish"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'largemouth-bass'), 'NB', 'Freshwater', 'See current GNB Fish Regulations Summary for open season dates by water — a valid NB angling licence is required', 'No release permitted in Restigouche, Chaleur, Miramichi, Southeast, Inner Bay of Fundy, and Upper Saint John RFAs — mandatory retention condition of licence applies', 'None specified — retention required regardless of size', 'Effective April 1, 2026: largemouth bass must be retained, not released, if caught in the RFAs listed above. Fines of $100–$500 apply for releasing one. Fish must be humanely euthanized; keep for consumption or deliver frozen to a local DNR office, and report the catch to DNR. Confirm your RFA using the GNB Fishing Regulations Web/Mobile Map.', 'https://www.gnb.ca/en/topic/environment-resources/biodiversity-conservation/invasive-species/invasive-fish.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'largemouth-bass'), 'NS', 'Freshwater', 'Not applicable', 'Not applicable', 'Not applicable', 'DFO''s species profile states largemouth bass is not currently reported as established in Nova Scotia. No NS regulation entry exists for this species; if you believe you''ve caught one in NS, treat it as a reportable potential new introduction rather than a normal catch.', 'https://www.dfo-mpo.gc.ca/species-especes/profiles-profils/largemouthbass-achigangrandebouche-eng.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'largemouth-bass'), 'PEI', 'Freshwater', 'Not applicable', 'Not applicable', 'Not applicable', 'DFO''s species profile states largemouth bass is not currently reported as established in Prince Edward Island.', 'https://www.dfo-mpo.gc.ca/species-especes/profiles-profils/largemouthbass-achigangrandebouche-eng.html', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'largemouth-bass'), 0, 'Status', 'Introduced/invasive in NB only — not established in NS or PEI per DFO');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'largemouth-bass'), 1, 'Key Rule', 'MUST-KEEP in NB''s Restigouche/Chaleur/Miramichi/Southeast/Inner Bay of Fundy/Upper Saint John RFAs — no release');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'largemouth-bass'), 2, 'Where', 'Grand Lake, Washademoak Lake, Oromocto Lake, Mactaquac Arm, Meduxnekeag River, Spednic Lake (St. Croix)');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'largemouth-bass'), 3, 'Best Time', 'Late spring spawn through summer; dawn/dusk for topwater');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'largemouth-bass'), 4, 'Gear', 'Medium-heavy spinning/baitcasting rod, 10-17 lb line, weedless soft plastics and topwater');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'largemouth-bass'), 'DFO, Largemouth Bass species profile', 'https://www.dfo-mpo.gc.ca/species-especes/profiles-profils/largemouthbass-achigangrandebouche-eng.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'largemouth-bass'), 'New Brunswick Invasive Species Council, Invasive Gamefish', 'https://www.nbinvasives.ca/invasive-gamefish');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'largemouth-bass'), 'Government of New Brunswick, New recreational fishing rules to take effect', 'https://www.gnb.ca/en/news/n-b.2026.03.new-recreational-fishing-rules-take-effect.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'largemouth-bass'), 'Government of New Brunswick, Mandatory retention of invasive species', 'https://www.gnb.ca/en/topic/environment-resources/biodiversity-conservation/invasive-species/invasive-fish.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'largemouth-bass'), 'Fish''n Canada, The First-Ever "Official" Atlantic Canada Largemouth Bass', 'https://fishncanada.com/the-first-ever-official-atlantic-canada-largemouth-bass/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'largemouth-bass'), 'DFO, Biological Synopsis of Largemouth Bass (Micropterus salmoides)', 'https://publications.gc.ca/collections/collection_2010/mpo-dfo/Fs97-4-2884-eng.pdf');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'largemouth-bass'), 0, 'Smallmouth Bass', 'lookalike', 'Micropterus dolomieu', 'On a largemouth, the jaw hinge extends back well past the eye; on a smallmouth, the corner of the upper jaw lines up roughly even with the eye. A largemouth''s dorsal fin has a deep notch that can look like two separate fins, while a smallmouth''s dorsal fin is joined by only a shallow notch, appearing almost continuous. Colour also differs: largemouth are greener with a single bold horizontal stripe running eye-to-tail, while smallmouth are brown to bronze with faint vertical bars running gill-to-tail rather than a horizontal stripe.', 'Smallmouth bass are far more widespread across NB, NS, and PEI, including the same Saint John River system that holds largemouth. Largemouth remain confirmed only in specific NB waters (Grand Lake, Washademoak Lake, Oromocto Lake, Mactaquac Arm, Meduxnekeag River, Spednic Lake).', 'The two species carry different mandatory-retention rules under NB''s April 2026 invasive-species regulations: largemouth must be retained in the Restigouche, Chaleur, Miramichi, Southeast, Inner Bay of Fundy, and Upper Saint John RFAs, while smallmouth''s mandatory-retention list (Restigouche, Chaleur, Miramichi, Southeast) does not include Inner Bay of Fundy or Upper Saint John. Misidentifying the species can mean releasing a fish that was legally required to be kept, or vice versa — both carry $100-$500 fines.', '/species/largemouth-bass--variant-0.jpg', 'Timothy Knepp, U.S. Fish and Wildlife Service', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Micropterus_dolomieu2.jpg');

-- ===== Muskellunge (muskellunge) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('muskellunge', 'Muskellunge', 'Esox masquinongy', 'freshwater', '{"NB"}'::text[], 'A rare, introduced trophy predator found only in the Saint John River system in New Brunswick — long a dedicated catch-and-release fishery built by a small, passionate community of local muskie anglers. A major 2026 regulatory change now requires mandatory retention (killing) of muskellunge caught in the Southwest RFA, upending the catch-and-release culture this fishery was built on — verify current rules carefully before you fish.', '/species/muskellunge.jpg', 'Knepp, Timothy - U.S. Fish and Wildlife Service', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Muskellunge_USFWS.jpg', true, now())
