insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'muskellunge'), 0, 'Know the Fish', 'Muskellunge (*Esox masquinongy*) are the largest member of the pike family — a long, torpedo-shaped predator with a duck-bill snout, sharp teeth, and a pattern of dark spots or vertical bars over a green-to-brown body (the reverse of a pike''s light markings on dark). They''re apex ambush predators, holding near weed edges, drop-offs, and current breaks, and famously earn the nickname "the fish of 10,000 casts" for how few strikes even experienced anglers get per outing.

Muskellunge are not native to New Brunswick or anywhere in Atlantic Canada. They were introduced into the Saint John River system in the late 1970s and have since expanded roughly 550 km through the river, with muskies found in sufficient numbers to target by 2004 in the mid-Saint John River, and confirmed natural reproduction downstream of the Mactaquac Generating Station documented by university research.', '[{"label":"Muskies Canada, Saint John River Chapter","url":"https://muskiescanada.ca/saint-john-river/"},{"label":"UNB Newsroom, UNB student project examines the sustainability of the St. John River''s muskie population","url":"https://blogs.unb.ca/newsroom/2021/05/muskie-population.php"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'muskellunge'), 1, 'Where to Find Them', 'The entire fishery is confined to the **Saint John River and its tributaries in New Brunswick**, with the core of the sport-fishing activity historically centered on the **Mactaquac headpond** and the **lower river below the Mactaquac Dam**, extending through the mid-Saint John River. This is a genuinely niche, specialty fishery — there is no muskellunge population anywhere else in NB, NS, or PEI.', '[{"label":"Muskies Canada, Saint John River Chapter","url":"https://muskiescanada.ca/saint-john-river/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'muskellunge'), 2, 'When to Go', 'Muskie fishing on the Saint John River is a warm-season pursuit, with activity building through summer and into fall as fish feed heavily ahead of winter — the local chapter''s events have historically run through the fall, including a notable fall event in 2008. Cooler water in spring and fall tends to produce more aggressive, followable fish; the heat of mid-summer can shut fish down during the day, pushing the best activity to dawn, dusk, and overcast conditions.', '[{"label":"Muskies Canada, Saint John River Chapter","url":"https://muskiescanada.ca/saint-john-river/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'muskellunge'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Heavy-power casting rod, 7.5–8.5 ft, rated for big baits. |
| Reel | Baitcasting reel with a strong drag, spooled with 65-100 lb braid. |
| Leader | Heavy wire or fluorocarbon leader (80 lb+) — mandatory given muskie teeth. |
| Lures | Large bucktail spinners, big crankbaits, jerkbaits, and glide baits (8-12+ inches). |
| Landing gear | A large net with a rubber/knotless bag, long-nose pliers, jaw spreaders, and cutters — handling a fish this size safely requires the right tools even before you factor in any retention requirement. |', '[{"label":"Destination Ontario, Muskie fishing","url":"https://www.destinationontario.com/en-ca/articles/muskie-fishing-ontario"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'muskellunge'), 4, 'Technique', '1. Cast large bucktails, crankbaits, or jerkbaits tight to weed edges, current breaks, and drop-offs — muskie relate hard to structure and ambush points.
2. Retrieve at a fast, steady pace for bucktails; muskie anglers generally favor speed over finesse to trigger reaction strikes.
3. **Always finish every retrieve with a figure-8** boatside: on the last few feet of retrieve, sweep the lure in a wide figure-8 pattern before lifting it out — muskie frequently follow a lure without striking, and the figure-8 is what converts a follow into a bite.
4. Trolling bucktail spinners just above submerged vegetation is an effective way to cover the larger stretches of the headpond and locate active fish.
5. Handle every fish quickly and support it horizontally — muskie are a demanding species to release properly even under normal catch-and-release circumstances.', '[{"label":"Wikipedia, Figure eight (angling)","url":"https://en.wikipedia.org/wiki/Figure_eight_(angling)"},{"label":"Destination Ontario, Muskie fishing","url":"https://www.destinationontario.com/en-ca/articles/muskie-fishing-ontario"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'muskellunge'), 5, 'IMPORTANT: Regulatory Change You Must Verify Before Fishing', 'This fishery sits at the center of a real conflict right now, and you need to check the current rule for your exact location before you fish.

**Historically**, the Saint John River muskie fishery was built entirely around voluntary catch-and-release: Muskies Canada''s Saint John River Chapter (est. 2005/2006) has for two decades promoted careful handling and 100% release, and muskellunge held no sportfish designation or specific protective status under NB regulations — meaning there was no legal retention limit either way, and the fishery survived on angler ethics alone.

**As of April 1, 2026**, that changed materially: New Brunswick''s new invasive-species mandatory retention condition of licence lists **muskellunge among the five species anglers must retain (kill), not release**, when caught in the **Restigouche, Chaleur, Miramichi, Southeast, Inner Bay of Fundy, and Southwest** Recreational Fishery Areas. Multiple independent sources confirm the Southwest RFA is on that list for muskellunge specifically — and the Saint John River''s core muskie water around Fredericton/Mactaquac falls within or near that region. Fines for releasing a mandatory-retention species run $100-$500 under the Fish and Wildlife Act, and a caught fish must be humanely euthanized, then can be kept for food or delivered frozen to a local DNR office, with the catch reported to DNR.

**Before you fish for muskellunge anywhere on the Saint John River system, confirm two things directly with GNB (Fishing Regulations Web/Mobile Map, or by calling your local DNR office): (1) exactly which RFA boundary you''ll be fishing in, and (2) whether the mandatory retention rule is currently being enforced for muskellunge in that specific stretch of river.** This is a fast-moving regulatory area, it runs directly counter to the conservation ethic this fishery was built on, and getting it wrong in either direction (illegally releasing a must-keep fish, or illegally killing a fish where the rule doesn''t apply) carries real consequences. This guide could not independently confirm whether any exception or transition provision exists for the historic Saint John River catch-and-release fishery — treat that as an open question requiring direct confirmation with NB Natural Resources before your trip.', '[{"label":"Government of New Brunswick, New recreational fishing rules to take effect","url":"https://www.gnb.ca/en/news/n-b.2026.03.new-recreational-fishing-rules-take-effect.html"},{"label":"Government of New Brunswick, Mandatory retention of invasive species","url":"https://www.gnb.ca/en/topic/environment-resources/biodiversity-conservation/invasive-species/invasive-fish.html"},{"label":"Wired2Fish, New Brunswick Anglers Ordered To Kill Largemouth Bass (covers full 5-species mandate)","url":"https://www.wired2fish.com/news/new-brunswick-anglers-ordered-to-kill-largemouth-bass"},{"label":"Muskies Canada, Saint John River Chapter","url":"https://muskiescanada.ca/saint-john-river/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'muskellunge'), 6, 'Conservation & Consumption Notes', 'Prior to 2026, this fishery''s entire conservation model rested on catch-and-release, and it produced genuinely large fish — a NB catch-and-release record of 52 inches / 27-inch girth (roughly 48 lb) is held by a chapter director, with another fish over 50 inches and 42+ lb caught during a fall chapter event. That size structure took decades of protective handling to build.

The 2026 mandatory-retention rule is framed by NB as invasive-species control, treating muskellunge the same as chain pickerel and largemouth bass. Whatever your view on that policy, the practical reality for anglers is: fish conservatively, know your RFA, follow whatever the current rule requires exactly, and expect this to remain a live, possibly-changing regulatory issue for the next few seasons as the local angling and conservation community responds.', '[{"label":"Muskies Canada, Saint John River Chapter","url":"https://muskiescanada.ca/saint-john-river/"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'muskellunge'), 'NB', 'Freshwater', 'No person may fish for muskellunge except by angling; close times apply on specific waters per the current GNB Fish Regulations Summary — confirm exact dates for the stretch of the Saint John River you plan to fish', 'UNVERIFIED / CHANGING: as of April 1, 2026, muskellunge caught in the Restigouche, Chaleur, Miramichi, Southeast, Inner Bay of Fundy, and Southwest RFAs must be retained (killed), not released, under NB''s new invasive-species mandatory retention condition of licence — this directly reverses the historic catch-and-release norm on the Saint John River fishery. Confirm current status and exact RFA boundaries directly with NB Natural Resources before fishing.', 'Not independently confirmed — retention requirement in listed RFAs applies regardless of size', 'This guide could not independently verify whether any exception exists for the traditional Saint John River catch-and-release muskie fishery under the 2026 rule. Fines for illegal release are $100-$500 under the Fish and Wildlife Act. Verify directly with GNB before your trip — flagged here explicitly for human double-check before publishing.', 'https://www.gnb.ca/en/topic/environment-resources/biodiversity-conservation/invasive-species/invasive-fish.html', '2026 — confirm current status directly with GNB before relying on this');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'muskellunge'), 0, 'Where', 'Saint John River system only — Mactaquac headpond and downstream, extending through the mid-river');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'muskellunge'), 1, 'Status', 'Introduced in the late 1970s; only muskellunge population in NB/NS/PEI');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'muskellunge'), 2, 'Historic Practice', '100% voluntary catch-and-release, promoted by Muskies Canada''s Saint John River Chapter since 2005');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'muskellunge'), 3, '2026 CHANGE — VERIFY BEFORE FISHING', 'New mandatory-retention rule may require killing any muskellunge caught in the Southwest RFA and other listed RFAs — confirm with NB Natural Resources directly');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'muskellunge'), 4, 'Gear', 'Heavy casting rod, 65-100 lb braid, wire/heavy fluoro leader, big bucktails/jerkbaits, large net');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'muskellunge'), 5, 'Technique', 'Fast retrieve tight to structure, always finish with a figure-8 boatside');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'muskellunge'), 'Muskies Canada, Saint John River Chapter', 'https://muskiescanada.ca/saint-john-river/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'muskellunge'), 'UNB Newsroom, UNB student project examines the sustainability of the St. John River''s muskie population', 'https://blogs.unb.ca/newsroom/2021/05/muskie-population.php');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'muskellunge'), 'Government of New Brunswick, New recreational fishing rules to take effect', 'https://www.gnb.ca/en/news/n-b.2026.03.new-recreational-fishing-rules-take-effect.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'muskellunge'), 'Government of New Brunswick, Mandatory retention of invasive species', 'https://www.gnb.ca/en/topic/environment-resources/biodiversity-conservation/invasive-species/invasive-fish.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'muskellunge'), 'Wired2Fish, New Brunswick Anglers Ordered To Kill Largemouth Bass', 'https://www.wired2fish.com/news/new-brunswick-anglers-ordered-to-kill-largemouth-bass');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'muskellunge'), 'Destination Ontario, Muskie fishing', 'https://www.destinationontario.com/en-ca/articles/muskie-fishing-ontario');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'muskellunge'), 0, 'Northern Pike', 'lookalike', 'Esox lucius', 'Pike show light, bean-shaped yellowish spots scattered over a darker green body — the reverse of a muskie''s dark spots/bars over a lighter body. The surest check is the cheek and gill cover: pike have a fully scaled cheek but only the upper half of the gill cover (operculum) is scaled, the lower half is bare — on a muskie, the lower half of BOTH the cheek and gill cover are bare. Counting sensory pores on the underside of the lower jaw also works: pike have 4-5 pores per side, muskellunge have 6-9.', 'Northern pike are a recent, spreading invasive in the Saint John River watershed, moving down from upstream/Maine waters into the same system muskellunge occupy — expect the two species to increasingly overlap in the mid-to-lower Saint John River.', 'Both species are now on NB''s 2026 mandatory-retention invasive list, so misidentifying one for the other doesn''t change what you''re legally required to do with it in a listed RFA — but confirming which species you actually caught still matters for accurate catch reporting to DNR.', '/species/muskellunge--variant-0.jpg', 'George Chernilevsky', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Esox_lucius_2021_G1.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'muskellunge'), 1, 'Chain Pickerel', 'lookalike', 'Esox niger', 'Chain pickerel are much smaller (typically under 24 inches) with a distinctive dark chain-link/mesh pattern over a lighter body, versus a muskie''s spots or vertical bars. The cheek and gill cover are fully scaled top to bottom on a chain pickerel — neither the muskellunge (bare lower cheek and gill cover) nor the pike (bare lower gill cover only) share this trait.', 'Established and spreading in NB, including waters connected to the Saint John River system — chain pickerel are smaller and more common in weedy backwaters than muskellunge.', 'Chain pickerel is also on NB''s mandatory-retention invasive list province-wide as of April 2026. A small pike-family fish with a full scale pattern top to bottom on cheek and gill cover is very unlikely to be a muskellunge, so don''t assume a mandatory-retention muskie situation just because it''s toothy and pike-shaped.', '/species/muskellunge--variant-1.jpg', 'Noel Burkhead/Howard Jelks', 'CC BY-SA 2.5', 'https://commons.wikimedia.org/wiki/File:Esox_niger.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'muskellunge'), 2, 'Tiger Muskie', 'related-species', 'Esox masquinongy x Esox lucius', 'A naturally-occurring, sterile hybrid of muskellunge and northern pike. Shows narrow, irregular dark vertical bars that merge and interlock toward the back (distinct from a pure muskie''s cleaner spot/bar pattern), rounded tail lobes rather than a muskie''s more pointed tail, and 10-16 jaw pores — overlapping both parent species'' counts. Cheeks and jaws are usually spotted.', 'Not stocked or confirmed established in NB — flagged here because pike and muskellunge now overlap in the Saint John River system, creating at least the theoretical conditions for a wild-produced hybrid to show up. Treat any unusual-patterned pike-family fish from that river as worth a closer look and a photo.', 'If the 2026 mandatory-retention rule applies to muskellunge in your RFA, a true hybrid''s status is a genuine grey area this guide could not resolve — photograph the cheek/gill-cover scale pattern and jaw pores and check with GNB before deciding whether to release or retain an unusual-looking fish.', NULL, NULL, NULL, NULL);

-- ===== Pollock (pollock) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('pollock', 'Pollock', 'Pollachius virens', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Hard-fighting member of the cod family caught from wharves, breakwaters, and boats throughout the Maritimes, with the Bay of Fundy and Nova Scotia''s Atlantic coast the strongest shore fisheries. Note: Gulf-side waters (NB Gulf shore, PEI, NS''s Northumberland Strait) currently run zero retention on pollock — catch and release only there.', '/species/pollock.jpg', 'Gervais et Boulart', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Pollachius_virens_Gervais.jpg', true, now())
