insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'pollock'), 2, 'Gulf Region (NB, PEI, NS Northumberland Strait)', 'Catch and release only — zero retention on pollock in 2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'pollock'), 3, 'Maritimes Region (NS Bay of Fundy / Atlantic coast)', 'Retainable — counts toward 10/day (Halifax Harbour and west) or 5/day (Hartlen Point east) groundfish bag limit');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'pollock'), 4, 'Technique', 'Snap-jig a jig/spoon/bucktail with sharp lifts and slack-line drops; fast steady retrieve when fish are surface-feeding');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'pollock'), 5, 'Bait option', 'Worms or oily/smoked herring fished near wharf pilings and current seams');
