insert into species_sources (species_id, label, url) values ((select id from species where slug = 'pollock'), 'fishing.news, Pollock jigging, a simple and effective technique', 'https://www.fishing.news/news/44721/pollock-jigging-a-simple-and-effective-technique');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'pollock'), 0, 'Atlantic Cod', 'lookalike', 'Gadus morhua', 'Cod has a rounded/square tail (pollock''s is forked), an obvious chin barbel (pollock''s is tiny or absent, especially on bigger fish), and an upper jaw that projects past the lower (pollock''s lower jaw protrudes). Cod also runs brown-to-greenish and mottled with dark spots, while pollock is olive-green to smoky black on the back with a cleaner, less-blotched flank and a straighter, less obviously pale lateral line than cod''s curved one.', 'Same wharves, breakwaters, and offshore structure as pollock region-wide; cod stays closer to bottom while pollock will chase bait right to the surface.', 'The retention rules differ sharply: pollock is zero-retention in the DFO Gulf Region (NB, PEI, NS Northumberland Strait) in 2026, while cod has a short open window there with a 5-fish sub-limit. Getting the jaw/tail/barbel check backwards and keeping a cod thinking it''s a legal pollock, or vice versa, is a real and avoidable violation on the Gulf side.', '/species/pollock--variant-0.jpg', 'Wilhelm Thomas Fiege', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Atlantic_Cod,_Atlantischer_Kabeljau_(Gadus_morhua).jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'pollock'), 1, 'Haddock', 'lookalike', 'Melanogrammus aeglefinus', 'Haddock has a dark, straight lateral line and a distinct dark oval blotch ("Devil''s thumbprint") above the pectoral fin, both absent on pollock. Haddock also lacks pollock''s protruding lower jaw and forked tail is less pronounced, with a cleaner silvery-grey body versus pollock''s olive-to-black back.', 'Offshore banks and ledges, most associated with the Bay of Fundy/NS Atlantic side rather than shallow Gulf inshore water.', 'Haddock shares pollock''s zero-retention status in the 2026 DFO Gulf Region notice — both must be released in NB, PEI, and NS''s Northumberland Strait shore. On the DFO Maritimes Region side (NS Atlantic coast/Bay of Fundy), haddock retention is permitted within the same aggregate bag limit as pollock, so the practical handling is identical there.', '/species/pollock--variant-1.jpg', 'Vsevolod Rudyi', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Melanogrammus_aeglefinus_318932194.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'pollock'), 2, 'Harbor Pollock (juvenile)', 'life-stage', NULL, 'Fish under about two years old and 1-3 lbs that school tight around wharves, breakwaters, kelp beds, and rocky intertidal structure — the fish most shore anglers actually catch. Same field marks as adult pollock, just smaller and more likely encountered in a tight surface-feeding school at dusk.', 'Inshore wharves and breakwaters region-wide, especially in summer and fall; adults move offshore onto banks and ledges.', 'Same rules apply as adult pollock — zero retention in the Gulf Region, retainable within the aggregate groundfish limit in the Maritimes Region.', NULL, NULL, NULL, NULL);

-- ===== Rainbow Smelt (rainbow-smelt) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('rainbow-smelt', 'Rainbow Smelt', 'Osmerus mordax', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Small, silvery, iridescent baitfish-sized species that floods estuary shallows and rivers each spring to spawn, fished by hook-and-line, dip net, and spear across NB/NS/PEI — a classic family and community fishery, not a trophy target.', '/species/rainbow-smelt.jpg', 'Bex Goreham', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Osmerus_mordax_380012943.jpg', true, now())
