  summary = excluded.summary,
  image_path = excluded.image_path,
  image_credit = excluded.image_credit,
  image_license = excluded.image_license,
  image_source_url = excluded.image_source_url,
  is_published = true,
  updated_at = now();
delete from guide_sections where species_id = (select id from species where slug = 'rainbow-smelt');
delete from regulations where species_id = (select id from species where slug = 'rainbow-smelt');
delete from quick_reference where species_id = (select id from species where slug = 'rainbow-smelt');
delete from species_sources where species_id = (select id from species where slug = 'rainbow-smelt');
delete from species_variants where species_id = (select id from species where slug = 'rainbow-smelt');
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-smelt'), 0, 'Know the Fish', 'Rainbow smelt (*Osmerus mordax*) are slender, silvery fish with an olive-green back and iridescent purple, blue, and pink sides shot through with a bright silvery lateral stripe — the source of the name. Look for the small adipose fin (a tiny fleshy fin between the dorsal and tail) and noticeably strong canine teeth for such a small fish, both good ID markers. Adults typically run 10-25 cm, occasionally to 33 cm, and live 8-10 years, maturing by age 2-3.

Smelt can be either **anadromous** (sea-run) or landlocked in freshwater lakes; the sea-run form is what dominates the NB/NS/PEI shore and estuary fishery. In spring, adults migrate from coastal water up into small tributaries and river mouths to spawn at night over gravel bottom, arriving when water temperature is still cold (roughly 4-5°C). At spawning time, males develop small tubercles on their scales that feel like tiny buttons — a simple way to sex fish by hand.', '[{"label":"USGS NAS, Rainbow Smelt (Osmerus mordax) Species Profile","url":"https://nas.er.usgs.gov/queries/factsheet.aspx?SpeciesID=796"},{"label":"identifyfish.blogspot.com, Fish Identification: Rainbow Smelt","url":"http://identifyfish.blogspot.com/2010/09/rainbow-smelt-osmerus-mordax.html"},{"label":"NJDEP, Rainbow Smelt (Osmerus mordax) Historical Presence, Abundance, Life History","url":"https://dep.nj.gov/njfw/wp-content/uploads/njfw/Rainbow-Smelt.pdf"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-smelt'), 1, 'When to Go', 'The **spring spawning run** is the main event and the reason smelt fishing is a big deal across the region: fish stack up at river mouths and push into small coastal streams for a short, intense window, generally through April into June depending on location and water temperature (see the regulations table for exact dip-net date ranges by province, which double as a rough guide to run timing). Spawning happens at night, so evening and after-dark fishing during the run is classically the most productive. Outside the run, smelt remain present in estuary shallows and near structure through the season and can still be caught, just in smaller numbers and less predictably.', '[{"label":"NCBI, Environmental DNA detects Spawning Habitat of an ephemeral migrant fish (Anadromous Rainbow Smelt)","url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9594880/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-smelt'), 2, 'Where to Find Them', 'Smelt run in small coastal streams and river mouths right across all three provinces, making this one of the most locally accessible fisheries in the region.

- **NS:** The **Kennetcook, Meander, Herbert, St. Croix, and Avon Rivers** (Hants County) all have DFO-specified spring dip-net windows and are well-known smelt water; **Porters Lake** and the **Portapique River** are also popular, angler-reported spots, with fish typically showing by mid-May.
- **NB:** The Cocagne and Shediac River mouths on the Northumberland Strait side are proven local spots; smelt are present through the season near structure, with the spring run being the peak.
- **PEI:** The Boughton River mouth and other estuary systems island-wide hold smelt, again peaking during the spring run.

Within any of these, target the tide head of the main tributary (where salt water meets fresh) and any gravelly stretch just upstream of the estuary during the run.', '[{"label":"novascotiafishing.com, Smelts thread","url":"https://www.novascotiafishing.com/threads/smelts.4480/"},{"label":"DFO Maritimes Region, Tidal and freshwater (Diadromous) recreational regulations","url":"https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-smelt'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Light spinning rod, ultralight if you have one — small fish and small hooks call for light tackle. |
| Hooks/jig | Very small bucktail jigheads or a small streamer fly — smelt have tiny mouths, so undersized terminal tackle is essential. |
| Dip net | A legal, popular alternative to hook-and-line during the spring run in all three provinces (check size/mesh rules and season dates). |
| Extras | A bucket with some water/ice if keeping fish for the table — smelt are commonly kept and eaten fresh or smoked in this region. |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-smelt'), 4, 'Technique', '**Hook-and-line:**
1. Locate a school at a river mouth or estuary shallow, especially during the spring run.
2. Cast a tiny bucktail jighead or small streamer fly to the middle of the school.
3. Retrieve steadily back toward you — takes typically happen as the lure is leaving the school, not while sitting inside it, so keep the retrieve moving rather than stalling in place.
4. Because of their small, delicate mouths, use a gentle hookset — a hard hookset tears the hook right back out.

**Dip netting (where legal — see regulations):**
1. Work the tide head of a spawning tributary at night during the run, when fish concentrate most heavily.
2. Net in slack-water eddies along the current edge rather than fighting the main flow.
3. Respect posted weekly closures — many rivers in this region close to dip netting on specific days each week during the season to let some fish through to spawn.', '[{"label":"novascotiafishing.com, Smelts thread","url":"https://www.novascotiafishing.com/threads/smelts.4480/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-smelt'), 5, 'Handling & Table Notes', 'Smelt are widely kept and eaten across the region — a classic simple prep is whole, gutted, dredged in flour or cornmeal, and pan-fried crisp, small enough that the bones aren''t an issue. Ice or keep fish cool promptly if you plan to keep a mess of them, since a bucket of any small oily fish left in the sun spoils quickly. If releasing fish caught outside your bag limit, handle briefly and gently — smelt are a fragile, easily stressed species compared to hardier bottom fish like cunner or tomcod.', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-smelt'), 6, 'Conservation Notes', 'No broad at-risk status turned up for rainbow smelt in this region in current research, but this is a genuinely important forage species: smelt are key prey for striped bass, mackerel, and other predators covered elsewhere in this guide, and their runs are locally monitored closely enough that some rivers carry weekly closed days and gear restrictions specifically to protect spawning access. Respect posted closures and avoid overharvesting a spawning run in one sitting even where the daily limit is generous.', '[]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'rainbow-smelt'), 'NB', 'Tidal and inland', 'Inland angling: Apr 1–Sep 30 (when sport fish season open). Tidal angling: Aug 1–May 31. Dip nets (inland and tidal): Apr 1–May 31. Spears (tidal only): year-round.', '60/day (angling, dip netting, spearing); 200/day in boundary waters with Maine, Jan–Mar', 'None specified', 'No licence required in tidal water. Provincial angling licence required for inland angling.', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'rainbow-smelt'), 'NS', 'Tidal and inland', 'Inland angling: Apr 1–Sep 30 (when sport fish season open). Tidal angling: Aug 1–May 31. Dip nets: Apr 1–Jun 15 with additional weekly closures (e.g. Kennetcook, Meander, Herbert, St. Croix, Avon Rivers in Hants Co. closed Thu/Fri/Sat during that window; other areas closed Fri/Sat/Sun). Spears (tidal only): year-round.', '60/day (angling/spearing); 30/day by dip net; 24/day in Grand Lake (Jan–Sep)', 'None specified', 'No licence required in tidal water. Provincial angling licence required for inland angling. Jigging for smelt prohibited Apr 1–Jun 15 in specified NS rivers.', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'rainbow-smelt'), 'PEI', 'Tidal/saltwater', 'No closed season for hook-and-line recreational take in tidal water', 'No specific bag limit found in current DFO Gulf Region notices for PEI — fish conservatively', 'None specified', 'No provincial licence needed in tidal/salt water.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-smelt'), 0, 'Season', 'Spring spawning run (roughly April–June, varies by river); present year-round in estuaries');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-smelt'), 1, 'Best Time', 'Night, during the spring run');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-smelt'), 2, 'Gear', 'Ultralight rod + tiny jighead/streamer, or legal dip net during the run');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-smelt'), 3, 'Retrieve', 'Cast into school, steady retrieve back out — takes happen leaving the school');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-smelt'), 4, 'Table Fare', 'Popular local eating fish — whole, floured, pan-fried');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-smelt'), 5, 'Watch For', 'Weekly closed days on many spawning rivers — check before you go');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-smelt'), 'USGS NAS, Rainbow Smelt (Osmerus mordax) Species Profile', 'https://nas.er.usgs.gov/queries/factsheet.aspx?SpeciesID=796');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-smelt'), 'identifyfish.blogspot.com, Fish Identification: Rainbow Smelt', 'http://identifyfish.blogspot.com/2010/09/rainbow-smelt-osmerus-mordax.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-smelt'), 'NJDEP, Rainbow Smelt (Osmerus mordax) Historical Presence, Abundance, Life History', 'https://dep.nj.gov/njfw/wp-content/uploads/njfw/Rainbow-Smelt.pdf');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-smelt'), 'NCBI, Environmental DNA detects Spawning Habitat of an ephemeral migrant fish (Anadromous Rainbow Smelt)', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9594880/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-smelt'), 'novascotiafishing.com, Smelts thread', 'https://www.novascotiafishing.com/threads/smelts.4480/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-smelt'), 'DFO Maritimes Region, Tidal and freshwater (Diadromous) recreational regulations', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-smelt'), 'DFO — Recreational Groundfish Fishery, Southern Gulf of St. Lawrence', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'rainbow-smelt'), 0, 'Landlocked Smelt', 'form', NULL, 'Landlocked (freshwater-resident) smelt look essentially identical to the sea-run form — same iridescent silver-purple sides and adipose fin — but stay in a lake year-round rather than migrating from salt water. They tend to run smaller on average than sea-run fish reaching estuary size classes.', 'Landlocked populations exist in some cold, deep freshwater lakes in the region as a resident forage/panfish, separate from the tidal river and estuary run that drives most of the NB/NS/PEI smelt fishery covered in this guide.', 'The dip-net and hook-and-line rules in this guide apply to the tidal/anadromous fishery — a landlocked lake population may fall under different inland/provincial angling rules rather than the DFO diadromous framework.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'rainbow-smelt'), 1, 'Juvenile Herring', 'lookalike', 'Clupea harengus', 'Young herring school alongside smelt in estuaries and can be mistaken for them at a glance, but herring lack a smelt''s adipose fin (the small fleshy fin between the dorsal and tail) entirely, and lack a smelt''s strong canine teeth. Herring also have a deeper, more compressed body and a distinct row of scutes (bony plates) along the belly that smelt do not have.', 'Both species use the same estuary shallows and river mouths across NB, NS, and PEI, especially where baitfish schools concentrate near river mouths.', 'No specific bag-limit conflict identified between the two in this guide''s research, but confirming the adipose fin is a quick, reliable way to know you''re looking at smelt before counting them against a smelt-specific bag limit.', '/species/rainbow-smelt--variant-1.jpg', 'Olivier Dugornay', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Juv%C3%A9niles_de_hareng_(Clupea_harengus)_%C3%A0_70_jours_post-%C3%A9closion_(Ifremer_00614-72593_-_28700).jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'rainbow-smelt'), 2, 'Silversides', 'lookalike', 'Menidia menidia', 'Atlantic silversides are a similar small, slender, silvery baitfish often lumped in with "smelt" colloquially, but they aren''t related. Silversides lack a lateral line (a visible line of sensing pores down the flank that smelt have), have small, weak teeth compared to a true smelt''s noticeably strong canines, and their small spiny first dorsal fin sits well separated from the soft second dorsal, with pelvic fins set further back than in a smelt.', 'Silversides school in the same shallow estuary and beach habitat used by rainbow smelt across the region, particularly in warmer months.', 'Worth knowing the difference mainly for accurate identification rather than any specific rule conflict — silversides are not the regulated species covered by this guide''s smelt dip-net and bag-limit rules.', '/species/rainbow-smelt--variant-2.jpg', 'Smithsonian Environmental Research Center', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Menidia_menidia_RR_08-11-19_0545_(48555459552).jpg');

-- ===== Rainbow Trout (rainbow-trout) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('rainbow-trout', 'Rainbow Trout', 'Oncorhynchus mykiss', 'freshwater', '{"NB","NS","PEI"}'::text[], 'Introduced, hard-fighting trout stocked and naturalized across all three Maritime provinces, with PEI''s river-run ''sea-run'' rainbows drawing the most dedicated following — best fished with light spinning gear or fly tackle in rivers, streams, and stocked lakes from spring through the fall extended season.', '/species/rainbow-trout.jpg', 'USFWS Mountain Prairie', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Rainbow_Trout_(Oncorhynchus_mykiss)_Gavins_Point.jpg', true, now())
