insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-trout'), 0, 'Know the Fish', 'Rainbow trout (*Oncorhynchus mykiss*) are native to the Pacific coast of North America and were introduced to Atlantic Canada for sport fishing; they are not native to NB, NS, or PEI but are now established through stocking and, in some river systems, naturalized wild populations.

Identify them by an olive-green to blue-green back, a pink-to-reddish lateral band running the length of the body (most pronounced on river fish), small evenly-distributed black spots on the body and tail, and a lack of teeth on the tongue (a difference from brown trout). Rainbows are aggressive, acrobatic fighters — a big part of their popularity with anglers who also fish brook and brown trout in the same waters.

In PEI specifically, some river systems support a naturalized, sea-run-like population that moves between river and estuary, giving anglers a bigger, harder-pulling fish than a typical stocked-lake rainbow.', '[{"label":"Cast & Fly — Rainbow vs Brown Trout: ID, Habits & Fly Fishing Tips","url":"https://castandfly.com/rainbow-vs-brown-trout/"},{"label":"Fishing Skillz — Trout Identification Guide","url":"https://www.fishingskillz.com/identify-different-trout-species/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-trout'), 1, 'Where to Find Them', '- **Saint John River system (NB)** — a broad, well-known fishery holding rainbow trout alongside brown trout, bass, and other species.
- **Bras d''Or Lakes and tributaries (Cape Breton, NS)** — a popular recreational rainbow fishery, with rivers flowing into the Bras d''Or supporting both stocked fish and spawning escapees.
- **Albro Lake, Halifax (NS)** — HRM''s most popular urban stocked fishery, regularly stocked with rainbow and brook trout.
- **Morell, Valleyfield, West, Naufrage, and Trout Rivers (PEI)** — home to PEI''s signature rainbow trout and brook trout river fisheries.
- Nova Scotia stocks roughly 200 lakes each spring and another 200 in the fall province-wide with rainbow and brook trout — check the current Anglers'' Handbook stocked-lakes list for a water near you.', '[{"label":"Angler''s Atlas — St. John River","url":"https://www.anglersatlas.com/place/724844/st-john-river"},{"label":"Canada Fishing Licence — Nova Scotia Stocked Lakes Guide 2026","url":"https://canadafishinglicence.com/guides/nova-scotia-stocked-lakes-trout-guide/"},{"label":"Tourism PEI — River Fishing","url":"https://www.tourismpei.com/askanislander/questions/river-fishing"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-trout'), 2, 'When to Go', '### New Brunswick
Most Regional Fishery Areas (RFAs) open rivers/streams **May 1 – September 15** and lakes **May 15 – September 15** for trout, though exact dates vary by RFA — check the current NB Fish Regulations Summary for your specific water.

### Nova Scotia
General inland trout season runs **April 1 – September 30**, with natural bait prohibited province-wide in September (artificial fly/unbaited lure only that month). NS also runs a dedicated Winter Sportfishing Weekend program on select stocked lakes.

### PEI
Regular rainbow trout season runs roughly **May 15 – November 15** on scheduled river systems, and PEI adds an **extended season (Sept 16 – Dec 31 in most locations, to Nov 30 on some ponds)** where only single barbless fly or barbless lure (no bait) is permitted.', '[{"label":"Canada Fishing Licence — Nova Scotia Fishing Regulations 2026","url":"https://canadafishinglicence.com/guides/nova-scotia-fishing-season-regulations-2026/"},{"label":"Government of Prince Edward Island — Extended Angling Season","url":"https://www.princeedwardisland.ca/en/information/environment-energy-and-climate-action/2024-extended-angling-season"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-trout'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Fly rod | 5-6 wt, 9 ft, floating line for rivers and stocked lakes alike. |
| Spinning rod | Light 6-7 ft spinning rod, 4-8 lb line — rainbows fight hard for their size and a soft tip protects light line/tippet. |
| Flies | Nymphs (Hare''s Ear, Pheasant Tail) fished under an indicator for river fish; small streamers for aggressive, actively-feeding fish. |
| Lures | Small inline spinners (1/16-1/8 oz) and small spoons — flash and vibration are the trigger. |
| Extras | Barbless single hook/fly during PEI''s extended season (legally required); small landing net for handling fish quickly. |', '[{"label":"KastKing — How to Find the Difference Between Trout Species","url":"https://kastking.com/blogs/how-to/how-to-find-the-difference-between-trout-species"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-trout'), 4, 'Technique', '**Fly fishing** excels in clear water and shallow streams where you can read specific lies or rising fish. Dead-drift a nymph through likely current seams and pocket water; switch to a small streamer stripped with short pulls when fish are actively chasing baitfish.

**Spin fishing** covers more water faster and handles murky or windy conditions better than fly gear. Cast a small inline spinner or spoon across and slightly upstream of a run, retrieving just fast enough to keep the blade turning — rainbows in moving water tend to hit hardest on a retrieve that swings naturally through a seam rather than one stripped straight back.

Rainbows confined to a single lake their whole life are generally less selective feeders than river fish that need to keep growing toward reproduction — lake stockers will often hit a lure or fly more readily than a wary river fish.', '[{"label":"Field & Stream — Spin Fishing for Trout: A Complete Guide","url":"https://fieldandstream.com/stories/fishing/freshwater-fishing/trout-fishing/spin-fishing-for-trout"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-trout'), 5, 'Handling & Release', '- Wet your hands before handling any trout you plan to release — dry hands strip the protective slime coat and increase infection risk.
- Keep fish in the water as much as possible; if photographing, support horizontally and keep the time out of water under 10 seconds.
- Use barbless hooks where required (mandatory during PEI''s extended season) to speed release regardless of local rule — it reduces handling injury on any water.
- If you''re keeping fish within the legal limit for the table, dispatch and bleed promptly rather than stringing live fish for an extended period.', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'rainbow-trout'), 6, 'Conservation & Consumption Notes', 'Rainbow trout are an introduced species in the Maritimes, sustained largely through provincial stocking programs (NS alone stocks roughly 400 lakes annually across spring and fall). Because they''re not native, there''s generally no conservation concern about harvesting them within posted limits — in fact stocked-lake fisheries are specifically managed to be harvested. No regional mercury/consumption advisory specific to rainbow trout turned up in current provincial notices; as with any freshwater fish, check your province''s general fish consumption advisory list if fishing a specific lake or industrial-adjacent watershed.', '[{"label":"Canada Fishing Licence — Nova Scotia Stocked Lakes Guide 2026","url":"https://canadafishinglicence.com/guides/nova-scotia-stocked-lakes-trout-guide/"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'rainbow-trout'), 'NB', 'Freshwater rivers, streams, lakes', 'Most RFAs: rivers/streams May 1–Sep 15; lakes May 15–Sep 15 (varies by RFA)', '5 fish combined daily limit across trout species (rainbow/brown/brook combined), varies by RFA', 'Minimum 15 cm total length', 'Regular angling licence covers rainbow trout (no separate salmon licence needed). Some RFAs impose stricter local limits — confirm against the current NB Fish Regulations Summary for your specific water.', 'https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'rainbow-trout'), 'NS', 'Freshwater rivers, streams, lakes', 'Apr 1–Sep 30 inland; Sep 1–30 fly/unbaited-lure only province-wide', 'Combined limit of 5 fish/day across rainbow, brown, and brook trout; some Special Management Areas impose stricter local limits', 'Generally no minimum size outside Special Management Areas (some SMAs require one fish over 35 cm)', 'General Fishing Licence required. Natural bait prohibited every September province-wide. Bras d''Or Lakes area open all year with a reduced 2-fish limit Oct-Mar in some sections.', 'https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'rainbow-trout'), 'PEI', 'Freshwater rivers, streams, ponds', 'Regular season ~May 15–Nov 15; extended season ~Sep 16–Dec 31 (to Nov 30 on some ponds), single barbless fly/lure only', '3 rainbow trout per day', 'Only 1 of the 3 daily fish may be greater than 40 cm', 'Extended season restricted to single barbless fly or barbless lure, no bait. Regular PEI angling licence required (~$10 resident plus mandatory Wildlife Conservation Fund contribution).', 'https://www.princeedwardisland.ca/en/information/environment-energy-and-climate-action/2024-extended-angling-season', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-trout'), 0, 'Season', 'Spring through fall, varies by province; PEI has a fall extended fly/lure-only season');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-trout'), 1, 'NB Bag Limit', '5 combined trout species/day');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-trout'), 2, 'NS Bag Limit', '5 combined trout species/day; Sept fly/lure only');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-trout'), 3, 'PEI Bag Limit', '3/day, only 1 over 40 cm');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-trout'), 4, 'Best Gear', 'Light spinning rod with small inline spinners, or 5-6 wt fly rod with nymphs/streamers');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'rainbow-trout'), 5, 'Top Waters', 'Saint John River (NB), Bras d''Or Lakes (NS), Morell & West Rivers (PEI)');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-trout'), 'New Brunswick Fish Regulations Summary 2026-27', 'https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-trout'), 'Nova Scotia Anglers'' Handbook and 2026 Summary of Regulations', 'https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-trout'), 'Government of Prince Edward Island — Extended Angling Season', 'https://www.princeedwardisland.ca/en/information/environment-energy-and-climate-action/2024-extended-angling-season');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-trout'), 'Cast & Fly — Rainbow vs Brown Trout: ID, Habits & Fly Fishing Tips', 'https://castandfly.com/rainbow-vs-brown-trout/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-trout'), 'Canada Fishing Licence — Nova Scotia Stocked Lakes Guide 2026', 'https://canadafishinglicence.com/guides/nova-scotia-stocked-lakes-trout-guide/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'rainbow-trout'), 'Angler''s Atlas — St. John River', 'https://www.anglersatlas.com/place/724844/st-john-river');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'rainbow-trout'), 0, 'Sea-Run Rainbow Trout ("Steelhead")', 'form', NULL, 'The same species as resident rainbow trout, genetically, but grown much larger on rich ocean feeding. Fresh-run fish are more streamlined with a dark-olive back and silvery-white sides, a pink-to-red stripe still visible along the flank, and noticeably larger size than a lake or river resident from the same system. There is no reliable visual field mark to prove a fish went to sea — that''s only confirmed by scale reading or otolith analysis.', 'PEI''s east and south shore river systems, including the Morell, Valleyfield, and Trout Rivers, which support naturalized river-run populations moving between fresh and estuary water.', 'Best targeted in fall (September-November) as fish run up PEI rivers. Falls under the same rainbow trout licence and limits as any other rainbow — there is no separate steelhead category or regulation in this region.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'rainbow-trout'), 1, 'Resident/Stocked Rainbow Trout', 'form', NULL, 'Spends its whole life in a lake, pond, or river without going to sea. Generally smaller than a sea-run fish from the same watershed, with the same olive-green back, pink lateral band, and evenly spread small black spots, but less streamlined and without the silvery ocean sheen of a fresh-run fish.', 'Stocked lakes across all three provinces (e.g. Albro Lake, NS; roughly 200 NS lakes stocked each spring and fall) and river systems like the Saint John (NB) and Bras d''Or tributaries (NS).', 'Lake-confined stockers tend to be less selective feeders than river fish, since they don''t need to keep growing toward a spawning migration.', NULL, NULL, NULL, NULL);

-- ===== Sculpin (Grubby / Longhorn Sculpin) (sculpin) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('sculpin', 'Sculpin (Grubby / Longhorn Sculpin)', 'Myoxocephalus spp. / Acanthocottus spp.', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Spiny, big-headed, structure-loving bottom fish caught as a bonus around wharves and flounder grounds across NB/NS/PEI — several similar species covered under one common name, none of them a dedicated target but all good fun on light bait gear.', NULL, NULL, NULL, NULL, true, now())
