insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'sculpin'), 4, 'Role', 'Bonus/incidental catch, not a dedicated target species');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'sculpin'), 5, 'ID Tip', 'Longhorn sculpin has long cheek spines; grubby''s are short');
