insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'sculpin'), 0, 'Grubby', 'related-species', 'Myoxocephalus aenaeus', 'The smallest and shortest-spined of the region''s common sculpins — cheek (preopercular) spines are noticeably short compared to longhorn sculpin''s long, gill-cover-spanning spine, and grubby has only 10-11 anal fin rays with no pore behind the last gill arch (shorthorn has 13-14 rays and that pore).', 'Same wharf, estuary, and flounder-ground bottom as the other sculpins region-wide, including Cocagne Cove, NB.', 'Least likely of the group to cause a painful spine wound given its short spines, but still worth a rag or glove when unhooking.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'sculpin'), 1, 'Longhorn Sculpin', 'related-species', 'Myoxocephalus octodecemspinosus', 'Identified by its long preopercular (cheek) spine, roughly four times the length of the spine below it and long enough to extend past the gill cover — the clearest single field mark separating it from grubby and shorthorn sculpin. Its first dorsal fin also stands taller than the second, and its lateral line shows smooth cartilaginous plates rather than the prickly scales found on shorthorn sculpin.', 'Bay of Fundy and St. Mary''s Bay, NS specifically, plus offshore on Banquereau and Sable Island Banks; also common inshore region-wide as flounder-ground bycatch.', 'Longhorn sculpin spines can inflict a genuinely painful puncture wound, with venom in the spine groove causing swelling, redness, and throbbing pain some anglers compare to a bee or wasp sting. Handle with a rag or glove, keep fingers clear of the head and gill-cover spines when unhooking, and immerse a puncture wound in hot water if stung.', '/species/sculpin--variant-1.jpg', 'Luis Miguel Bugallo Sánchez (Lmbuga)', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:2018._Myoxocephalus_octodecemspinosus_(Mitchil_1814)._Museo_do_Mar_de_Galicia.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'sculpin'), 2, 'Shorthorn Sculpin', 'related-species', 'Myoxocephalus scorpius', 'Cheek spines are short and blunt-triangular, with the uppermost less than twice the length of the one below it (versus longhorn''s uppermost spine at roughly 4x). Shorthorn has 13-14 anal fin rays and a small pore on each side of the throat behind the last gill arch, both absent on grubby, and prickly (not smooth) scales along the lateral line versus longhorn''s smooth cartilaginous plates.', 'Same rocky, ledge, and estuary bottom as the other sculpins region-wide; tends toward colder, more northerly water within the group''s range.', 'Spines are less prominent than longhorn''s but still capable of a painful jab — same rag/glove handling applies.', '/species/sculpin--variant-2.jpg', 'TinoStrauss', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Myoxocephalus_scorpius_01.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'sculpin'), 3, 'Sea Raven', 'related-species', 'Hemitripterus americanus', 'Unmistakable once you know what to look for: sea raven has fleshy, branched skin tabs along the lower jaw, snout, and head, a ragged, torn-looking first dorsal fin outline unlike any true sculpin''s, prickly spine-covered skin, and a stouter, heavier body than grubby, longhorn, or shorthorn sculpin.', 'Same wharf and bottom structure as the other sculpins region-wide.', 'Not a true sculpin (a related but separate family, Hemitripteridae) — often lumped in with "sculpin" bycatch by anglers regardless. Handle carefully; the spiny skin and dorsal fin can still scrape or prick bare hands even without the venom concern longhorn sculpin poses.', '/species/sculpin--variant-3.jpg', 'Norbert Verneau', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Hemitripterus_americanus.jpg');

-- ===== Smallmouth Bass (smallmouth-bass) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('smallmouth-bass', 'Smallmouth Bass', 'Micropterus dolomieu', 'freshwater', '{"NB","NS","PEI"}'::text[], 'A hard-fighting, introduced river and lake gamefish, mostly a catch-and-release fishery across the region — the Saint John River system in NB is the region''s premier smallmouth water.', '/species/smallmouth-bass.jpg', 'Timothy Knepp, U.S. Fish and Wildlife Service', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Micropterus_dolomieu2.jpg', true, now())
