insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'smallmouth-bass'), 0, 'Know the Fish', 'Smallmouth bass are not native to the Maritimes — they were introduced into the St. Croix River system and nearby lakes, then spread through the Saint John River watershed and beyond, including waterways feeding the Petitcodiac. They''ve since been introduced to parts of Nova Scotia and are more locally present in PEI. They spawn in May and June: the male clears and guards a nest about a metre wide, and continues guarding the young after they hatch, sometimes returning to the same nest site year after year. They feed on insects, frogs, and small fish, and slow down and eat less as winter approaches — which is also why fall fish feed aggressively beforehand.

They''re known as hard-fighting, aggressive fish on light tackle, and Maritime anglers generally practice more catch-and-release than harvest with this species — by reputation, most Maritimers haven''t developed a strong taste for eating them, which keeps regulators comfortable setting long seasons in most zones.', '[{"label":"GNB, Smallmouth Bass species fact sheet","url":"https://www2.gnb.ca/"},{"label":"Outdoor Canada, 10 East Coast hot spots with spectacular smallmouth bass fishing","url":"https://www.outdoorcanada.ca/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'smallmouth-bass'), 1, 'Where to Find Them', 'The **Saint John River system and its many lakes** remain the region''s premier smallmouth fishery. Closer to Moncton, the Petitcodiac watershed gives a legitimate closer option:

- **Little River**, near Salisbury — cross the river on the Salisbury Road heading out of Riverview; multiple pull-off spots to walk the river.
- **Pollett River / North River confluence** with the Petitcodiac, near Salisbury.
- **Anagance River** — a Petitcodiac tributary further out toward Petitcodiac village.
- Rivers and brooks along Mollins Road and Salisbury Back Road.

In Nova Scotia, smallmouth are established in a number of lake systems (check the current NS Anglers'' Handbook for open waters); in PEI, smallmouth populations are more limited and localized.', '[{"label":"newbrunswickfishing.com forum threads (Fishing around Moncton)","url":"https://www.newbrunswickfishing.com/"},{"label":"Wikipedia, Petitcodiac River","url":"https://en.wikipedia.org/wiki/Petitcodiac_River"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'smallmouth-bass'), 2, 'When to Go', '- **Pre-spawn** (late April into May): bass move from deeper water into rivers and shallow staging areas ahead of the May-June spawn — aggressive and catchable on moderate tackle.
- **Spawn** (May-June): males guard nests in shallow water; sight-fishing to bedding fish is possible but consider the impact of pressuring guarding males on nest success.
- **Summer**: classic topwater and structure fishing once fish settle into summer patterns.
- **Fall**: bass feed heavily ahead of winter — a reliably aggressive window before most seasons close in mid-September.', '[{"label":"Outdoor Canada, 10 East Coast hot spots","url":"https://www.outdoorcanada.ca/"},{"label":"Fish''n Canada, Shore Fishing in New Brunswick","url":"https://fishncanada.com/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'smallmouth-bass'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Medium-action spinning rod — matches what local anglers commonly recommend for river smallmouth. |
| Line | 10 lb test is a commonly cited standard for aggressive river smallmouth on moving water. |
| Terminal tackle | In-line spinners, small crankbaits, soft plastic tubes, topwater poppers/walkers — carry a mix and let the fish tell you what they want that day. |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'smallmouth-bass'), 4, 'Lures & Retrieves', '- **In-line spinner** (e.g. green-and-chartreuse blade) — cast up-and-across current and retrieve steadily back with the flow; a proven producer on pre-spawn river fish moving up from deeper holding water.
- **Topwater popper or walking bait** — best early morning and evening; work with a walk-the-dog side-to-side action or a chugging pop-pause-pop retrieve over calm pools and current edges.
- **Crankbait** — steady retrieve, letting the bill bounce off submerged rock and structure; a good searching bait to cover water and find where fish are holding.
- **Soft plastic tube jig** — hop it along bottom with a lift-and-drop retrieve, imitating a crayfish — a staple smallmouth bait wherever they''re found.
- **Soft plastic craw/creature bait** on a jighead — slow drag or hop along bottom, especially around rock and current breaks.

Read the water the same way anywhere smallmouth are found: current seams, rock structure, drop-offs at the edge of pools, and any current break where a fish can hold with minimal effort while ambushing food drifting past.', '[{"label":"Fish''n Canada, Shore Fishing in New Brunswick","url":"https://fishncanada.com/"},{"label":"Outdoor Canada, 10 East Coast hot spots","url":"https://www.outdoorcanada.ca/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'smallmouth-bass'), 5, 'Handling & Release', 'Smallmouth bass are aggressive fighters and will thrash hard boatside or streamside — use tackle heavy enough to land them reasonably quickly, and a rubber-meshed net if netting fish, which is gentler on their protective slime coat than knotted nylon. Keep handling brief, keep the fish wet as much as possible, and support it horizontally rather than lifting by the jaw alone on larger fish.', '[{"label":"Nova Scotia Anglers'' Handbook, general handling guidance","url":"https://novascotia.ca/fish/programs-and-services/recreational-fishing/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'smallmouth-bass'), 6, 'Conservation & Consumption Notes', 'Smallmouth bass is on New Brunswick''s mercury consumption advisory list: any size, the guideline is 2 servings per month for the general population over 12, and sensitive populations (pregnant/breastfeeding women, infants, children under 12) should avoid eating them.

**Invasive-species note**: as of April 1, 2026, smallmouth bass became a mandatory-retention invasive species in the Restigouche, Chaleur, Miramichi, and Southeast Fishery Areas of New Brunswick (any caught there must be kept, not released) — this does NOT apply province-wide, so check which Recreational Fishery Area (RFA) you''re fishing before deciding whether to release a fish.', '[{"label":"GNB Fish Consumption Guidelines (mercury)","url":"https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf"},{"label":"GNB Fish 2026-27 Regulations Summary","url":"https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'smallmouth-bass'), 'NB', 'Rivers, brooks, streams', 'Apr 15 - Sept 15', '5', 'Min 10 cm, Max 60 cm', 'Mandatory retention (invasive species rule) in Restigouche, Chaleur, Miramichi, and Southeast RFAs as of Apr 1 2026 — normal catch-and-release applies elsewhere, e.g. Inner Bay of Fundy RFA. NB angling licence required ($23 CAD resident season, Class 9).', 'https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'smallmouth-bass'), 'NB', 'Lakes, ponds, reservoirs', 'May 1 - Sept 15', '5', 'Min 10 cm, Max 60 cm', 'Same RFA-specific mandatory retention rule applies where relevant.', 'https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'smallmouth-bass'), 'NS', 'Inland waters (general)', 'Per current NS Anglers'' Handbook — varies by district', 'Per NS Anglers'' Handbook', 'Per NS Anglers'' Handbook', 'NS angling licence required. Check current handbook for districts where smallmouth are established/legal to target.', 'https://novascotia.ca/fish/programs-and-services/recreational-fishing/', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'smallmouth-bass'), 'PEI', 'Inland waters (limited distribution)', 'Per PEI Anglers'' Guide', 'Per PEI Anglers'' Guide', 'Per PEI Anglers'' Guide', 'Smallmouth bass populations are more localized in PEI than NB/NS — confirm current status/access with PEI Fish & Wildlife before planning a trip specifically for this species.', 'https://www.princeedwardisland.ca/en/topic/fishing-hunting-trapping-licences', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'smallmouth-bass'), 0, 'Season (NB rivers)', 'Apr 15 - Sept 15');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'smallmouth-bass'), 1, 'Best Time', 'Fall feeding window and early morning/evening topwater');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'smallmouth-bass'), 2, 'Best Method', 'In-line spinner, topwater popper, or tube jig on structure');
