insert into species_sources (species_id, label, url) values ((select id from species where slug = 'smallmouth-bass'), 'Nova Scotia Recreational Fishing', 'https://novascotia.ca/fish/programs-and-services/recreational-fishing/');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'smallmouth-bass'), 0, 'Largemouth Bass', 'lookalike', 'Micropterus salmoides', 'On a smallmouth, the corner of the upper jaw lines up roughly even with the eye; on a largemouth, the jaw hinge extends back well past the eye. Smallmouth have a spiny and soft dorsal fin joined by only a shallow notch, appearing almost as one continuous fin, while a largemouth''s dorsal fin has a deep notch that can look like two separate fins. Colour also differs: smallmouth are brown to bronze with faint vertical bars running gill-to-tail, while largemouth are greener with a single bold horizontal stripe running eye-to-tail rather than vertical bars.', 'Both species now occur in the Saint John River system (NB); largemouth are confirmed only in NB (Grand Lake, Washademoak Lake, Oromocto Lake, Mactaquac Arm, Meduxnekeag River, Spednic Lake) with no established NS or PEI population, while smallmouth are more widespread across all three provinces.', 'This distinction has real legal weight under NB''s April 2026 invasive-species rules: mandatory-retention Recreational Fishery Areas differ by species (smallmouth: Restigouche, Chaleur, Miramichi, Southeast; largemouth: Restigouche, Chaleur, Miramichi, Southeast, Inner Bay of Fundy, and Upper Saint John). Misidentifying one bass as the other in a mandatory-retention RFA — or releasing either species where retention is required — can draw a $100-$500 fine.', '/species/smallmouth-bass--variant-0.jpg', 'USFWS Mountain Prairie', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Largemouth_Bass_(Micropterus_salmoides)_June_2023.jpg');

-- ===== Spiny Dogfish (spiny-dogfish) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('spiny-dogfish', 'Spiny Dogfish', 'Squalus acanthias', 'saltwater', '{"NB","NS","PEI"}'::text[], 'A small, slow-growing shark caught mostly by accident while bottom fishing for cod, pollock, and flounder from wharves and boats around the Maritimes; regulated as a groundfish, not under the shark licence system, and handled with care for the mildly venomous spine in front of each dorsal fin.', '/species/spiny-dogfish.jpg', 'Doug Costa, NOAA/SBNMS', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Squalus_acanthias_stellwagen.jpg', true, now())
