insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'spiny-dogfish'), 0, 'Know the Fish', 'Spiny dogfish (*Squalus acanthias*) are small, slender sharks, gray to brownish-gray on top with a pale belly, most commonly 60–105 cm in the Maritimes though some reach over a metre. They''re easy to identify by two features: no anal fin, and a sharp spine set just forward of each of the two dorsal fins.

They''re long-lived and slow to mature — DFO records lifespans of 30-40 years in Atlantic Canada, with some Pacific dogfish aged past 70. Males mature around age 10 (about 64 cm); females don''t mature until roughly age 16 (about 82 cm). That slow life history is the reason this species is so easily overfished and so slow to recover.

Dogfish are opportunistic feeders, taking small schooling fish like capelin and herring along with squid, krill, and jellyfish. In Atlantic Canada, semi-resident groups hold off southern Newfoundland, through the Gulf of St. Lawrence, and on the Scotian Shelf, with seasonal inshore-offshore movement; a portion of the southwest Nova Scotia group migrates into U.S. waters annually.', '[{"label":"DFO — Species Profile, Spiny Dogfish","url":"https://www.dfo-mpo.gc.ca/species-especes/profiles-profils/spiny-dogfish-aiguillat-commun-atl-eng.html"},{"label":"Oceana Canada — Spiny Dogfish","url":"https://oceana.ca/en/marine-life/spiny-dogfish/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'spiny-dogfish'), 1, 'Reproduction & Why They School', 'Spiny dogfish are ovoviviparous — pups develop inside the female in egg capsules, nourished by a yolk sac, and are born live rather than hatched externally. Their gestation runs roughly 18-24 months, commonly cited as the longest of any vertebrate on record, well beyond an elephant''s. Litters are small, typically 4-7 pups born at 20-33 cm, with pregnant females moving into shallower coastal water in winter (including Nova Scotia waters) to give birth.

That combination — late maturity, tiny litters, two-year pregnancies — gives the species one of the lowest population growth rates of any fish. It''s also why dogfish are seen in such dense, uniform schools: they segregate tightly by size and sex, so a school hitting your bait is often all one size class.

This life history is the core reason dogfish populations can look locally abundant (booming catch numbers some years) while still being vulnerable to sustained fishing pressure — they simply can''t rebuild quickly once numbers drop.', '[{"label":"DFO — Species Profile, Spiny Dogfish","url":"https://www.dfo-mpo.gc.ca/species-especes/profiles-profils/spiny-dogfish-aiguillat-commun-atl-eng.html"},{"label":"American Oceans — Spiny Dogfish","url":"https://www.americanoceans.org/species/spiny-dogfish/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'spiny-dogfish'), 2, 'Where to Find Them', 'Dogfish show up almost anywhere bottom fishing happens in tidal water in the Maritimes — they''re one of the most frequently reported incidental catches by anglers targeting cod, pollock, mackerel, or flounder from shore and wharves, not usually a species anglers deliberately target here.

**Regionally documented areas:**
- **Bay of Fundy** (Digby Harbour Wharf, Saint John Harbour area) — long-standing dogfish grounds; Bay of Fundy small-boat fishermen have targeted dogfish commercially for decades as groundfish stocks declined elsewhere.
- **Southwest Scotian Shelf** — the core Canadian aggregation area for the species, per DFO.
- **Halifax Harbour / Bedford Basin** — local anglers on the Nova Scotia Fishing Forum report dogfish turning up while fishing these areas from shore.
- **Gulf of St. Lawrence / Northumberland Strait (NB and PEI shores)** — DFO lists the Gulf as one of the species'' semi-resident aggregation zones, and PEI anglers report them as incidental bycatch while fishing for striped bass and other species from shore.

Expect them most in the warmer months when they push inshore to feed, and understand that where cod, pollock, or mackerel are biting from a wharf, dogfish are a realistic bycatch any day the school is moving through.', '[{"label":"CBC News — Spiny dogfish shark boom, bane for Nova Scotia fishermen","url":"https://www.cbc.ca/news/canada/nova-scotia/spiny-dogfish-shark-boom-bane-for-nova-scotia-fishermen-1.2686688"},{"label":"Britannica — Digby, Bay of Fundy","url":"https://www.britannica.com/place/Digby"},{"label":"DFO — Species Profile, Spiny Dogfish","url":"https://www.dfo-mpo.gc.ca/species-especes/profiles-profils/spiny-dogfish-aiguillat-commun-atl-eng.html"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'spiny-dogfish'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Medium-heavy spinning or conventional bottom rod — same setup used for cod/pollock/flounder handles dogfish fine. |
| Line/Leader | 20-30 lb main line with a wire or heavy-mono leader (30-50 lb+) — dogfish have small but sharp teeth and will bite through light leader material. |
| Terminal tackle | Standard bottom rig or jig used for groundfish — bait (clam, herring, mackerel strip) or metal jigs both take dogfish readily. |
| Extras | Long-nose pliers or a dedicated dehooking tool, thick gloves, and a rag — essential given the spines and their habit of swallowing hooks deep (see Handling & Safety). |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'spiny-dogfish'), 4, 'Handling & Safety', 'This is the section to read before you catch your first one. Spiny dogfish carry a hard, sharp spine set just ahead of each dorsal fin. Small venom glands run along these spines, and a hooked or landed dogfish will arch its body and thrash the tail specifically to drive a spine into whatever''s holding it — hand, forearm, or thigh. The wound is genuinely painful and often takes time to heal; anglers who''ve been stuck describe swelling and lingering soreness for days.

### Safe handling
1. **Keep the fish in the water if possible.** Use a de-hooking tool to remove the hook without lifting the fish out — this avoids direct contact entirely and the fish is less likely to whip its tail while still partly submerged.
2. **If you must land it**, pin the fish down firmly — a boot placed just behind (or ahead of) the second dorsal spine works — then grip it firmly by the head/gill area from behind, ahead of the first spine, keeping fingers clear of both spines at all times.
3. **Wear thick gloves** regardless of method — spines can still catch you through casual contact.
4. **Never grab a dogfish by the tail and let the body hang free** — this is exactly when the tail-whip reflex drives the second dorsal spine into a hand or arm.

### Hook removal
Dogfish frequently swallow bait and hook deep, especially on bait rigs meant for cod or flounder. A long-handled hook remover or de-hooking tool is strongly recommended over needle-nose pliers alone — it reaches deep hook sets without putting fingers near the mouth, and lets you release the fish with the hook out (or cut the leader and leave a deeply set hook, which the fish can survive) rather than forcing extended handling to dig a hook out by hand.

If stuck by a spine: clean the wound thoroughly, expect pain and swelling out of proportion to the size of the puncture, and seek medical attention for signs of infection or a severe reaction.', '[{"label":"PubMed — Envenoming in a fisherman, taxonomic and toxinologic comments on the Squalus genus","url":"https://pubmed.ncbi.nlm.nih.gov/15922385/"},{"label":"The Fishing Website (NZ) — Handling Hazardous Fish","url":"https://www.fishing.net.nz/fishing-advice/how-to/handling-hazardous-fish/"},{"label":"BC Fishing Journal — Pier Fishing for Dogfish Sharks","url":"https://www.bcfishingjournal.com/journals/pier-fishing-for-dogfish-sharks/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'spiny-dogfish'), 5, 'Conservation Status', 'Spiny dogfish is a genuine conservation-sensitive species despite sometimes looking locally abundant. In 2010, COSEWIC (Committee on the Status of Endangered Wildlife in Canada) assessed the Atlantic population as **Special Concern**, citing low fecundity, long generation time, uncertainty in trends of mature-fish abundance, and demonstrated vulnerability to overfishing elsewhere. Globally, the IUCN lists the species as Vulnerable, and the Northeast Atlantic (European) population specifically as Critically Endangered after decades of heavy fishing pressure there — a cautionary example of how fast this slow-reproducing species can be drawn down.

The Northwest Atlantic stock that reaches Canadian waters is shared with the U.S., which does the primary stock assessment work; recent assessments describe the stock as not currently overfished with overfishing not occurring, though mature female biomass has declined since 2012, prompting recommendations to manage more cautiously going forward. Canadian catch is mostly incidental bycatch in groundfish fisheries plus a directed but comparatively small commercial fishery (liver oil historically, more recently export markets), concentrated in the Bay of Fundy and southwest Scotian Shelf.

Given the slow growth and two-year gestation, released fish represent real future spawning potential — handle promptly and return dogfish you''re not keeping to the water without unnecessary delay.', '[{"label":"Oceana Canada — Spiny Dogfish","url":"https://oceana.ca/en/marine-life/spiny-dogfish/"},{"label":"Canada Commons — Assessment of Spiny Dogfish in the Northwest Atlantic","url":"https://canadacommons.ca/artifacts/34679876/assessment-of-spiny-dogfish-in-the-northwest-atlantic/35579523/"},{"label":"Wikipedia — Rock salmon (dogfish species, IUCN status)","url":"https://en.wikipedia.org/wiki/Rock_salmon"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'spiny-dogfish'), 6, 'Eating & Consumption Notes', 'Dogfish is genuinely edible and has a long history as food — in the UK it''s sold in fish-and-chips shops as **"rock salmon"**, "huss," or "flake," and it''s also used in some smoked fish products. In the Maritimes, it''s overwhelmingly treated as a nuisance bycatch and released rather than kept for the table; documented recreational consumption practice in NB/NS/PEI specifically is thin, so treat it as "commonly released" rather than a standard local table fish.

If you do keep one to eat: shark flesh (dogfish included) carries urea in the blood and tissue that breaks down into ammonia after death. **Bleed and gut the fish immediately**, ice it right away, and fillet promptly — within about 24 hours untreated meat can develop a noticeable ammonia smell/taste. Even handled well, a brine, milk soak, or acid marinade (lime juice, vinegar) before cooking is standard practice to further neutralize any residual ammonia flavor. Given the conservation status above, most anglers here are better served releasing dogfish and keeping the cod, pollock, or flounder they were actually targeting.', '[{"label":"Wikipedia — Rock salmon","url":"https://en.wikipedia.org/wiki/Rock_salmon"},{"label":"SeafoodSource — Dogfish","url":"https://www.seafoodsource.com/seafood-handbook/finfish/dogfish"},{"label":"The Daily Meal — Why Marinating Shark Meat Is Absolutely Crucial","url":"https://www.thedailymeal.com/1461297/marinade-shark-meat-ammonia-smell/"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'spiny-dogfish'), 'NB', 'Tidal/saltwater (DFO Gulf Region jurisdiction)', 'Recreational groundfish fishery generally open per the annual Gulf Variation Order; no dogfish-specific season identified', 'Dogfish is not named in the current southern Gulf of St. Lawrence recreational groundfish notice (general 15 groundfish/day bag limit, with named exclusions for skate, wolffish species, and Atlantic halibut). Because dogfish isn''t explicitly addressed either way, anglers should confirm current-year treatment directly with DFO Gulf Region before retaining fish for the table — this is a gap in the public notice, not a confirmed allowance.', 'None specified', 'No provincial licence required for hook-and-line fishing in tidal/salt water. Rules apply to waters within 50 metres of the New Brunswick coastline. Commercial dogfish landings in the Gulf are managed separately from this recreational notice.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'spiny-dogfish'), 'NS', 'Tidal/saltwater (DFO Maritimes Region jurisdiction — Bay of Fundy and NS Atlantic coast from Halifax Harbour west to the NB border, and Hartlen Point east to Cape North)', 'Halifax Harbour and west (incl. Bay of Fundy): open Feb 1 - Dec 31. Hartlen Point east to Cape North: open 3rd Saturday in June through Labour Day.', 'Dogfish is explicitly listed as a managed groundfish species alongside cod, haddock, pollock, flounder, red/silver/white hake, and falls under the general daily groundfish bag limit: 10 groundfish/day (Halifax Harbour and west) or 5 groundfish/day (Hartlen Point east to Cape North). No dogfish-specific sub-limit.', 'None specified', 'Handline and angling gear only. No licence required for this groundfish category (distinct from the DFO recreational shark licence, which covers pelagic sharks like blue shark and porbeagle, not dogfish). Halibut, Northern wolffish, and Spotted wolffish retention is prohibited year-round.', 'https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/groundfish-poisson-fond-eng.html', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'spiny-dogfish'), 'PEI', 'Tidal/saltwater (DFO Gulf Region jurisdiction)', 'Recreational groundfish fishery generally open per the annual Gulf Variation Order; no dogfish-specific season identified', 'As with New Brunswick, dogfish is not named in the current Gulf of St. Lawrence recreational groundfish notice covering PEI''s coastline (general 15 groundfish/day bag limit, named exclusions for skate, wolffish species, and Atlantic halibut). Confirm current treatment with DFO Gulf Region before retaining for the table.', 'None specified', 'No provincial licence required for hook-and-line fishing in tidal/salt water. Rules apply to waters within 50 metres of the PEI coastline.', 'https://www.glf.dfo-mpo.gc.ca/en/recreational-groundfish-fishery-southern-gulf-st-lawrence-0', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'spiny-dogfish'), 0, 'Typical catch', 'Incidental bycatch while bottom fishing for cod, pollock, flounder — rarely a deliberate target here');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'spiny-dogfish'), 1, 'Identification', 'No anal fin; sharp spine forward of each of the 2 dorsal fins');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'spiny-dogfish'), 2, 'Danger', 'Mildly venomous dorsal spines — painful puncture wounds; watch the tail-whip');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'spiny-dogfish'), 3, 'Handling', 'De-hooking tool, keep fish in water if possible, grip from behind ahead of spines, gloves');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'spiny-dogfish'), 4, 'Regulatory status', 'Managed as groundfish (not under shark licence); NS has explicit bag limits, NB/PEI notices don''t name dogfish specifically — confirm with DFO before keeping');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'spiny-dogfish'), 5, 'Conservation', 'COSEWIC Special Concern (Atlantic, 2010); slow growth, ~2-year gestation — release promptly if not keeping');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'spiny-dogfish'), 6, 'Eating', 'Edible (UK ''rock salmon''/huss) but rarely kept locally; must bleed/ice/fillet fast to avoid ammonia taint');
