insert into species_sources (species_id, label, url) values ((select id from species where slug = 'spiny-dogfish'), 'CBC News — Spiny dogfish shark boom, bane for Nova Scotia fishermen', 'https://www.cbc.ca/news/canada/nova-scotia/spiny-dogfish-shark-boom-bane-for-nova-scotia-fishermen-1.2686688');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'spiny-dogfish'), 'PubMed — Envenoming in a fisherman, taxonomic and toxinologic comments on the Squalus genus', 'https://pubmed.ncbi.nlm.nih.gov/15922385/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'spiny-dogfish'), 'Wikipedia — Rock salmon', 'https://en.wikipedia.org/wiki/Rock_salmon');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'spiny-dogfish'), 'SeafoodSource — Dogfish', 'https://www.seafoodsource.com/seafood-handbook/finfish/dogfish');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'spiny-dogfish'), 0, 'Smooth Dogfish', 'lookalike', 'Mustelus canis', 'Smooth dogfish has no dorsal spines at all — its two dorsal fins are plain and spineless, versus spiny dogfish''s sharp spine in front of each dorsal fin. Smooth dogfish also has an anal fin (spiny dogfish has none), flat pavement-like teeth built for crushing rather than the small sharp teeth of spiny dogfish, and lacks the white spots scattered across a spiny dogfish''s back and sides.', 'More of a warm-water, southern New England/Mid-Atlantic species that occasionally reaches Maritime waters at the northern edge of its range; spiny dogfish is the default dogfish encountered region-wide.', 'The missing dorsal spines are the safety-relevant distinction — a smooth dogfish can be handled without the puncture risk spiny dogfish poses. Check for spines before assuming any small shark needs the same careful handling.', '/species/spiny-dogfish--variant-0.jpg', 'NOAA', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Mustelus_canis_noaa.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'spiny-dogfish'), 1, 'Juvenile Porbeagle', 'lookalike', 'Lamna nasus', 'Even a young porbeagle is a heavier-bodied, more torpedo-shaped shark than spiny dogfish, with a large first dorsal fin carrying a distinctive white patch on its free rear tip, no dorsal spines at all, and a secondary keel on the tail base alongside the main caudal keel (spiny dogfish has neither feature). Porbeagle teeth are large, pointed, and visible even in a small individual, unlike spiny dogfish''s small teeth in a comparatively slender jaw.', 'Offshore and open-water, encountered more on deeper boat trips than the shallow wharf/bottom-fishing water where spiny dogfish are typical bycatch.', 'Porbeagle is managed under DFO''s recreational shark licence system, a completely different regulatory track from spiny dogfish''s groundfish management — confirm which licence covers what''s in hand before deciding whether a fish can be retained.', NULL, NULL, NULL, NULL);

-- ===== Striped Bass (striped-bass) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('striped-bass', 'Striped Bass', 'Morone saxatilis', 'anadromous', '{"NB","NS","PEI"}'::text[], 'Explosive, hard-fighting anadromous gamefish that boomed off the near-collapse of the 1990s into a southern Gulf of St. Lawrence population over 900,000 strong, all spawned from one river system — the Miramichi — and now fished under a DFO slot-limit fishery from wharves, beaches, and river mouths across NB, NS, and PEI.', '/species/striped-bass.jpg', 'Timothy Knepp', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Striped_bass_FWS_1.jpg', true, now())
on conflict (slug) do update set
  common_name = excluded.common_name,
  scientific_name = excluded.scientific_name,
  category = excluded.category,
  provinces = excluded.provinces,
  summary = excluded.summary,
  image_path = excluded.image_path,
  image_credit = excluded.image_credit,
  image_license = excluded.image_license,
  image_source_url = excluded.image_source_url,
  is_published = true,
  updated_at = now();
delete from guide_sections where species_id = (select id from species where slug = 'striped-bass');
delete from regulations where species_id = (select id from species where slug = 'striped-bass');
delete from quick_reference where species_id = (select id from species where slug = 'striped-bass');
delete from species_sources where species_id = (select id from species where slug = 'striped-bass');
