insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'striped-bass'), 0, 'Know the Fish', 'Striped bass (*Morone saxatilis*) are anadromous, spawning in freshwater and doing most of their growing at sea. Identify them by 6-9 dark horizontal stripes running along a silvery body, a spiny first dorsal fin separate from the soft second dorsal, and a stout, deep-bodied shape.

The entire self-sustaining southern Gulf of St. Lawrence population spawns in one place: the tidal-fresh reach of the **Northwest Miramichi River estuary**, New Brunswick — the only confirmed successful spawning ground for this stock. Spawning happens in a brief window in late May to mid-June, concentrated over just a couple of kilometres of river, when water hits roughly 15.6-16.6°C. From near-collapse (fewer than 5,000 spawners in the late 1990s) the population rebuilt to more than 900,000 spawners by 2017, and fish from that single nursery now range every summer along the Northumberland Strait and Gulf shorelines of NB, NS, and PEI.

Note: this is a biologically separate stock from the smaller **Bay of Fundy population** (Shubenacadie/Minas Basin, NS), which has its own, much more conservative regulations (see the Nova Scotia entry below).', '[{"label":"Miramichi Salmon Association / Bradburns Fishing — Miramichi Conservation Updates","url":"https://www.bradburnsfishing.com/still-kelts-and-trout-miramichi-conservation-updates/"},{"label":"ResearchGate — Spawning and Early Life History of a Northern Population of Striped Bass in the Miramichi River Estuary","url":"https://www.researchgate.net/publication/238037476_Spawning_and_early_life_history_of_a_northern_population_of_striped_bass_Morone_saxatilis_in_the_Miramichi_River_estuary_Gulf_of_St_Lawrence"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'striped-bass'), 1, 'When to Go', 'Fish move out of Miramichi wintering grounds as ice melts (April) and are available through the tidal system and along the coast into October. Peak shore and boat action along the Northumberland Strait runs roughly **May through October**, with early season concentrated near the Miramichi and fish dispersing along NB, NS, and PEI beaches as water warms through summer.

Daily timing: DFO''s fishing-hours rules (below) effectively set your day — spring/early summer is sunrise-to-sunset plus a two-hour buffer each end; summer through fall opens up to a near round-the-clock window in tidal water outside the upper Miramichi.', '[{"label":"DFO Gulf Region — Striped Bass Recreational Fishery in the Southern Gulf of St. Lawrence in 2026","url":"https://www.glf.dfo-mpo.gc.ca/en/striped-bass-recreational-fishery-southern-gulf-st-lawrence-2026"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'striped-bass'), 2, 'Where to Find Them', '- **Miramichi River estuary (NB)** — the source population; both Northwest and Southwest Miramichi hold big numbers spring and fall.
- **Hillsborough River, Charlottetown (PEI)** — a well-known top striper spot right in the capital.
- **Malpeque Bay (PEI)** — good striper and mackerel water.
- **North Shore beaches near Rustico and Cavendish, and West Point/Jacques Cartier beach (PEI)** — popular rock/beach shore fishing.
- **Northport wharf (PEI)** — locally reported wharf action.
- **Northumberland Strait shoreline generally (NB & NS)** — wharves, river mouths, and estuaries all along the strait see summer/fall striper runs as Miramichi-origin fish disperse.
- **Shubenacadie and Minas Basin area (NS)** — different, smaller Bay of Fundy stock; check the separate, stricter Maritimes Region regulations before fishing here (see Regulations).

Always confirm you have permission/access at wharves — check with the local wharf authority and use designated parking.', '[{"label":"Tourism PEI — Ask an Islander: shore/dock fishing spots","url":"https://www.tourismpei.com/askanislander/questions/where-is-the-best-place-to-fish-off-shore-or-a-dock"},{"label":"Stripers of the Strait — Northumberland Strait Striped Bass Fishing","url":"https://www.stripersofthestrait.com/northumberland-strait-striped-bass-fishing"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'striped-bass'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Medium-heavy spinning rod, 7-9 ft, for casting distance off beaches/wharves and handling fish up to the 65 cm max slot. |
| Reel | Spinning reel with a strong, smooth drag and 150+ yards of 15-20 lb braid. |
| Terminal tackle | Single barbless hooks are mandatory — swap out trebles on hard baits for single inline hooks. |
| Lures/bait | Soft plastic paddletails and swimbaits, topwater poppers at dawn/dusk, and fresh-cut mackerel or gaspereau chunk bait on bottom rigs. |
| Extras | Long-handled net or lip-grip tool, tape measure (the 50-65 cm slot is enforced by law), pliers for quick hook removal. |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'striped-bass'), 4, 'Technique', '**Shore/wharf casting:** Cast paddletail swimbaits or spoons across the current and let them swing, retrieving with a steady swim or short pumps — stripers often hold on current seams near pilings, river mouths, and drop-offs adjacent to wharves.

**Topwater:** Dawn and dusk, work poppers or walk-the-dog style plugs over shallow flats and sandbars where bass are pushing bait.

**Bait fishing:** Fresh-cut mackerel or gaspereau on a simple bottom rig (egg sinker above a swivel, leader, single barbless hook) fished in current seams or river-mouth holes is a proven, low-effort producer, especially for bigger fish.

**Measure before you decide to keep one** — the 50-65 cm slot is unforgiving and DFO enforces it; a fish outside that window must go back immediately.', '[{"label":"DFO Gulf Region — Striped Bass Recreational Fishery in the Southern Gulf of St. Lawrence in 2026","url":"https://www.glf.dfo-mpo.gc.ca/en/striped-bass-recreational-fishery-southern-gulf-st-lawrence-2026"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'striped-bass'), 5, 'Handling & Release', '- Fish outside the 50-65 cm slot, and anything beyond your daily/possession limit of 4, must be released immediately.
- Support the fish horizontally with wet hands; avoid squeezing the belly or holding by the eyes/gills.
- Use single barbless hooks (legally required) to speed unhooking and cut handling time.
- If bleeding heavily from deep hooking, consider it a mortality risk and count it against your limit rather than trying to release a fish unlikely to survive.
- Never fish or handle striped bass in the Northwest Miramichi spawning closure zone when it''s posted (a roughly 9.8 km stretch that can close for up to 10 days during peak spawning).', '[{"label":"DFO Gulf Region — Striped Bass Recreational Fishery in the Southern Gulf of St. Lawrence in 2026","url":"https://www.glf.dfo-mpo.gc.ca/en/striped-bass-recreational-fishery-southern-gulf-st-lawrence-2026"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'striped-bass'), 6, 'Conservation & Consumption Notes', 'The southern Gulf population''s recovery from under 5,000 spawners in the late 1990s to over 900,000 by 2017 is a genuine conservation success story, driven directly by tight recreational and commercial controls — which is exactly why the slot limit, hook restrictions, and Miramichi spawning closure exist and are actively enforced. Fish within the slot cook up well and there''s no widespread consumption advisory for this species in the region, but treat the Miramichi spawning grounds and closure notices as non-negotiable: this is the one river that sustains the entire regional fishery.

The separate Bay of Fundy (Shubenacadie/Minas Basin) stock is far smaller and managed far more conservatively by DFO Maritimes Region — don''t assume Gulf Region rules apply there.', '[{"label":"ResearchGate — Spawning and Early Life History of Miramichi Striped Bass","url":"https://www.researchgate.net/publication/238037476_Spawning_and_early_life_history_of_a_northern_population_of_striped_bass_Morone_saxatilis_in_the_Miramichi_River_estuary_Gulf_of_St_Lawrence"},{"label":"DFO Maritimes Region — Tidal and Freshwater (Diadromous) Recreational Fisheries","url":"https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/diadrom-eng.html"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'striped-bass'), 'NB', 'Tidal/saltwater and Miramichi River system (southern Gulf stock)', 'Tidal waters Apr 15–Oct 31; Miramichi River system Apr 15–Oct 15', '4 per day; possession limit of 4 at any time', 'Slot limit 50-65 cm total length (nose to tail); must release outside slot', 'Single barbless hooks mandatory. Fishing hours: Apr 15–Jun 30 two hours before sunrise to two hours after sunset; Jul 1–Oct 31, 04:00–00:00 except tidal Miramichi upstream of Centennial Bridge. Northwest Miramichi spawning area closes for up to 10 days during peak spawning (~9.8 km stretch). No provincial licence needed in tidal salt water.', 'https://www.glf.dfo-mpo.gc.ca/en/striped-bass-recreational-fishery-southern-gulf-st-lawrence-2026', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'striped-bass'), 'NS', 'Northumberland Strait/Gulf shore (southern Gulf stock)', 'Tidal waters Apr 15–Oct 31; inland waters May 1–Sep 15', '4 per day; possession limit of 4 at any time', 'Slot limit 50-65 cm total length', 'Same Gulf Region rules as NB apply along NS''s Northumberland Strait/Gulf shoreline. IMPORTANT: the separate Bay of Fundy stock (e.g. Shubenacadie/Minas Basin) is managed under different, much stricter DFO Maritimes Region rules — 1 fish/day, 68-150 cm slot reported, plus a fly/unbaited-lure-only, catch-and-release window (~May 10–Jun 10) on the Shubenacadie downstream of the CN Railway Bridge at East Milford. Confirm which stock''s water you''re fishing before keeping a fish.', 'https://www.glf.dfo-mpo.gc.ca/en/striped-bass-recreational-fishery-southern-gulf-st-lawrence-2026', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'striped-bass'), 'PEI', 'Tidal/saltwater (southern Gulf stock)', 'Tidal waters Apr 15–Oct 31; inland waters Apr 15–Sep 15', '4 per day; possession limit of 4 at any time', 'Slot limit 50-65 cm total length', 'Single barbless hooks mandatory; same fishing-hours structure as NB/NS Gulf Region waters. No provincial licence needed in tidal salt water.', 'https://www.glf.dfo-mpo.gc.ca/en/striped-bass-recreational-fishery-southern-gulf-st-lawrence-2026', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'striped-bass'), 0, 'Slot Limit', '50-65 cm total length — keep only fish inside this window');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'striped-bass'), 1, 'Daily/Possession Limit', '4 fish per day; max 4 in possession at any time');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'striped-bass'), 2, 'Season', 'Tidal waters Apr 15–Oct 31 (Gulf stock)');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'striped-bass'), 3, 'Gear Rule', 'Single barbless hooks required; max 5 lines/6 hooks tidal, 1 line/3 hooks inland');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'striped-bass'), 4, 'Hours', 'Apr 15–Jun 30: 2 hrs before sunrise to 2 hrs after sunset. Jul 1–Oct 31: 04:00–midnight (most tidal water)');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'striped-bass'), 5, 'Watch For', 'Northwest Miramichi spawning closure (late May–June); Bay of Fundy stock has separate stricter rules');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'striped-bass'), 6, 'Source Population', 'Northwest Miramichi River estuary — the only confirmed spawning ground for this stock');
