insert into species_sources (species_id, label, url) values ((select id from species where slug = 'striped-bass'), 'Stripers of the Strait — Northumberland Strait Striped Bass Fishing', 'https://www.stripersofthestrait.com/northumberland-strait-striped-bass-fishing');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'striped-bass'), 0, 'Southern Gulf of St. Lawrence Stock (Miramichi-spawned)', 'stock', NULL, 'No visible physical difference from the Bay of Fundy stock — the two are told apart by genetics (they are isolated and genetically distinct populations) and by where and when you catch them, not by markings on the fish.', 'The entire Northumberland Strait and Gulf shoreline of NB, NS, and PEI — all spawned in one place, the Northwest Miramichi River estuary, then disperse coastwide each summer.', 'This is the large, recovered stock (900,000+ spawners) that the standard 50-65 cm slot and 4-fish daily limit apply to. It is a completely separate population from the Bay of Fundy stock below, even though the fish look identical.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'striped-bass'), 1, 'Bay of Fundy Stock (Shubenacadie/Minas Basin)', 'stock', NULL, 'Physically indistinguishable from the southern Gulf stock. Identified only by location: any striped bass caught in the Bay of Fundy/upper Minas Basin drainage, including the Shubenacadie and Stewiacke rivers, belongs to this separate, genetically distinct, much smaller population.', 'Shubenacadie and Stewiacke rivers and the Minas Basin (NS) — spawns in the inner Bay of Fundy rather than the Miramichi.', 'Managed far more conservatively by DFO Maritimes Region than the Gulf Region slot fishery: reported rules include a 1 fish/day limit, a wider 68-150 cm slot, and a fly/unbaited-lure-only catch-and-release window (roughly May 10-Jun 10) on parts of the Shubenacadie. Confirm current Maritimes Region regulations before keeping any fish here — Gulf Region rules (50-65 cm, 4/day) do not apply.', NULL, NULL, NULL, NULL);
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'striped-bass'), 2, 'Juvenile Striped Bass', 'lookalike', 'Morone americana', 'A small striped bass still shows continuous, unbroken horizontal stripes running the length of the body, a slender profile (body depth generally less than a third of its length), a spiny first dorsal fin clearly separated from the soft second dorsal, and two tooth patches side by side on the back of the tongue. White perch lack horizontal stripes entirely (or show only faint, broken ones), are noticeably deeper-bodied, have dorsal fins that are barely connected, and lack the central double tooth patch on the tongue.', 'Anywhere small stripers and white perch overlap — river mouths, estuaries, and tidal reaches across NB, NS, and PEI, especially the Miramichi and other Northumberland Strait systems.', 'Consequential mix-up: white perch has its own separate limits, while any striped bass under the 50 cm minimum must be released immediately. Keeping an undersized striper because it was mistaken for a white perch is an offence under the striped bass slot-limit rule.', '/species/striped-bass--variant-2.jpg', 'Cephas', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Morone_americana_PAQ.jpg');

-- ===== White Perch (white-perch) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('white-perch', 'White Perch', 'Morone americana', 'freshwater', '{"NB","NS","PEI"}'::text[], 'A schooling, brackish-water-loving panfish common in estuaries, tidal headponds, and barrier-beach ponds across NB, NS, and PEI. Bag limits have recently been tightened in both NS and PEI, so check current numbers before keeping a big cooler-full.', '/species/white-perch.jpg', 'Cephas', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Morone_americana_PAQ.jpg', true, now())
