delete from guide_sections where species_id = (select id from species where slug = 'white-perch');
delete from regulations where species_id = (select id from species where slug = 'white-perch');
delete from quick_reference where species_id = (select id from species where slug = 'white-perch');
delete from species_sources where species_id = (select id from species where slug = 'white-perch');
delete from species_variants where species_id = (select id from species where slug = 'white-perch');
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'white-perch'), 0, 'Know the Fish', 'White perch (*Morone americana*) are a small, silvery, deep-bodied member of the temperate bass family (related to striped bass, not to yellow perch despite the name) — no stripes, no dark bars, just a uniform silver-to-olive body and two connected dorsal fins. Most run 7-11 inches. They''re a schooling species that tolerates a wide salinity range, which is why they thrive in estuaries, river mouths, and the brackish barrier-beach ponds common along the PEI and NB coastlines, as well as in freshwater headponds well upriver.', '[{"label":"Nova Scotia Invasive Species Council, Chain Pickerel (native-alternative species reference)","url":"https://nsinvasives.ca/chain-pickerel/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'white-perch'), 1, 'Where to Find Them', '**New Brunswick:** anglers report good white perch fishing at the **Hampton Lighthouse River Centre** area on the Kennebecasis, the **Mactaquac headpond** on the Saint John River, **Maquapit Lake**, and **Wauklehegan Lake**.

**PEI:** white perch are common in the island''s estuaries and brackish **barrier-beach ponds**, including documented catches in the **Johnstons River** and **Desroches Pond** systems, and in the Morell River system alongside brook trout.

**Nova Scotia:** found in tidal rivers and estuaries province-wide wherever brackish, slow-current water exists — check local river mouths and headponds.', '[{"label":"New Brunswick Fishing Forum, White Perch Fishing","url":"https://www.newbrunswickfishing.com/threads/white-perch-fishing.868/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'white-perch'), 2, 'When to Go', 'White perch move into shallower, warmer water to spawn in spring, which is when they''re easiest to find and catch in numbers close to shore. They remain a solid summer-through-fall target in estuaries and headponds, and in PEI in particular, ice fishing for perch through the winter has grown into its own dedicated fishery on brackish ponds where ice forms reliably.', '[{"label":"CBC News, Ice fishing for perch could be a thing on P.E.I.","url":"https://www.cbc.ca/news/canada/prince-edward-island/pei-white-perch-fishery-1.5452838"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'white-perch'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod | Light spinning rod, 6-7 ft, 4-8 lb line — white perch fight modestly and light gear makes it fun. |
| Terminal tackle | Small jigs, spinners, or a simple bobber-and-worm/minnow rig. |
| Bait | Worms, small minnows, or small strips of cut bait work well in brackish water. |
| Ice gear | Same small jigs/teardrops used for yellow perch, tipped with a waxworm or minnow head. |', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'white-perch'), 4, 'Technique', '1. Fish river mouths, headpond current seams, and pond inlets where fresh and brackish water mix — perch stack up at these transition zones.
2. Once you find a school, stay on it — white perch bite fast and often in numbers, similar to yellow perch.
3. A simple bobber rig with a small piece of worm or a small jig worked slowly near bottom will out-produce more complicated presentations for this species.
4. In headponds like Mactaquac, fish the slower, deeper water along the margins of the main current rather than in the fastest flow.', '[]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'white-perch'), 5, 'Conservation & Consumption Notes', 'White perch are good, mild table fish, but bag limits have been trending down across the region as fisheries managers keep an eye on local population pressure — Nova Scotia''s current Anglers'' Handbook lists the white perch bag limit reduced to **10 fish**, and PEI''s daily limit was cut from a historical 100 fish down to **25 fish** in recent regulation summaries. Fish conservatively even where an older, higher number might still be floating around online — always check the current-year regulations summary for your province before keeping a full cooler.', '[{"label":"Nova Scotia Anglers'' Handbook and Summary of Regulations","url":"https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf"}]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'white-perch'), 'NB', 'Freshwater/estuarine', 'Season varies by water body — check the current GNB Fish Regulations Summary', 'Varies by water body — check current regulations summary; no single province-wide figure independently confirmed for this guide', 'Varies by water body — see current regulations summary', 'A valid NB angling licence is required in freshwater; tidal/estuarine water where no provincial licence is needed may still fall under DFO rules — confirm which applies for your specific location.', 'https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'white-perch'), 'NS', 'Freshwater/estuarine', 'See current Nova Scotia Anglers'' Handbook for season dates by Recreational Fishing Area', '10 fish per day (recently reduced) — confirm in the current-year Anglers'' Handbook, as this can vary further by Recreational Fishing Area', 'Not independently confirmed for this guide — see current handbook', 'A valid NS angling licence is required for freshwater fishing.', 'https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'white-perch'), 'PEI', 'Freshwater/estuarine', 'Open season per current PEI Angling Summary; a growing winter ice-fishery for perch exists on select brackish ponds', '25 fish per day, minimum length 10 cm (3.9") per the 2025-2026 season referenced in current sources — confirm against the current-year PEI Angling Summary', '10 cm (3.9") minimum', 'A valid PEI angling licence is required for freshwater/estuarine angling; anglers under 16 fish free. The daily limit was reduced from a historical 100 fish to 25 in recent years.', 'https://www.princeedwardisland.ca/en/publication/2025-angling-summary', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'white-perch'), 0, 'Habitat', 'Estuaries, tidal headponds, and brackish barrier-beach ponds');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'white-perch'), 1, 'Best Time', 'Spring spawn through fall; growing winter ice fishery in PEI');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'white-perch'), 2, 'Where (NB)', 'Hampton (Kennebecasis), Mactaquac headpond, Maquapit Lake, Wauklehegan Lake');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'white-perch'), 3, 'Where (PEI)', 'Johnstons River, Desroches Pond, Morell River system');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'white-perch'), 4, 'Bag Limit Trend', 'Reduced recently in both NS (to 10) and PEI (to 25) — check current-year regs');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'white-perch'), 'New Brunswick Fishing Forum, White Perch Fishing', 'https://www.newbrunswickfishing.com/threads/white-perch-fishing.868/');
