insert into species_sources (species_id, label, url) values ((select id from species where slug = 'white-perch'), 'PEI 2025 Angling Summary', 'https://www.princeedwardisland.ca/en/publication/2025-angling-summary');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'white-perch'), 'CBC News, Ice fishing for perch could be a thing on P.E.I.', 'https://www.cbc.ca/news/canada/prince-edward-island/pei-white-perch-fishery-1.5452838');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'white-perch'), 0, 'Juvenile Striped Bass', 'lookalike', 'Morone saxatilis', 'This is the single most important ID check in this guide. Striped bass carry 7-8 dark, continuous horizontal stripes running the length of the body — white perch have none at all, just a uniform silvery-to-olive flank. If stripes aren''t obvious, check the tongue: striped bass have two distinct tooth patches on the back of the tongue (feel for two rough spots running your finger down the centerline), while white perch have none. Body shape backs this up too — striped bass are slender and torpedo-shaped (depth less than about a third of body length), while white perch are noticeably deeper-bodied for their size. Striped bass also have two dorsal fins that are clearly separated with a gap between them; a white perch''s two dorsal fins are close together, nearly touching.', 'Juvenile striped bass use the exact same brackish estuary and headpond water white perch do across all three provinces — anywhere you catch white perch, a small striper is a realistic catch too, especially near river mouths that connect to known striped bass spawning rivers like the Miramichi.', 'This is a legally serious mix-up. Striped bass have a minimum retainable size in all three provinces, and undersized striped bass must be released — keeping one because it was mistaken for a white perch is an offence. Check stripes and the tongue on every fish before it goes in the cooler, not just the ones that look obviously different.', '/species/white-perch--variant-0.jpg', 'Smithsonian Environmental Research Center', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Morone_saxatilis_(S0016)_(12679096963).jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'white-perch'), 1, 'Yellow Perch', 'lookalike', 'Perca flavescens', 'Yellow perch are a true perch (family Percidae), not a bass, and look it: a golden-yellow body with 6-8 sharp, dark vertical bars, versus a white perch''s plain silvery-olive flank with no bars or stripes at all. Yellow perch also have a triangular pelvic fin angled out at roughly 45 degrees, while a white perch''s pelvic fin points straight down and widens toward the tip.', 'Both species share freshwater headponds and lake systems, including stretches of the Saint John River system — yellow perch lean more toward fully fresh water, white perch tolerate brackish water further downstream.', 'No shared retention concern, but yellow perch cannot legally be used as bait anywhere in NB, a rule that does not apply to white perch — worth knowing if you''re catching incidental fish to use as bait for something else.', '/species/white-perch--variant-1.jpg', 'Robert Colletta', 'Public domain', 'https://commons.wikimedia.org/wiki/File:D3149-1._yellow_perch_(Perca_flavescens).jpg');

-- ===== Winter Flounder (winter-flounder) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('winter-flounder', 'Winter Flounder', 'Pseudopleuronectes americanus', 'saltwater', '{"NB","NS","PEI"}'::text[], 'Small, easy-to-catch flatfish taken from wharves, shallow bays, and estuary mouths on mud-sand bottom, best in spring and early summer on light bottom tackle with worms or clams.', '/species/winter-flounder.jpg', 'Smithsonian Environmental Research Center', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Pseudopleuronectes_americanus_(S0892)_(12658628105).jpg', true, now())
