insert into species_sources (species_id, label, url) values ((select id from species where slug = 'winter-flounder'), 'Tourism PEI, Ask an Islander — flounder fishing in PEI', 'https://www.tourismpei.com/askanislander/questions/i-want-to-fish-for-flounder-in-pei-where-should-i-do-that-i-am-there-the');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'winter-flounder'), 0, 'Atlantic Halibut', 'lookalike', 'Hippoglossus hippoglossus', 'Both are right-eyed flatfish, so eye side alone will NOT tell them apart — this is the important trap. The reliable checks are the lateral line and mouth: halibut has a lateral line that arcs sharply above the pectoral fin (winter flounder''s lateral line runs nearly straight), and a large, gaping mouth that extends back to the eyes (winter flounder''s mouth is small, built for picking at worms and clams). Halibut also has a concave/forked tail versus winter flounder''s rounded tail, and even a small halibut is proportionally more elongated and diamond-shaped than a winter flounder of the same length.', 'Halibut are typically a deeper, offshore fish, but juveniles can turn up inshore in the same soft-bottom flats and channels winter flounder are caught from — the overlap is real, not theoretical.', 'Atlantic halibut is ZERO RETENTION year-round in these waters under both DFO Gulf and Maritimes Region rules, with no exceptions in the aggregate groundfish bag limits. Keeping even a small halibut mistaken for a large winter flounder is a genuine regulatory violation, not a technicality — check the lateral-line arc and mouth size on anything unusually large or big-mouthed before it goes in the cooler, and release any halibut immediately.', '/species/winter-flounder--variant-0.jpg', 'U.Name.Me', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Hippoglossus_hippoglossus_NHM.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'winter-flounder'), 1, 'Yellowtail Flounder', 'lookalike', 'Limanda ferruginea', 'Yellowtail flounder has a yellow tail fin and yellow-edged dorsal/anal fins, a thinner body, and large rusty-red irregular spots on an olive-brown back — all absent on winter flounder, which runs plain brown to almost black with no yellow trim. Yellowtail also has an arched lateral line versus winter flounder''s nearly straight one, though both share a small mouth.', 'More of an offshore/deeper-water species than winter flounder, less commonly encountered from shore in this region.', 'Both count toward the same groundfish aggregate bag limit, so misidentifying one for the other has no regulatory consequence here, but the yellow tail is a fast, reliable field check if it comes up.', '/species/winter-flounder--variant-1.jpg', 'NOAA Fisheries', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Limanda_ferruginea_(NOAA)_no_watermark.png');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'winter-flounder'), 2, 'American Plaice', 'lookalike', 'Hippoglossoides platessoides', 'American plaice has a distinctly larger mouth than winter flounder''s small worm-picking mouth, a rounded tail, and a nearly straight lateral line, with a reddish-brown eyed side. The larger mouth is the fastest check against winter flounder specifically.', 'Deeper offshore bottom generally, less of a shore-caught fish than winter flounder in this region.', 'Counts toward the same groundfish aggregate bag limit as winter flounder — no separate rule to worry about, just worth knowing if a bigger-mouthed flatfish turns up on flounder gear.', '/species/winter-flounder--variant-2.jpg', 'André-Philippe D. Picard', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Plie_canadienne_(Hippoglossoides_platessoides).jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'winter-flounder'), 3, 'Witch Flounder', 'lookalike', 'Glyptocephalus cynoglossus', 'Witch flounder is narrower and less oval than winter flounder, with a small head and mouth, and often a dusky-to-black patch on the topside pectoral fin with a faint pale border — a mark winter flounder lacks entirely.', 'A deeper, offshore species, uncommon in the shallow shore/estuary water winter flounder are typically caught from.', 'Counts toward the same groundfish aggregate limit as winter flounder — no separate rule, just useful for ID if one turns up on deeper boat gear.', '/species/winter-flounder--variant-3.jpg', 'Cedricguppy - Loury Cédric', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Glyptocephalus_cynoglossus_-_(Pleuronectes_cynoglossus)_-_squelette_mnhn_Paris.JPG');

-- ===== Yellow Perch (yellow-perch) =====
insert into species (slug, common_name, scientific_name, category, provinces, summary, image_path, image_credit, image_license, image_source_url, is_published, updated_at)
values ('yellow-perch', 'Yellow Perch', 'Perca flavescens', 'freshwater', '{"NB","NS","PEI"}'::text[], 'Widespread, easy-to-catch freshwater panfish found in lakes across all three Maritime provinces — a reliable year-round target, especially popular through the ice in winter.', '/species/yellow-perch.jpg', 'Robert Colletta', 'Public domain', 'https://commons.wikimedia.org/wiki/File:D3149-1._yellow_perch_(Perca_flavescens).jpg', true, now())
on conflict (slug) do update set
  common_name = excluded.common_name,
  scientific_name = excluded.scientific_name,
  category = excluded.category,
  provinces = excluded.provinces,
  summary = excluded.summary,
  image_path = excluded.image_path,
  image_credit = excluded.image_credit,
  image_license = excluded.image_license,
  image_source_url = excluded.image_source_url,
  is_published = true,
  updated_at = now();
delete from guide_sections where species_id = (select id from species where slug = 'yellow-perch');
delete from regulations where species_id = (select id from species where slug = 'yellow-perch');
delete from quick_reference where species_id = (select id from species where slug = 'yellow-perch');
delete from species_sources where species_id = (select id from species where slug = 'yellow-perch');
delete from species_variants where species_id = (select id from species where slug = 'yellow-perch');
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'yellow-perch'), 0, 'Know the Fish', 'Yellow perch (*Perca flavescens*) are easy to identify: golden-yellow body, 6–8 dark vertical bars, and orange-tinged lower fins. They school tightly by size and are active feeders on insect larvae, small crustaceans, and baitfish, which is why perch fishing is often a fast, high-volume affair once you find the school. Most Maritime lake perch run 6–10 inches, with 12-inch-plus "jumbos" a nice bonus.

Perch are native and common across most of NB and NS; on Prince Edward Island they aren''t native but are established through stocking in a number of colder, spring-fed freshwater bodies, and are a popular ice-fishing target there.', '[{"label":"New Brunswick Fishing Forum, Yellow Perch?","url":"https://www.newbrunswickfishing.com/threads/yellow-perch.71/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'yellow-perch'), 1, 'Where to Find Them', '**New Brunswick:** widely reported across the Saint John River valley and Fredericton/Saint John area lakes — **French Lake** is called out by local anglers as one of the most consistently active yellow perch lakes, and in the Saint John area, **Douglas Lake** (off Loch Lomond Road), **Hunter Lake, McBrien''s Lake, and First, Second, and Third Lakes** are all reported producers.

**Nova Scotia:** perch are present in lakes throughout the province and are a common bycatch/target species wherever anglers fish for bass or trout in weedy lake systems.

**PEI:** perch are stocked in a number of colder freshwater ponds and lakes on the island and are a particularly popular target for ice anglers in winter.', '[{"label":"New Brunswick Fishing Forum, Yellow Perch?","url":"https://www.newbrunswickfishing.com/threads/yellow-perch.71/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'yellow-perch'), 2, 'When to Go', 'Yellow perch are a genuine year-round target in this region. Open-water fishing is best in spring right after ice-out (perch spawn early, in shallow water, and feed hard beforehand) and again in fall as they bulk up for winter. Through summer they tend to move a bit deeper and school around structure. Ice fishing is a major part of the yellow perch fishery here — schools concentrate predictably under the ice and can be caught in numbers through a single hole once located.', '[{"label":"Wired2Fish, How to Chase Wintertime Yellow Perch","url":"https://www.wired2fish.com/winter-fishing/how-to-chase-wintertime-yellow-perch"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'yellow-perch'), 3, 'Gear', '| Item | Recommendation |
|---|---|
| Rod (open water) | Light spinning rod, 6–7 ft, 4-8 lb line. |
| Rod (ice) | Short (24-32") light-action ice rod with a sensitive spring or spiral bobber tip. |
| Terminal tackle | Small jigs (1/16-1/8 oz), teardrop jigs, and jigging spoons in the 1.25-2 inch range. |
| Bait | Fresh minnows (whole or a minnow head on a jig), waxworms, or maggots/spikes. |
| Extras | A small sonar/flasher unit helps a lot for locating suspended schools through the ice. |', '[{"label":"Outdoor Life, Tips for Catching Jumbo Yellow Perch Through the Ice","url":"https://www.outdoorlife.com/fishing/tips-ice-fishing-jumbo-perch/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'yellow-perch'), 4, 'Technique', '1. Start fishing near bottom — perch feed close to bottom more often than not — then work up through the water column if you''re marking fish higher.
2. Tip a small jig or jigging spoon with a fresh minnow head, waxworm, or maggot; perch will hit bare jigs when actively feeding but a scent/flavor edge usually out-produces plastic alone.
3. Use a subtle presentation: light jiggling shakes and slow lift-and-pause work better than aggressive snapping, especially on pressured or finicky schools.
4. Once you find a school (through the ice especially), stay put — perch school tight, and a productive hole can often be fished steadily rather than searched away from.
5. In open water, target weed edges, drop-offs, and points in spring and fall; move to deeper basin structure in summer.', '[{"label":"Outdoor Life, Tips for Catching Jumbo Yellow Perch Through the Ice","url":"https://www.outdoorlife.com/fishing/tips-ice-fishing-jumbo-perch/"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'yellow-perch'), 5, 'Handling & Consumption', 'Yellow perch have sharp dorsal spines — grip fish from the top down, laying the spines flat, or cradle them belly-up to unhook safely. They''re excellent, mild-flavored table fish and a traditional favorite for shore lunches and fish fries across the Maritimes; fillet around the light rib cage and skin is optional given their small size.

**Important bait restriction (NB):** it is illegal to use yellow perch as live or dead bait in New Brunswick waters — plan to bring commercial bait rather than perch you''ve caught yourself.', '[{"label":"Government of New Brunswick, Fish NB Angling Regulations (regulations summary)","url":"https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf"}]'::jsonb);
insert into guide_sections (species_id, position, heading, body_md, sources) values ((select id from species where slug = 'yellow-perch'), 6, 'Conservation & Consumption Notes', 'Yellow perch populations are generally healthy and abundant across the region — this is a species you can fish hard without conservation concern in most waters. As with any panfish, extremely heavy harvest pressure on a small lake can shift a population toward smaller average size over time, so many experienced anglers voluntarily release larger "breeder" fish and keep average-size perch for the table.', '[]'::jsonb);
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'yellow-perch'), 'NB', 'Freshwater', 'Open season varies by water body — recreational ice fishing for yellow perch (by angling or set lines in permitted waters) generally runs January 1 to March 31 in addition to the regular open-water season; confirm exact dates for your water in the current GNB Fish Regulations Summary', 'Fishing quotas and length limits vary by specific water body — check the current regulations summary for the lake you plan to fish', 'Varies by water body — see current regulations summary', 'A valid NB angling licence is required. Yellow perch may not be used as live or dead bait anywhere in NB.', 'https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'yellow-perch'), 'NS', 'Freshwater', 'See current Nova Scotia Anglers'' Handbook for season dates by Recreational Fishing Area — many areas offer expanded winter/ice fishing opportunities for yellow perch', 'No specific bag limit figure independently confirmed for this guide — consult the current Anglers'' Handbook for your Recreational Fishing Area', 'None specified in sources reviewed', 'A valid NS angling licence is required for freshwater fishing.', 'https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf', '2026');
insert into regulations (species_id, province, water_type, season, bag_limit, size_limit, notes, source_url, last_verified) values ((select id from species where slug = 'yellow-perch'), 'PEI', 'Freshwater', 'Yellow perch are a popular target during PEI''s winter ice-fishing season on select stocked ponds/lakes — check the current PEI Angling Summary for open dates and eligible waters', 'Not independently confirmed for this guide — consult the current PEI Angling Summary', 'Not independently confirmed for this guide — consult the current PEI Angling Summary', 'A valid PEI angling licence is required for freshwater fishing; anglers under 16 fish free. Yellow perch are not native to PEI but are stocked in a number of freshwater bodies.', 'https://www.princeedwardisland.ca/en/publication/2025-angling-summary', '2026');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'yellow-perch'), 0, 'Season', 'Year-round target — spring/fall open water plus a strong winter ice fishery');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'yellow-perch'), 1, 'Where (NB)', 'French Lake, Douglas/Hunter/McBrien''s/1st-3rd Lakes (Saint John area)');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'yellow-perch'), 2, 'Gear', 'Light spinning or ice rod, small jigs/teardrops tipped with minnow head or waxworm');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'yellow-perch'), 3, 'Bait note (NB)', 'Illegal to use yellow perch as bait anywhere in NB');
insert into quick_reference (species_id, position, label, value) values ((select id from species where slug = 'yellow-perch'), 4, 'Table Fare', 'Excellent, mild white flesh — a Maritime shore-lunch staple');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'yellow-perch'), 'New Brunswick Fishing Forum, Yellow Perch?', 'https://www.newbrunswickfishing.com/threads/yellow-perch.71/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'yellow-perch'), 'Government of New Brunswick, Fish NB Angling Regulations (regulations summary)', 'https://www2.gnb.ca/content/dam/gnb/Departments/nr-rn/pdf/en/Fish/Fish.pdf');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'yellow-perch'), 'Nova Scotia Anglers'' Handbook and Summary of Regulations', 'https://www.novascotia.ca/sites/default/files/documents/1-2412/anglers-handbook-en.pdf');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'yellow-perch'), 'PEI 2025 Angling Summary', 'https://www.princeedwardisland.ca/en/publication/2025-angling-summary');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'yellow-perch'), 'Outdoor Life, Tips for Catching Jumbo Yellow Perch Through the Ice', 'https://www.outdoorlife.com/fishing/tips-ice-fishing-jumbo-perch/');
insert into species_sources (species_id, label, url) values ((select id from species where slug = 'yellow-perch'), 'Wired2Fish, How to Chase Wintertime Yellow Perch', 'https://www.wired2fish.com/winter-fishing/how-to-chase-wintertime-yellow-perch');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'yellow-perch'), 0, 'White Perch', 'lookalike', 'Morone americana', 'White perch belong to the temperate bass family, not the perch family, and it shows: a uniform silvery-to-olive body with no vertical bars at all, versus a yellow perch''s 6-8 sharply defined dark bars on a golden-yellow body. White perch also run deeper-bodied with two dorsal fins set close together, while a yellow perch''s pelvic fin points out at a 45-degree angle rather than the downward, widening pelvic fin of a white perch.', 'Both species overlap in slow, brackish-influenced water — Mactaquac headpond and other Saint John River system headponds hold both. Yellow perch stick to fully fresh water more consistently; white perch tolerate and often prefer brackish estuary mouths.', 'No retention consequence between these two, but the bait-use rule differs: yellow perch cannot legally be used as bait anywhere in NB, a restriction that does not apply to white perch.', '/species/yellow-perch--variant-0.jpg', 'Cephas', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Morone_americana_PAQ.jpg');
insert into species_variants (species_id, position, name, kind, scientific_name, how_to_tell, where_found, notes, image_path, image_credit, image_license, image_source_url) values ((select id from species where slug = 'yellow-perch'), 1, 'Juvenile Walleye', 'lookalike', 'Sander vitreus', 'Walleye are true Percidae relatives of yellow perch and share the same family fang-like conical teeth on both — but yellow perch never develop the walleye''s large canine teeth, and a small walleye shows a more olive-gold, mottled body with a distinctive white-tipped lower lobe of the tail fin, which yellow perch lack entirely.', 'Anywhere the two species share water in NB lake systems with both stocked or naturalized populations — check locally which lakes carry walleye before assuming every small perch-shaped fish is a yellow perch.', 'Walleye regulations (seasons, size limits) differ from yellow perch — confirm which species you have before keeping a small fish from a lake known to hold both.', '/species/yellow-perch--variant-1.jpg', 'USFWS Mountain-Prairie', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Walleye_Fingerling_(9518198980).jpg');

-- ===== Location guide: Shore Fishing Around Launching, PEI (launching-pei) =====
insert into location_guides (slug, title, province, region_name, intro_md, lat, lng, is_published, updated_at)
values ('launching-pei', 'Shore Fishing Around Launching, PEI', 'PEI', 'Boughton Bay & The Three Rivers, Kings County', 'Launching is a small community on Boughton Bay / Launching Harbour in Kings County, Prince Edward Island, between Annandale and Georgetown. It sits at the edge of one of PEI''s best-known fishing systems: The Three Rivers — the Brudenell, Cardigan, and Montague Rivers — which converge into Cardigan Bay right beside Georgetown, a few minutes from Launching. This whole area is tidal estuary and open coastline, meaning nearly everything in this guide is saltwater/tidal fishing that does not require a provincial licence.

Panmure Island Provincial Park, about 15 km away, gives two very different types of water off the same causeway: the sheltered St. Mary''s Bay side, and the open Gulf of St. Lawrence side. That contrast — calm estuary vs. open surf — is useful, because different species and techniques favour each.

**Regulations overview**: PEI recreational saltwater fishing is managed by Fisheries and Oceans Canada (DFO), Gulf Region. No provincial licence is needed for tidal-water species (striped bass, mackerel, flounder, smelt, eel, etc.). A provincial PEI angling licence IS required for freshwater/inland species such as brook trout, rainbow trout, and Atlantic salmon. See each species'' own guide for full current bag limits, seasons, and size limits — DFO issues variation orders that can change dates and limits with little notice.', 46.2, -62.4, true, now())
on conflict (slug) do update set
  title = excluded.title,
  province = excluded.province,
  region_name = excluded.region_name,
  intro_md = excluded.intro_md,
  lat = excluded.lat,
  lng = excluded.lng,
  is_published = true,
  updated_at = now();
delete from location_guide_sections where location_guide_id = (select id from location_guides where slug = 'launching-pei');
delete from location_guide_spots where location_guide_id = (select id from location_guides where slug = 'launching-pei');
delete from location_guide_sources where location_guide_id = (select id from location_guides where slug = 'launching-pei');
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 0, 'Striped Bass', '**Where near Launching**: River mouths and current seams at the Three Rivers/Georgetown Harbour outlet, the Boughton River mouth into Boughton Bay, and the Panmure Island surf side on a moving tide.

**Key pattern**: Follow the current and the baitfish (smelt, gaspereau, small eels are key forage). Find strong tidal current holding baitfish and you''ll find bass. Low light (dawn, dusk, after dark within legal hours) is consistently the best window.

**Best lures & retrieves**: bucktail jig (1/2-1 oz) cast across current and swum near bottom; soft plastic paddletail cast down-and-across and swung on a falling tide; topwater plug/popper low-light only; casting spoon (3/4 oz+) for long searching casts. **Best bait**: live or fresh-cut mackerel, gaspereau/alewife, and eels on a bottom or float rig.

**Gear fit**: MH rod, 20 lb braid / 20 lb fluoro leader.', 'striped-bass', '[{"label":"DFO 2026 Striped Bass Notice","url":"https://www.glf.dfo-mpo.gc.ca/en/striped-bass-recreational-fishery-southern-gulf-st-lawrence-2026"},{"label":"timberandfins.com, Chasing Striped Bass on PEI","url":"https://timberandfins.com/blogs/fish-stories/chasing-striped-bass-on-pei"}]'::jsonb);
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 1, 'Atlantic Mackerel', '**Where near Launching**: Any wharf, breakwater, or beach with tidal current — the Georgetown wharf area and the Panmure Island causeway are both worth checking. Mackerel arrive close to shore mainly from August into fall. **Best lures**: sabiki/feather rig jigged slowly; small shiny casting spoon fast and steady; small metal jig at varied depths. **Gear fit**: ML rod, 20 lb braid / 12 lb mono.', 'atlantic-mackerel', '[{"label":"thejighead.com, 19 Different Fish Species to Fish for on PEI","url":"https://thejighead.com/2017/03/11/19-different-fish-species-to-fish-for-on-prince-edward-island/"}]'::jsonb);
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 2, 'Winter Flounder', '**Where near Launching**: Sandy/muddy estuary bottom — Boughton Bay shallows and the Georgetown/Three Rivers estuary mouth are classic flounder water. **Rig**: hi-lo bottom rig tipped with clam strips, squid strips, sandworms, or scented soft plastics, cast out and retrieved slowly with frequent pauses — bites are subtle nibbles.', 'winter-flounder', '[{"label":"Salt Water Sportsman, Winter Flounder Fishing Tips","url":"https://www.saltwatersportsman.com/"}]'::jsonb);
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 3, 'Rainbow Smelt', '**Where near Launching**: Estuary shallows and river mouths, e.g. Boughton River — mainly a spring spawning-run fish, present through the season near structure in summer. **Method**: locate a school and target its edge with a tiny bucktail jighead or small streamer fly, retrieved steadily — takes usually happen as the lure leaves the school.', 'rainbow-smelt', '[]'::jsonb);
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 4, 'Gaspereau (Alewife)', '**Where near Launching**: River mouths and lower estuary stretches, especially the Boughton and Three Rivers system — they run upriver a few weeks after the smelt run (typically May), with stragglers into summer near estuary mouths. Strong fighters for their size, prone to jumping when hooked. **Method**: small white streamer fly (size 8-12) swung with a swift consistent pace. Not good table fare — plan to release.', 'gaspereau', '[]'::jsonb);
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 5, 'White Perch', '**Where near Launching**: Estuaries and any barrier-beach ponds in the area — not fussy about habitat. A consistent, high-action producer once located. **Method**: small spinner at a steady moderate pace, or a float/bobber rig with bait.', 'white-perch', '[]'::jsonb);
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 6, 'American Eel', '**Where near Launching**: Estuaries throughout the area hold large eel populations — Boughton Bay and the Three Rivers system both qualify. Eels hunt almost entirely by smell — lures/flies are largely ineffective. **Method**: cut fish, worms, or other scented bait fished directly on the bottom, and wait.', 'american-eel', '[]'::jsonb);
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 7, 'Cunner (Bergall)', '**Where near Launching**: Around docks, wharves, and piers — Georgetown''s waterfront is a good bet. Aggressive, opportunistic, and very good at stealing bait — reliably easy, fun species. **Method**: drop a small bait rig straight down beside pilings/rocks.', 'cunner', '[]'::jsonb);
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 8, 'Tomcod & Sculpin', '**Where near Launching**: Deeper estuary water — often caught incidentally while targeting winter flounder in the Boughton Bay/Three Rivers estuary. Tomcod max around 6 in / 15 cm — treat as bonus catches on flounder gear. Sculpin share the same shallow estuary bottom and make a fun sight-fishing target in clear water.', 'atlantic-tomcod', '[{"label":"DFO Maritimes Region recreational fisheries page","url":"https://www.dfo-mpo.gc.ca/fisheries-peches/recreational-recreative/maritimes/index-eng.html"}]'::jsonb);
insert into location_guide_sections (location_guide_id, position, heading, body_md, species_slug, sources) values ((select id from location_guides where slug = 'launching-pei'), 9, 'Sea-Run Brook Trout (freshwater bonus option)', '**Where near Launching**: Boughton River (the nearest system) and other estuary-connected rivers across PEI. Requires a valid PEI angling licence — an inland-water fishery, separate from the tidal saltwater species above. Best May-early July as sea-run fish gorge on estuary baitfish and shrimp; by August the push has typically passed.', 'brook-trout', '[]'::jsonb);
insert into location_guide_spots (location_guide_id, position, name, description, map_url) values ((select id from location_guides where slug = 'launching-pei'), 0, 'Launching Harbour / Boughton Bay shoreline', 'The water immediately in front of Launching; current-driven striper and flounder water, especially near the harbour mouth.', 'https://www.google.com/maps?q=46.20,-62.40');
insert into location_guide_spots (location_guide_id, position, name, description, map_url) values ((select id from location_guides where slug = 'launching-pei'), 1, 'Boughton River mouth', 'Estuary system flowing into Boughton Bay; good for striped bass, flounder, gaspereau, and smelt near the outflow.', 'https://www.google.com/maps/search/?api=1&query=Boughton+River+Prince+Edward+Island');
insert into location_guide_spots (location_guide_id, position, name, description, map_url) values ((select id from location_guides where slug = 'launching-pei'), 2, 'Georgetown Harbour / Three Rivers mouth', 'Where the Brudenell, Cardigan, and Montague Rivers converge into Cardigan Bay; one of PEI''s best-known striper systems, plus good wharf fishing for mackerel and cunner.', 'https://www.google.com/maps?q=46.18459,-62.53362');
insert into location_guide_spots (location_guide_id, position, name, description, map_url) values ((select id from location_guides where slug = 'launching-pei'), 3, 'Panmure Island Provincial Park', 'Two distinct waters off one causeway: the sheltered St. Mary''s Bay side (calmer, good for flounder/perch) and the open ocean/surf side (better for stripers and mackerel on a moving tide).', 'https://www.google.com/maps?q=46.14111,-62.48556');
insert into location_guide_spots (location_guide_id, position, name, description, map_url) values ((select id from location_guides where slug = 'launching-pei'), 4, 'Cardigan River estuary', 'A bit further out, but a known producer for mackerel and flounder.', 'https://www.google.com/maps/search/?api=1&query=Cardigan+River+Prince+Edward+Island');
